entry.string:
enum common_proposal_type {

    // Economy chain
    ec_cluster_create,
    ec_cluster_change_tag,
    ec_tag_create,
    ec_tag_update,
    ec_tag_remove,
    ec_constants_update,
    ec_voter_set_update,
    ec_mint,
}

enum common_proposal_state {
    PENDING, APPROVED, REJECTED, REVOKED
}

entity common_proposal {
    index timestamp, proposal_type: common_proposal_type;
    proposed_by: pubkey;
    index voter_set: common_voter_set;
    description: integer;
    transaction = op_context.transaction;
    mutable state: common_proposal_state = common_proposal_state.PENDING;
}

entity common_voter_set {
    key name;
    mutable threshold: integer = 0;
}

entity common_voter_set_governance {
    key voter_set: common_voter_set;
    mutable governor: common_voter_set;
}

entity common_voter_set_member {
    key voter_set: common_voter_set, pubkey;
}

entity common_vote {
    key proposal: common_proposal, pubkey;
    vote: boolean;
}

// This is a generic proposal and voting module using pubkeys instead of provider entities

module;

function create_common_voter_set_internal(name, threshold: integer = 0, governor: common_voter_set? = null) {
    val vs = create common_voter_set(name, threshold);
    if (exists(governor)) {
        create common_voter_set_governance(voter_set = vs, governor = governor);
    } else {
        create common_voter_set_governance(voter_set = vs, governor = vs);
    }
    return vs;
}

@extendable function delete_common_proposal_handlers(): map<text, (common_proposal) -> unit>;

@extendable function apply_common_voting_result_handlers(): map<text, (common_proposal) -> unit>;

function delete_common_proposal(common_proposal) = run_common_proposal_event(delete_common_proposal_handlers(), common_proposal);

function apply_common_voting_result(common_proposal) = run_common_proposal_event(apply_common_voting_result_handlers(), common_proposal);

function run_common_proposal_event(handlers: map<text, (common_proposal) -> unit>, proposal: common_proposal) {
    if (handlers.contains(proposal.proposal_type.name)) {
        handlers[proposal.proposal_type.name](proposal);
    }
}

operation make_common_vote(pubkey, proposal_id: rowid, vote: boolean) {
    require_is_signer(pubkey);
    val prop = require_common_proposal(proposal_id);
    require(prop.state == common_proposal_state.PENDING, "The proposal is already closed as %s".format(prop.state));
    require_common_voter_set_member(prop.voter_set, pubkey);
    require(empty(common_vote @? {prop, pubkey}), "Only one vote per pubkey is allowed");
    internal_common_vote(pubkey, prop, vote);
}

operation revoke_common_proposal(pubkey, proposal_id: rowid) {
    require_is_signer(pubkey);
    val prop = common_proposal @? { proposal_id };
    require(prop, "Proposal not found: %d".format(proposal_id));
    require(prop.proposed_by == pubkey, "It is only allowed to revoke own proposals");
    prop.state = common_proposal_state.REVOKED;
    delete_common_proposal(prop);
}

struct common_proposal_voting_results {
    positive_votes: integer;
    negative_votes: integer;
    max_votes: integer;
    threshold: integer;
    voting_result: common_voting_result;
}

struct common_proposal_voter {
    pubkey: byte_array;
    vote: boolean;
}

query get_common_proposals_range(from: timestamp, until: timestamp, only_pending: boolean) {
    return common_proposal @* {
        .timestamp >= from,
        .timestamp <= until,
        not(only_pending) or .state == common_proposal_state.PENDING
    } (.rowid, proposal_type = .proposal_type, .state);
}

query get_relevant_common_proposals(from: timestamp, until: timestamp, only_pending: boolean, my_pubkey: pubkey) {
    return (common_proposal, common_voter_set_member) @* {
        common_voter_set_member.voter_set == common_proposal.voter_set,
        common_voter_set_member.pubkey == my_pubkey,
        common_proposal.timestamp >= from,
        common_proposal.timestamp <= until,
        not(only_pending) or common_proposal.state == common_proposal_state.PENDING
    } (common_proposal.rowid, proposal_type = common_proposal.proposal_type, common_proposal.state);
}

query get_common_proposal(id: rowid?): (id: rowid, timestamp: integer, type: common_proposal_type, proposed_by: pubkey, description: text, state: common_proposal_state)? {
    val result = if (id == null) common_proposal @? {} (@sort_desc @omit .rowid, $) limit 1 else common_proposal @? { id };
    if (result == null) return null;
    return (
        id = result.rowid,
        timestamp = result.timestamp,
        type = result.proposal_type,
        proposed_by = result.proposed_by,
        description = "result.description",
        state = result.state
    );
}

query get_common_proposal_voting_results(rowid): common_proposal_voting_results {
    val proposal = require_common_proposal(rowid);
    require(proposal.state == common_proposal_state.PENDING, "This proposal is closed as %s. For info about voting use get_proposal_voter_info query.".format(proposal.state));
    val positive_votes = positive_common_votes(proposal);
    val negative_votes = negative_common_votes(proposal);
    val max_votes = max_common_votes(proposal.voter_set);
    val threshold = proposal.voter_set.threshold;
    val status = _compute_common_voting_result(positive_votes, negative_votes, max_votes, threshold);
    return common_proposal_voting_results(positive_votes, negative_votes, max_votes, threshold, status);
}

query get_common_proposal_voter_info(rowid): list<common_proposal_voter> {
    val proposal = require_common_proposal(rowid);
    return common_vote @* { .proposal.rowid == rowid } (common_proposal_voter(.pubkey, .vote));
}

query get_common_pubkey_votes(from: timestamp, until: timestamp, pubkey) {
    return (common_proposal, common_vote) @* {
        common_vote.pubkey == pubkey,
        common_vote.proposal == common_proposal,
        common_proposal.timestamp >= from,
        common_proposal.timestamp <= until
    } ( .proposal, .vote );
}

function require_common_proposal(rowid) = require(common_proposal @? { rowid }, "Proposal " + rowid + " not found");

function require_common_voter_set(name) = require(common_voter_set @? { name }, "Voter set %s does not exist".format(name));

function require_common_voter_set_member(common_voter_set, pubkey) {
    require(exists(common_voter_set_member @* { common_voter_set, pubkey}), "Voter is not a member of voter set " + common_voter_set.name);
}

function require_common_voter_set_governor(common_voter_set, pubkey) {
    val governor = common_voter_set_governance @ { .voter_set == common_voter_set } .governor;
    require_common_voter_set_member(governor, pubkey);
}

function require_is_signer(pubkey) {
    require(op_context.is_signer(pubkey), "Operation must be signed by " + pubkey);
}

function require_signer_member_of_voter_set(voter_set: common_voter_set) =
    require(not(empty(common_voter_set_member @* { voter_set, .pubkey in op_context.get_signers() })), "Signer is not a member of voter set %s".format(voter_set.name));

enum common_voting_result {
    pending,
    approved,
    rejected
}

namespace consensus_threshold {
    val majority = -1;
    val super_majority = 0;
}

function positive_common_votes(common_proposal) = common_vote @? { common_proposal, .vote == true } (@sum 1) ?: 0;
function negative_common_votes(common_proposal) = common_vote @? { common_proposal, .vote == false } (@sum 1) ?: 0;
function max_common_votes(common_voter_set) = common_voter_set_member @ { common_voter_set } (@sum 1);

function _compute_common_voting_result(yes: integer, no: integer, max: integer, threshold: integer): common_voting_result {
    require (threshold >= -1 and threshold <= max, "Invalid threshold, must be in range [%d, %d] but was: %d".format(-1, max, threshold));
    require (yes + no <= max, "Too many votes");
    when (threshold) {
        -1 -> return _compute_common_voting_result_majority(yes, no, max);
        0 -> return _compute_common_voting_result_super_majority(yes, no, max);
        else -> return _compute_common_voting_result_custom(yes, no, max, threshold);
    }
}

function _compute_common_voting_result_custom(yes: integer, no: integer, max: integer, threshold: integer): common_voting_result {
    return _common_voting_result(yes, no, max, threshold);
}

function _compute_common_voting_result_majority(yes: integer, no: integer, max: integer): common_voting_result {
    val required = max / 2 + 1;
    return _common_voting_result(yes, no, max, required);
}

function _compute_common_voting_result_super_majority(yes: integer, no: integer, max: integer): common_voting_result {
    val required = max - (max - 1) / 3;
    return _common_voting_result(yes, no, max, required);
}

function _common_voting_result(yes: integer, no: integer, max: integer, required: integer): common_voting_result {
    log("Votes - positive: %d, negative: %d, required: %d, maximum: %d".format(yes, no, required, max));
    return when {
        yes >= required -> common_voting_result.approved;
        no > max - required -> common_voting_result.rejected;
        else -> common_voting_result.pending;
    };
}

function internal_common_vote(pubkey, proposal: common_proposal, vote: boolean) {
    require(common_voter_set_member @? { proposal.voter_set, pubkey }, pubkey + " must be a member of the voter set");
    create common_vote(proposal, pubkey, vote);
    log("vote '%s' added for proposal %s".format(if (vote) "Yes" else "No", proposal_str(proposal)));
    try_to_apply_proposal(proposal);
}

function try_to_apply_proposal(prop: common_proposal) {
    val prop_str = proposal_str(prop);
    val results = get_common_proposal_voting_results(prop.rowid);
    when (results.voting_result) {
        pending -> log("proposal is still under discussion:", prop_str);
        rejected -> {
            log("proposal rejected:", prop_str);
            prop.state = common_proposal_state.REJECTED;
            delete_common_proposal(prop);
        }
        approved -> {
            log("proposal approved:", prop_str);
            prop.state = common_proposal_state.APPROVED;
            apply_common_voting_result(prop);
            delete_common_proposal(prop);
        }
    }
}

@extendable function proposal_str(prop: common_proposal): text? = "%s:%d".format(prop.proposal_type, prop.rowid);

module;

namespace blockchains {
    val directory_chain = "directory_chain";
    val system_anchoring = "system_anchoring";
    val evm_event_receiver_chain = "evm_event_receiver_chain";
    val evm_transaction_submitter_chain = "evm_transaction_submitter_chain";
    val cluster_anchoring_prefix = "cluster_anchoring_";
    val price_oracle_chain_name = "price_oracle_chain";
}

function register_provider_account(provider) {

    if (provider_account @? { provider } == null) {

        val auth_descriptor = ft4.accounts.single_sig_auth_descriptor(provider.pubkey, set(["A", "T"]));
        val account = ft4.accounts.create_account_with_auth(auth_descriptor);

        create provider_account(provider, account);
    }
}

function register_account_impl(pubkey) {
    require_admin();

    val auth_descriptor = ft4.accounts.single_sig_auth_descriptor(pubkey, set(["A", "T"]));

    before_account_registration(auth_descriptor);
    val account = ft4.accounts.create_account_with_auth(auth_descriptor);
    after_account_registration(account, auth_descriptor);
}

@extend(auth.before_account_registration) function(ft4.accounts.auth_descriptor, ft4.auth.signature) {
    before_account_registration(auth_descriptor);
}

function before_account_registration(ft4.accounts.auth_descriptor) {
    require_initialized();
}

@extend(auth.after_account_registration) function(ft4.accounts.account, ft4.accounts.auth_descriptor, ft4.auth.signature) {
    after_account_registration(account, auth_descriptor);
}

function after_account_registration(ft4.accounts.account, ft4.accounts.auth_descriptor) {
    log("Account created: %s".format(account.id));

    ft4.assets.Unsafe.mint(account, get_asset(), chain_context.args.amount_to_mint);

    create user(account = account, last_refill_millis = op_context.last_block_time);
}

function get_account_balance(ft4.accounts.account): big_integer =
        (ft4.assets.balance @? { account, get_asset() }.amount) ?: 0L;

function get_asset(): ft4.assets.asset {
    val asset_id = (chain_context.args.asset_name, chain_context.blockchain_rid).hash();
    return ft4.assets.asset @ { .id == asset_id };
}

function create_pool_account(): ft4.accounts.account {
    return ft4.accounts.create_account_with_auth(get_pool_account_auth_descriptor());
}

function get_pool_account() = ft4.accounts.account_by_id(get_pool_account_id());

function get_pool_account_auth_descriptor() = ft4.accounts.single_sig_auth_descriptor(chain_context.args.pool_account_pubkey, set(["A", "T"]));

function get_pool_account_id() = chain_context.args.pool_account_pubkey.hash();

function create_deposit_account(): ft4.accounts.account {
    return ft4.accounts.create_account_with_auth(get_deposit_account_auth_descriptor());
}

function get_deposit_account() = ft4.accounts.account_by_id(get_deposit_account_id());

function get_deposit_account_id() = chain_context.args.deposit_account_pubkey.hash();

function get_deposit_account_auth_descriptor() = ft4.accounts.single_sig_auth_descriptor(chain_context.args.deposit_account_pubkey, set(["A", "T"]));


function create_chromia_foundation_account(): ft4.accounts.account {
    return ft4.accounts.create_account_with_auth(get_chromia_foundation_account_auth_descriptor());
}

function get_chromia_foundation_account() = ft4.accounts.account_by_id(get_get_chromia_foundation_account_id());

function get_get_chromia_foundation_account_id() = chain_context.args.chromia_foundation_account_pubkey.hash();

function get_chromia_foundation_account_auth_descriptor() = ft4.accounts.single_sig_auth_descriptor(chain_context.args.chromia_foundation_account_pubkey, set(["A", "T"]));

function register_assets() {
    return ft4.assets.Unsafe.register_asset(
        chain_context.args.asset_name,
        chain_context.args.asset_symbol,
        chain_context.args.asset_decimals,
        chain_context.blockchain_rid,
        chain_context.args.asset_icon
    );
}

query get_ft4_account_ids() {
    return [
        "pool_account_id": get_pool_account().id,
        "chromia_foundation_account_id": get_chromia_foundation_account().id
    ];
}

// TODO: For now bridge leases are free (with a max cap) as long as you have a container lease but we should add some payment logic for these leases as well

@extend(ft4.auth.auth_handler)
function () = ft4.auth.add_auth_handler(
    scope = "add_bridge_lease",
    flags = ["T"],
    message = add_bridge_lease_auth_message(*)
);

function add_bridge_lease_auth_message(gtv) {
    val args = struct<add_bridge_lease>.from_gtv(gtv);
    return "Please sign the message\nto add a bridge lease to container lease %s\nfor blockchain %s and validator contract %s on network %s\n".format(
        args.container_name,
        args.blockchain_rid,
        args.validator_contract,
        args.evm_network_id
    );
}

// We don't really know if this chain belongs to the container but it should not really matter
function add_bridge_lease_impl(container_name: text, blockchain_rid: byte_array, evm_network_id: integer, validator_contract: text, bridge_contract: text, initial_signers: list<byte_array>, anomaly_detection: boolean) {
    val lease = require_lease(container_name);
    require(not lease.expired, "Container lease is expired");

    val account = ft4.auth.authenticate();
    require(user @? { account }, "No user for account %s".format(account.id));
    require(lease.account == account, "Lease for container %s was not created by you".format(container_name));
    require((bridge_lease @* { lease }).size() < chain_context.args.max_bridge_leases_per_container, "Container lease already has max amount of bridge leases");

    create bridge_lease(blockchain_rid, evm_network_id, lease, validator_contract, bridge_contract, anomaly_detection);

    send_message(bridge_mapping_topic, bridge_mapping_message(
        blockchain_rid = blockchain_rid,
        validator_contract = validator_contract,
        bridge_contract = bridge_contract,
        evm_network_id = evm_network_id,
        deleted = false,
        signers = initial_signers.to_gtv().to_bytes()
    ).to_gtv());
}

@extend(ft4.auth.auth_handler)
function () = ft4.auth.add_auth_handler(
    scope = "update_bridge_lease",
    flags = ["T"],
    message = update_bridge_lease_auth_message(*)
);

function update_bridge_lease_auth_message(gtv) {
    val args = struct<update_bridge_lease>.from_gtv(gtv);
    return "Please sign the message\nto update bridge lease\nfor blockchain %s on network %s\n".format(
        args.blockchain_rid,
        args.evm_network_id
    );
}

function update_bridge_lease_impl(blockchain_rid: byte_array, evm_network_id: integer, updated_validator_contract: text?, updated_bridge_contract: text?, updated_signers: list<byte_array>?, anomaly_detection: boolean?) {
    val bridge_lease = bridge_lease @? { .blockchain_rid == blockchain_rid, .evm_network_id == evm_network_id};
    require(bridge_lease, "No bridge lease found");
    require(not bridge_lease.lease.expired, "Container lease is expired");

    require(updated_validator_contract != null or updated_signers != null or updated_bridge_contract != null, "Must update contract or signers");

    val account = ft4.auth.authenticate();
    require(user @? { account }, "No user for account %s".format(account.id));
    require(bridge_lease.lease.account == account, "Lease for container %s was not created by you".format(bridge_lease.lease.container_name));

    if (updated_validator_contract != null) bridge_lease.validator_contract = updated_validator_contract;
    if (updated_bridge_contract != null) bridge_lease.bridge_contract = updated_bridge_contract;
    if (anomaly_detection != null) bridge_lease.anomaly_detection = anomaly_detection;

    send_message(bridge_mapping_topic, bridge_mapping_message(
        blockchain_rid = blockchain_rid,
        validator_contract = bridge_lease.validator_contract,
        bridge_contract = bridge_lease.bridge_contract,
        evm_network_id = evm_network_id,
        deleted = false,
        signers = updated_signers?.to_gtv()?.to_bytes()
    ).to_gtv());
}

@extend(ft4.auth.auth_handler)
function () = ft4.auth.add_auth_handler(
    scope = "remove_bridge_lease",
    flags = ["T"],
    message = remove_bridge_lease_auth_message(*)
);

function remove_bridge_lease_auth_message(gtv) {
    val args = struct<remove_bridge_lease>.from_gtv(gtv);
    return "Please sign the message\nto remove bridge lease\nfor blockchain %s on network %s\n".format(
        args.blockchain_rid,
        args.evm_network_id
    );
}

function remove_bridge_lease_impl(blockchain_rid: byte_array, evm_network_id: integer) {
    val bridge_lease = bridge_lease @? { .blockchain_rid == blockchain_rid, .evm_network_id == evm_network_id};
    require(bridge_lease, "No bridge lease found");

    val account = ft4.auth.authenticate();
    require(user @? { account }, "No user for account %s".format(account.id));
    require(bridge_lease.lease.account == account, "Lease for container %s was not created by you".format(bridge_lease.lease.container_name));

    send_bridge_lease_deleted_message(bridge_lease);

    delete bridge_lease;
}

function delete_bridge_leases(lease): list<struct<bridge_lease>> {
    val bridge_leases = bridge_lease @* { lease };
    val deleted_leases = list<struct<bridge_lease>>();

    for (bridge_lease in bridge_leases) {
        send_bridge_lease_deleted_message(bridge_lease);
        deleted_leases.add(bridge_lease.to_struct());
        delete bridge_lease;
    }

    return deleted_leases;
}

@extend(on_lease_expired) function expire_bridge_leases(lease) {
    val bridge_leases = bridge_lease @* { lease };

    for (bridge_lease in bridge_leases) {
        send_bridge_lease_deleted_message(bridge_lease);
    }
}

@extend(on_lease_resurrected) function restore_expired_bridge_leases(lease) {
    val bridge_leases = bridge_lease @* { lease };

    for (bridge_lease in bridge_leases) {
        send_message(bridge_mapping_topic, bridge_mapping_message(
            blockchain_rid = bridge_lease.blockchain_rid,
            validator_contract = bridge_lease.validator_contract,
            bridge_contract = bridge_lease.bridge_contract,
            evm_network_id = bridge_lease.evm_network_id,
            deleted = false,
            signers = null
        ).to_gtv());
    }
}

function transfer_bridge_leases_to_lease(lease, bridge_leases: list<struct<bridge_lease>>) {
    for (bridge_lease in bridge_leases) {
        create bridge_lease(
            blockchain_rid = bridge_lease.blockchain_rid,
            evm_network_id = bridge_lease.evm_network_id,
            lease = lease,
            validator_contract = bridge_lease.validator_contract,
            bridge_contract = bridge_lease.bridge_contract,
            anomaly_detection = bridge_lease.anomaly_detection
        );
    }
}

function send_bridge_lease_deleted_message(bridge_lease) {
    send_message(bridge_mapping_topic, bridge_mapping_message(
        blockchain_rid = bridge_lease.blockchain_rid,
        validator_contract = bridge_lease.validator_contract,
        bridge_contract = bridge_lease.bridge_contract,
        evm_network_id = bridge_lease.evm_network_id,
        deleted = true,
        signers = null
    ).to_gtv());
}

function receive_create_cluster_error_message(body: gtv) {
    val create_cluster_error_message = create_cluster_error_message.from_gtv(body);
    val pending_cluster = pending_cluster @ { .name == create_cluster_error_message.name };
    pending_cluster.status = pending_cluster_status.FAILURE;
}

function expire_leases(current_time_millis: integer) {
    for (lease in lease @* { current_time_millis > .start_time + .duration_millis, .expired == false }) {
        // Don't touch leases for containers that are currently being upgraded
        if (not has_pending_upgrade(lease.container_name)) {
            maybe_expire_lease(lease);
        }
    }
}

function maybe_expire_lease(lease) {
    if (lease.auto_renew) {
        log("Auto-renewing lease for container %s".format(lease.container_name));
        val success = try_call(renew_container_lease(lease.account, lease, 1, *));
        if (not success) {
            log("Unable to auto-renew lease for container %s".format(lease.container_name));
            expire_lease(lease);
        }
    } else {
        expire_lease(lease);
    }
}

function expire_lease(lease) {
    lease.expired = true;
    log("Lease for container %s has expired, stopping it".format(lease.container_name));
    send_message(stop_container_topic, stop_container_message(container_name = lease.container_name).to_gtv()); // fire-and-forget
    on_lease_expired(lease);
}

@extendable function on_lease_expired(lease) {}

@extend(ft4.auth.auth_handler)
function () = ft4.auth.add_auth_handler(
    scope = "create_container",
    flags = ["T"],
    message = create_container_auth_message(*)
);

function create_container_auth_message(gtv): text {
    val args = struct<create_container>.from_gtv(gtv);
    val tag = require_cluster(args.cluster_name).tag;
    val cost = calculate_container_cost(args.duration_weeks, args.container_units, args.extra_storage_gib, tag);
    return "Please sign the message\nto lease container with %s SCUs and %s GiB extra storage\nin cluster %s\nfor %s weeks\ncosting %s %s\n%son account {account_id}".format(
        args.container_units,
        args.extra_storage_gib,
        args.cluster_name,
        args.duration_weeks,
        ft4.assets.format_amount_with_decimals(cost, chain_context.args.asset_decimals),
        chain_context.args.asset_symbol,
        if (args.auto_renew) "with auto-renewal\n" else "");
}

function create_container_impl(
    provider_pubkey: pubkey,
    container_units: integer,
    duration_weeks: integer,
    extra_storage_gib: integer,
    cluster_name: text,
    auto_renew: boolean) {

    require_initialized();
    require_pubkey(provider_pubkey);
    require(container_units > 0, "container_units must be positive");
    require_lease_duration(duration_weeks);
    require(extra_storage_gib > -1, "extra_storage_gib must not be negative");
    require_dapp_cluster(cluster_name);

    val cluster = require_cluster(cluster_name);
    val account = ft4.auth.authenticate();
    ft4.accounts.Account(account.id);

    val cost = calculate_container_cost(duration_weeks, container_units, extra_storage_gib, cluster.tag);
    ft4.assets.Unsafe.transfer(account, get_pool_account(), get_asset(), cost);

    val ticket = create ticket(type = ticket_type.CREATE_CONTAINER, account);
    create create_container_ticket(ticket,
        container_units = container_units,
        extra_storage_gib = extra_storage_gib,
        duration_millis = duration_weeks * millis_per_week,
        cost = cost,
        auto_renew = auto_renew,
        cluster_name = cluster.name
    );
    send_message(create_container_topic, create_container_message(
        ticket_id = ticket.rowid.to_integer(),
        provider_pubkey = provider_pubkey,
        container_units = container_units,
        extra_storage = 1024 * extra_storage_gib,
        cluster_name = cluster_name
    ).to_gtv());
}

@extend(ft4.auth.auth_handler)
function () = ft4.auth.add_auth_handler(
    scope = "upgrade_container",
    flags = ["T"],
    message = upgrade_container_auth_message(*)
);

function upgrade_container_auth_message(gtv): text {
    val args = struct<upgrade_container>.from_gtv(gtv);
    val lease = require_lease(args.container_name);
    val lease_duration_in_weeks = lease.duration_millis / millis_per_week;
    val tag = require_cluster(args.upgraded_cluster_name).tag;
    val cost = calculate_container_cost(lease_duration_in_weeks, args.upgraded_container_units, args.upgraded_extra_storage_gib, tag);
    return "Please sign the message\nto upgrade container %s\nto have %s SCUs and %s GiB extra storage\nin cluster %s\nfor %s weeks\ncosting (before applying refund of current lease) %s %s\non account {account_id}".format(
        args.container_name,
        args.upgraded_container_units,
        args.upgraded_extra_storage_gib,
        args.upgraded_cluster_name,
        lease_duration_in_weeks,
        ft4.assets.format_amount_with_decimals(cost, chain_context.args.asset_decimals),
        chain_context.args.asset_symbol
    );
}

function upgrade_container_impl(
    container_name: text,
    upgraded_container_units: integer,
    upgraded_extra_storage_gib: integer,
    upgraded_cluster_name: text
) {
    require_initialized();
    val lease = require_lease(container_name);
    require(not has_pending_upgrade(container_name), "Container already has a pending upgrade");
    require(
        upgraded_container_units != lease.container_units or upgraded_extra_storage_gib != lease.extra_storage_gib,
        "New container specifications are identical to current lease"
    );
    require(upgraded_container_units >= lease.container_units, "new_container_units must be greater or equal to current lease");
    require(upgraded_extra_storage_gib >= lease.extra_storage_gib, "extra_storage_gib must be greater or equal to current lease");
    require_dapp_cluster(upgraded_cluster_name);

    val account = ft4.auth.authenticate();
    ft4.accounts.Account(account.id);
    require(lease.account == account, "Lease for container %s was not created by you".format(container_name));

    val cluster = require_cluster(upgraded_cluster_name);

    val cost = calculate_container_cost(lease.duration_millis / millis_per_week, upgraded_container_units, upgraded_extra_storage_gib, cluster.tag)
    - if (lease.expired) 0 else calculate_remaining_lease_value(lease, op_context.last_block_time);
    ft4.assets.Unsafe.transfer(account, get_pool_account(), get_asset(), cost);

    val ticket = create ticket(type = ticket_type.UPGRADE_CONTAINER, account);
    create upgrade_container_ticket(ticket,
        container_name = container_name,
        container_units = upgraded_container_units,
        extra_storage_gib = upgraded_extra_storage_gib,
        cost = cost,
        cluster_name = cluster.name
    );
    send_message(upgrade_container_topic, upgrade_container_message(
        ticket_id = ticket.rowid.to_integer(),
        container_name = container_name,
        container_units = upgraded_container_units,
        extra_storage = 1024 * upgraded_extra_storage_gib,
        cluster_name = upgraded_cluster_name
    ).to_gtv());
}

@extend(ft4.auth.auth_handler)
function () = ft4.auth.add_auth_handler(
    scope = "renew_container",
    flags = ["T"],
    message = renew_container_auth_message(*)
);

function renew_container_auth_message(gtv): text {
    val args = struct<renew_container>.from_gtv(gtv);

    val lease = require_lease(args.container_name);
    val tag = lease.cluster.tag;
    val cost = calculate_container_cost(args.duration_weeks, lease.container_units, lease.extra_storage_gib, tag);

    return "Please sign the message\nto renew lease of container %s\nfor %s weeks\ncosting %s %s\non account {account_id}".format(
        args.container_name,
        args.duration_weeks,
        ft4.assets.format_amount_with_decimals(cost, chain_context.args.asset_decimals),
        chain_context.args.asset_symbol);
}

function renew_container_impl(container_name: text, duration_weeks: integer) {
    require_initialized();
    require_lease_duration(duration_weeks);

    val account = ft4.auth.authenticate();
    ft4.accounts.Account(account.id);

    val lease = require_lease(container_name);

    renew_container_lease(account, lease, duration_weeks);
    if (lease.expired) {
        restart_container(lease);
    }
}

@extend(ft4.auth.auth_handler)
function () = ft4.auth.add_auth_handler(
    scope = "auto_renew_container",
    flags = ["T"],
    message = auto_renew_container_auth_message(*)
);

function auto_renew_container_auth_message(gtv): text {
    val args = struct<auto_renew_container>.from_gtv(gtv);

    val lease = require_lease(args.container_name);
    val tag = lease.cluster.tag;
    val weekly_cost = calculate_container_cost(1, lease.container_units, lease.extra_storage_gib, tag);

    return "Please sign the message\nto enable auto-renewal of container %s\ncosting %s %s per week\non account {account_id}".format(
        args.container_name,
        ft4.assets.format_amount_with_decimals(weekly_cost, chain_context.args.asset_decimals),
        chain_context.args.asset_symbol);
}

function auto_renew_container_impl(container_name: text) {
    require_initialized();

    val account = ft4.auth.authenticate();
    ft4.accounts.Account(account.id);

    val lease = require_lease(container_name);
    require(lease.account == account, "Lease for container %s was not created by you".format(container_name));
    require(lease.auto_renew == false, "Container %s is already auto-renewing".format(container_name));

    lease.auto_renew = true;

    if (lease.expired) {
        renew_container_lease(account, lease, 1);
        restart_container(lease);
    }
}

@extend(ft4.auth.auth_handler)
function () = ft4.auth.add_auth_handler(
    scope = "cancel_renew_container",
    flags = ["T"],
    message = cancel_renew_container_auth_message(*)
);

function cancel_renew_container_auth_message(gtv): text {
    val args = struct<cancel_renew_container>.from_gtv(gtv);

    val lease = require_lease(args.container_name);

    return "Please sign the message\nto cancel auto-renewal of container %s\non account {account_id}".format(
        args.container_name);
}

function cancel_renew_container_impl(container_name: text) {
    require_initialized();

    val account = ft4.auth.authenticate();
    ft4.accounts.Account(account.id);

    val lease = require_lease(container_name);
    require(lease.account == account, "Lease for container %s was not created by you".format(container_name));
    require(lease.auto_renew == true, "Container %s is not auto-renewing".format(container_name));

    lease.auto_renew = false;
}

function renew_container_lease(ft4.accounts.account, lease, duration_weeks: integer) {
    val tag = lease.cluster.tag;
    val cost = calculate_container_cost(duration_weeks, lease.container_units, lease.extra_storage_gib, tag);
    ft4.assets.Unsafe.transfer(account, get_pool_account(), get_asset(), cost);
    lease.duration_millis += duration_weeks * millis_per_week;
}

function restart_container(lease) {
    log("Lease for container %s was expired, restarting it".format(lease.container_name));
    send_message(restart_container_topic, restart_container_message(container_name = lease.container_name).to_gtv()); // fire-and-forget
    // TODO what if restart fails?
    lease.expired = false;
    on_lease_resurrected(lease);
}

@extendable function on_lease_resurrected(lease) {}

function calculate_container_cost(duration_weeks: integer, container_units: integer, extra_storage_gib: integer, tag: tag): integer {
    val scu_cost = container_units * tag.scu_price;
    val extra_storage_cost = extra_storage_gib * tag.extra_storage_price;

    return ((scu_cost + extra_storage_cost) * 7 * duration_weeks * economy_constants.chr_per_usd * units_per_asset).to_integer();
}

function calculate_remaining_lease_value(lease, current_time: integer): integer {
    val tag = lease.cluster.tag;
    val lease_weekly_cost = calculate_container_cost(1, lease.container_units, lease.extra_storage_gib, tag);
    val remaining_lease_time = lease.start_time + lease.duration_millis - current_time;
    val remaining_weeks = decimal(remaining_lease_time) / decimal(millis_per_week);
    val remaining_value = remaining_weeks * lease_weekly_cost;
    return remaining_value.round().to_integer();
}

function refund_lease(lease: lease) {

    if (not lease.expired) {
        val lease_value = calculate_remaining_lease_value(lease, op_context.last_block_time);
        if (not try_call(ft4.assets.Unsafe.transfer(get_pool_account(), lease.account, get_asset(), lease_value, *))) {
            log("Unable to refund lease with container name %s".format(lease.container_name));
        }
    }

}

import common_proposal.*;

function receive_cluster_update_message(body: gtv) {
    val message = cluster_update_message.from_gtv(body);
    val cluster = cluster @? { .name == message.name };
    if (message.deleted) {
        if (exists(cluster)) {
            log("Deleting cluster %s".format(message.name));

            val leases = lease @* { cluster };
            for (lease in leases) {
                refund_lease(lease);
                delete_bridge_leases(lease);
                delete lease;
            }

            delete cluster_node @* { cluster };
            delete cluster_replica_node @* { cluster };
            delete cluster;
        } else {
            log("Did not have to delete cluster %s".format(message.name));
        }
    } else {
        if (exists(cluster)) {
            log("Updating cluster %s".format(message.name));
            update cluster @ { .name == message.name } (
                operational = message.operational,
                cluster_units = message.cluster_units,
                extra_storage = message.extra_storage,
                anchoring_chain = message.anchoring_chain ?: x""
            );
        } else {
            val pending_cluster = pending_cluster @? { .name == message.name };
            if (pending_cluster != null) {
                log("Creating cluster %s".format(message.name));
                create cluster(
                    name = message.name,
                    operational = message.operational,
                    cluster_units = message.cluster_units,
                    extra_storage = message.extra_storage,
                    anchoring_chain = message.anchoring_chain ?: x"",
                    tag = pending_cluster.tag
                );
                delete pending_cluster;
            } else if (message.name == system_cluster_name) {
                log("Creating system cluster");
                create cluster(
                    name = message.name,
                    operational = message.operational,
                    cluster_units = message.cluster_units,
                    extra_storage = message.extra_storage,
                    anchoring_chain = message.anchoring_chain ?: x"",
                    tag = create tag("system", scu_price = 0, extra_storage_price = 0)
                );
            } else {
                log("Received cluster that is not PENDING with name %s".format(message.name));
            }
        }
    }
}

function receive_provider_update_message(body: gtv) {
    val message = provider_update_message.from_gtv(body);
    var provider = provider @? { message.pubkey };

    if (exists(provider)) {
        log("Updating provider %s".format(message.pubkey));

        if (provider.active and not message.active) {
            val provider_account = provider_account @ {.provider == provider};
            remove_provider_handler(provider_account);
        }

        provider.system = message.system;
        provider.tier = provider_tier.value(message.tier);
        provider.active = message.active;
    } else {
        log("Creating provider %s".format(message.pubkey));
        provider = create provider(pubkey = message.pubkey,
            system = message.system,
            tier = provider_tier.value(message.tier),
            active = message.active
        );

        register_provider_account(provider);
    }

    update_system_p_vote_set(provider);
}

@extendable function remove_provider_handler(provider_account) {}

function update_system_p_vote_set(provider: provider) {

    var system_p_voter_set = common_voter_set @? { voter_sets.system_p };
    if (system_p_voter_set == null) {
        system_p_voter_set = create_common_voter_set_internal(voter_sets.system_p);
    }

    val voter_set_member = common_voter_set_member @? { system_p_voter_set, provider.pubkey };

    if (provider.system and provider.active and voter_set_member == null) {
        create common_voter_set_member(system_p_voter_set, provider.pubkey);
        revoke_proposals_for_provider_as_member(provider);
    } else if ((not provider.system or not provider.active) and voter_set_member != null) {
        revoke_proposals_for_provider_as_member(provider);
        delete voter_set_member;
    }
}

function revoke_proposals_for_provider_as_member(provider) {

    val results = (voter_set_member: common_voter_set_member, voter_set: common_voter_set, proposal: common_proposal) @* {
        voter_set_member.pubkey == provider.pubkey,
        voter_set == voter_set_member.voter_set,
        proposal.voter_set == voter_set,
        proposal.state == common_proposal_state.PENDING
    };

    for (result in results) {
        log("Revoke proposal %s due to system provider changes".format(result.proposal.rowid));
        result.proposal.state = common_proposal_state.REVOKED;
        delete_common_proposal(result.proposal);
    }
}

function receive_node_update_message(body: gtv) {
    val message = node_update_message.from_gtv(body);
    val node = node @? { message.pubkey };
    if (message.deleted) {
        if (exists(node)) {
            log("Deleting node %s".format(message.pubkey));
            delete cluster_node @* { node };
            delete cluster_replica_node @* { node };
            delete node;
        } else {
            log("Did not have to delete node %s".format(message.pubkey));
        }
    } else {
        if (exists(node)) {
            log("Updating node %s".format(message.pubkey));
            update node @ { message.pubkey } (
                active = message.active,
                territory = message.territory,
                cluster_units = message.cluster_units,
                extra_storage = message.extra_storage
            );
        } else {
            val provider = require(provider @? { message.provider_pubkey }, "Cannot add node %s due to missing provider %s".format(message.pubkey, message.provider_pubkey));
            log("Creating node %s".format(message.pubkey));
            create node(pubkey = message.pubkey,
                provider = provider,
                active = message.active,
                territory = message.territory,
                cluster_units = message.cluster_units,
                extra_storage = message.extra_storage
            );
        }
    }
}

function receive_cluster_node_update_message(body: gtv) {
    val message = cluster_node_update_message.from_gtv(body);
    val node = require(node @? { message.pubkey }, "Cannot update cluster node due to missing node %s".format(message.pubkey));
    if (message.deleted) {
        val cluster = if (exists(message.name)) require(cluster @? { .name == message.name!! }, "Cannot update cluster node due to missing cluster %s".format(message.name)) else null;
        if (message.replica_node) {
            if (exists(cluster)) {
                log("Deleting cluster_replica_node for cluster %s and node %s".format(cluster.name, node.pubkey));
                delete cluster_replica_node @ { cluster, node };
            } else {
                log("Deleting cluster_replica_node for node %s".format(node.pubkey));
                delete cluster_replica_node @* { node };
            }
        } else {
            if (exists(cluster)) {
                log("Deleting cluster_node for cluster %s and node %s".format(cluster.name, node.pubkey));
                delete cluster_node @ { cluster, node };
            } else {
                log("Deleting cluster_node for node %s".format(node.pubkey));
                delete cluster_node @* { node };
            }
        }
    } else {
        require(message.name, "Missing cluster name when updating node %s".format(message.pubkey));
        val cluster = require(cluster @? { .name == message.name!! }, "Cannot update cluster node due to missing cluster %s".format(message.name));
        if (message.replica_node) {
            val crn = cluster_replica_node @? { cluster, node };
            if (exists(crn)) {
                log("Did not create cluster_replica_node since it already exists for cluster %s and node %s".format(cluster.name, node.pubkey));
            } else {
                log("Creating cluster_replica_node for cluster %s and node %s".format(cluster.name, node.pubkey));
                create cluster_replica_node(cluster, node);
            }
        } else {
            val cn = cluster_node @? { cluster, node };
            if (exists(cn)) {
                log("Did not create cluster_node since it already exists for cluster %s and node %s".format(cluster.name, node.pubkey));
            } else {
                log("Creating cluster_node for cluster %s and node %s".format(cluster.name, node.pubkey));
                create cluster_node(cluster, node);
            }
        }
    }
}

function register_and_link_erc20_asset(ft4.assets.asset) {
	eif.hbridge.register_erc20_asset(
			chain_context.args.bsc_asset_network_id,
			chain_context.args.bsc_asset_address,
			asset,
			//Should be native for mainnet
			eif.hbridge.bridge_mode.foreign 
		);
	eif.hbridge.register_erc20_asset(
			chain_context.args.eth_asset_network_id,
			chain_context.args.eth_asset_address,
			asset,
			//Should be native for mainnet
			eif.hbridge.bridge_mode.foreign 
		);
}

function receive_evm_transaction_submitter_cost(sender: byte_array, body: gtv) {
    val sender_transaction_submitter_chain_rid = sender_blockchain @? { .name == blockchains.evm_transaction_submitter_chain } ( .rid );
    if (sender_transaction_submitter_chain_rid == null or sender_transaction_submitter_chain_rid != sender) {
        log("Received evm transaction submitter cost message from sender: %s that is not tracked by economy chain.".format(sender));
        return;
    }
    val evm_transaction_submitter_cost = evm_transaction_submitter_cost.from_gtv(body);
    pay_evm_transaction_submitter_rewards(evm_transaction_submitter_cost);
}

@extend(receive_icmf_message) function icmf_message_receive(sender: byte_array, topic: text, body: gtv) {
    if (topic_needs_initialization(topic)) require_initialized();

    if (not try_call(handle_icmf_message(sender, topic, body, *))) {
        log("Error while processing ICMF message in topic %s".format(topic));
    }
}

function handle_icmf_message(sender: byte_array, topic: text, body: gtv) {
    when (topic) {
        // No need to validate sender since we use a local ICMF receiver
        create_cluster_error_topic -> receive_create_cluster_error_message(body);
        ticket_container_result_topic -> receive_ticket_container_result_message(body);
        cluster_update_topic -> receive_cluster_update_message(body);
        provider_update_topic -> receive_provider_update_message(body);
        node_update_topic -> receive_node_update_message(body);
        cluster_node_update_topic -> receive_cluster_node_update_message(body);
        blockchain_rid_topic -> receive_blockchain_rid(body);
        // Topics received from anchoring chains
        node_availability_report_topic -> receive_node_availability_report(sender, body);
        // Topics received from price oracle
        token_price_changed_topic -> receive_price_oracle_update(sender, body);
        // Topics received from postchain-eif
        evm_transaction_submitter_cost_topic -> receive_evm_transaction_submitter_cost(sender, body);
        // EIF
        eif.messaging.evm_block_events_topic -> eif.messaging.handle_evm_block(eif.messaging.evm_block_message.from_gtv(body));
        else -> log("Unexpected ICMF topic %s".format(topic));
    }
}

function topic_needs_initialization(topic: text): boolean =
    when (topic) {
        ticket_container_result_topic -> true;
        else -> false;
    };

struct pending_minting_data {
    amount: integer;
    account_id: byte_array;
}

operation create_chromia_foundation_voter_set() {

    require(empty(common_voter_set @? { voter_sets.chromia_foundation }), "Voter set %s already exists".format(voter_sets.chromia_foundation));
    require(not(empty(op_context.get_signers())), "Transaction must be signed to set first member of voter set");

    val voter_set = create_common_voter_set_internal(voter_sets.chromia_foundation, 0);

    for (signer in op_context.get_signers()) {
        create common_voter_set_member(voter_set, signer);
    }
}

query get_chromia_foundation_voter_set_info(): (name:text, threshold:integer, governor:text, members:list<pubkey>) {
    val v = require(common_voter_set @? { voter_sets.chromia_foundation }, "Voter set %s not found".format(voter_sets.chromia_foundation));
    val governance = common_voter_set_governance @ { .voter_set == v };
    val members = common_voter_set_member @* { v } ( .pubkey );
    return (
        name = v.name,
        threshold = v.threshold,
        governor = governance.governor.name,
        members = members
    );
}

operation update_chromia_foundation_voter_set(my_pubkey: pubkey, new_threshold: integer?, new_member: list<pubkey>, remove_member: list<pubkey>) {

    // Can't remove last member
    if (remove_member.size() > 0) {
        val voter_set_members = common_voter_set_member @* { require_mint_chr_voter_set() } ( .pubkey );
        voter_set_members.remove_all(remove_member);
        require(not(voter_set_members.empty()), "Can't remove last member in voter set");
    }

    _propose_update_ec_voter_set(my_pubkey, voter_sets.chromia_foundation, new_threshold, new_member, remove_member);
}

operation propose_minting(proposal_by: byte_array, amount: integer, account_id: byte_array) {

    val mint_chr_voter_set = require_mint_chr_voter_set();
    require_signer_member_of_voter_set(mint_chr_voter_set);
    require(amount > 0, "Amount must be greater than 0");
    ft4.accounts.Account(account_id);

    val proposal = create common_proposal(
        timestamp = op_context.last_block_time,
        common_proposal_type.ec_mint,
        proposal_by,
        mint_chr_voter_set,
        description = 1);

    create pending_minting(
        proposal,
        amount,
        account_id
    );

    internal_common_vote(proposal.proposed_by, proposal, true);
}

query get_minting_proposal(proposal_id: rowid) {

    val proposal = require_common_proposal(proposal_id);
    val pending_minting = require(pending_minting @? { proposal }, "Proposal %s is not of type minting".format(proposal_id));

    return pending_minting_data(pending_minting.amount, pending_minting.account_id);
}

enum ticket_state {
    PENDING, SUCCESS, FAILURE
}

enum ticket_type {
    CREATE_CONTAINER, UPGRADE_CONTAINER
}

enum cluster_creation_status {
    SUCCESS, FAILURE, PENDING_APPROVAL, PENDING_CREATION, UNKNOWN
}

object state {
    mutable initialized: boolean = false;
}

object economy_constants {
    mutable min_lease_time_weeks: integer = 1;
    mutable max_lease_time_weeks: integer = 12;
    mutable chr_per_usd: decimal = 5;
    mutable total_cost_system_providers: integer = 828;
    mutable system_provider_fee_share: decimal = 0.1;
    mutable staking_reward_fee_share: decimal = 0.1;
    mutable chromia_foundation_fee_share: decimal = 0.1;
    mutable resource_pool_margin_fee_share: decimal = 0.1;
    mutable system_provider_risk_share: decimal = 0.1;
    mutable dapp_provider_risk_share: decimal = 0.2;

    // Staking requirements for payout
    mutable staking_requirements_enabled: boolean = true;
    mutable staking_requirement_stop_payout_days: integer = 14; // 2 weeks - the time providers can fail to meet the requirements before payouts are stopped
    mutable staking_requirement_system_provider_own_stake_usd: integer = 20000; // 20k usd
    mutable staking_requirement_system_provider_total_stake_usd: integer = 200000; // 200k usd
    mutable staking_requirement_dapp_provider_own_stake_usd: integer = 10000; // 10k usd
    mutable staking_requirement_dapp_provider_total_stake_usd: integer = 10000; // 100k usd
}

entity sender_blockchain {
    rid: byte_array;
    name: text;
}

entity node_availability {
    index node: byte_array;
    availability: decimal;
    start_time: timestamp;
    index end_time: timestamp;
