operation update_system_provider_economy_constants(
    total_cost_system_providers: integer? = null,
    system_provider_fee_share: decimal? = null,
    system_provider_risk_share: decimal? = null
) {
    require_admin();
    economy_constants.total_cost_system_providers = total_cost_system_providers ?: economy_constants.total_cost_system_providers;
    economy_constants.system_provider_fee_share = system_provider_fee_share ?: economy_constants.system_provider_fee_share;
    economy_constants.system_provider_risk_share = system_provider_risk_share ?: economy_constants.system_provider_risk_share;
}

operation update_staking_requirements_economy_constants(
    staking_requirements_enabled: boolean? = null,
    staking_requirement_stop_payout_days: integer? = null,
    staking_requirement_system_provider_own_stake_usd: integer? = null,
    staking_requirement_system_provider_total_stake_usd: integer? = null,
    staking_requirement_dapp_provider_own_stake_usd: integer? = null,
    staking_requirement_dapp_provider_total_stake_usd: integer? = null
) {
    require_admin();
    economy_constants.staking_requirements_enabled = staking_requirements_enabled ?: economy_constants.staking_requirements_enabled;
    economy_constants.staking_requirement_stop_payout_days = staking_requirement_stop_payout_days ?: economy_constants.staking_requirement_stop_payout_days;
    economy_constants.staking_requirement_system_provider_own_stake_usd = staking_requirement_system_provider_own_stake_usd ?: economy_constants.staking_requirement_system_provider_own_stake_usd;
    economy_constants.staking_requirement_system_provider_total_stake_usd = staking_requirement_system_provider_total_stake_usd ?: economy_constants.staking_requirement_system_provider_total_stake_usd;
    economy_constants.staking_requirement_dapp_provider_own_stake_usd = staking_requirement_dapp_provider_own_stake_usd ?: economy_constants.staking_requirement_dapp_provider_own_stake_usd;
    economy_constants.staking_requirement_dapp_provider_total_stake_usd = staking_requirement_dapp_provider_total_stake_usd ?: economy_constants.staking_requirement_dapp_provider_total_stake_usd;
}

operation update_chr_per_usd(
    chr_per_usd: decimal?
) {
    require_admin();
    economy_constants.chr_per_usd = chr_per_usd ?: economy_constants.chr_per_usd;
}

operation update_economy_constants(
    min_lease_time_weeks: integer?,
    max_lease_time_weeks: integer?,
    staking_reward_fee_share: decimal?,
    chromia_foundation_fee_share: decimal?,
    resource_pool_margin_fee_share: decimal?,
    dapp_provider_risk_share: decimal?
) {
    val provider = require_system_provider_signer_entity();

    val proposal = create_system_p_proposal(common_proposal_type.ec_constants_update, provider, "Update economy constants");
    create pending_economy_constants(
        proposal,
        min_lease_time_weeks = get_integer_or_default(min_lease_time_weeks, -1)!!,
        max_lease_time_weeks = get_integer_or_default(max_lease_time_weeks, -1)!!,
        staking_reward_fee_share = get_decimal_or_default(staking_reward_fee_share, -1)!!,
        chromia_foundation_fee_share = get_decimal_or_default(chromia_foundation_fee_share, -1)!!,
        resource_pool_margin_fee_share = get_decimal_or_default(resource_pool_margin_fee_share, -1)!!,
        dapp_provider_risk_share = get_decimal_or_default(dapp_provider_risk_share, -1)!!
    );

    internal_common_vote(provider.pubkey, proposal, true);
}

operation create_tag(
    name: text,
    scu_price: integer,
    extra_storage_price: integer
) {
    val provider = require_system_provider_signer_entity();
    require(tag @? { .name == name } == null, "Tag %s already exists".format(name));
    require(pending_tag_operation @? { .name == name } == null, "A proposal for creating tag %s already exists".format(name));
    validate_entity_name(name);
    require(scu_price > 0, "Tag must have a positive SCU price");
    require(extra_storage_price > 0, "Tag must have a positive extra storage price");

    val proposal = create_system_p_proposal(common_proposal_type.ec_tag_create, provider, "Create tag %s".format(name));
    create pending_tag_operation(name = name, scu_price = scu_price, extra_storage_price = extra_storage_price, proposal);

    internal_common_vote(provider.pubkey, proposal, true);
}

operation update_tag(
    name: text,
    scu_price: integer?,
    extra_storage_price: integer?
) {
    val provider = require_system_provider_signer_entity();
    val tag = require_tag(name);
    require(empty(scu_price) or scu_price > 0, "Tag must have a positive SCU price");
    require(empty(extra_storage_price) or extra_storage_price > 0, "Tag must have a positive extra storage price");

    val proposal = create_system_p_proposal(common_proposal_type.ec_tag_update, provider, "Update tag %s".format(name));
    create pending_tag_operation(name = name, scu_price = scu_price ?: -1, extra_storage_price = extra_storage_price ?: -1, proposal);

    internal_common_vote(provider.pubkey, proposal, true);
}

operation remove_tag(
    name: text
) {
    val provider = require_system_provider_signer_entity();
    val tag = require_tag(name);

    val clusters = cluster @* { tag };
    require(clusters.empty(), "Tag with name %s is in use.".format(name));

    val proposal = create_system_p_proposal(common_proposal_type.ec_tag_remove, provider, "Remove tag %s".format(name));
    create pending_tag_operation(name = name, proposal);

    internal_common_vote(provider.pubkey, proposal, true);
}

operation create_cluster(
    name,
    governor_voter_set_name: text,
    voter_set_name: text,
    cluster_units: integer,
    extra_storage: integer,
    tag_name: text
) {
    val provider = require_system_provider_signer_entity();

    require(empty(cluster @* { .name == name }), "Cluster %s already exists".format(name));
    require(pending_cluster @? { name } == null, "There is already a pending request to create cluster with name %s".format(name));
    validate_entity_name(name);
    val tag = require_tag(tag_name);

    val proposal = create_system_p_proposal(common_proposal_type.ec_cluster_create, provider, "Create economy chain cluster %s".format(name));

    create pending_cluster(
        name = name,
        tag,
        proposer_pubkey = provider.pubkey,
        governor_voter_set_name = governor_voter_set_name,
        voter_set_name = voter_set_name,
        cluster_units,
        extra_storage,
        proposal,
        pending_cluster_status.PENDING_APPROVAL
    );

    internal_common_vote(provider.pubkey, proposal, true);
}

operation change_cluster_tag(
    cluster_name: text,
    tag_name: text
) {
    val provider = require_system_provider_signer_entity();
    val tag = require_tag(tag_name);
    val cluster = require_cluster(cluster_name);

    val proposal = create_system_p_proposal(common_proposal_type.ec_cluster_change_tag, provider, "Change tag for cluster %s".format(cluster_name));
    create pending_cluster_change_tag(cluster, tag, proposal);

    internal_common_vote(provider.pubkey, proposal, true);
}

operation add_bridge_lease(container_name: text, blockchain_rid: byte_array, evm_network_id: integer, validator_contract: text, bridge_contract: text, initial_signers: list<byte_array>, anomaly_detection: boolean) {
    add_bridge_lease_impl(container_name, blockchain_rid, evm_network_id, validator_contract, bridge_contract, initial_signers, anomaly_detection);
}

operation update_bridge_lease(blockchain_rid: byte_array, evm_network_id: integer, updated_validator_contract: text?, updated_bridge_contract: text?, updated_signers: list<byte_array>?, anomaly_detection: boolean?) {
    update_bridge_lease_impl(blockchain_rid, evm_network_id, updated_validator_contract, updated_bridge_contract, updated_signers, anomaly_detection);
}

operation remove_bridge_lease(blockchain_rid: byte_array, evm_network_id: integer) {
    remove_bridge_lease_impl(blockchain_rid, evm_network_id);
}

function create_system_p_proposal(common_proposal_type, provider, description: text): common_proposal {

    return create common_proposal(
        timestamp = op_context.last_block_time,
        common_proposal_type,
        provider.pubkey,
        system_p_voter_set(),
                                    description = 1);
}

import lib.priceoracle.icmf_encoding.*;

entity price_oracle_rates {
    key symbol: text;
    name: text;
    mutable price: decimal;
}

function receive_price_oracle_update(sender: byte_array, body: gtv) {

    require(exists(sender_blockchain @? { .name == blockchains.price_oracle_chain_name, .rid == sender }),
        "Received price oracle message from sender: %s that is not tracked by economy chain.".format(sender));

    val message = token_price_changed_body.from_gtv(body);

    set_price_oracle_rate_value(message);

    if (message.symbol == chain_context.args.asset_symbol) {
        economy_constants.chr_per_usd = message.price;
    }
}

function set_price_oracle_rate_value(message: token_price_changed_body) {

    val price_oracle_rates = price_oracle_rates @? { .name == message.name };

    if (price_oracle_rates == null) {
        create price_oracle_rates(symbol = message.symbol, name = message.name, message.price);
    } else {
        price_oracle_rates.price = message.price;
    }
}

@extend(apply_common_voting_result_handlers) function() = [common_proposal_type.ec_cluster_create.name: apply_cluster_create(*)];
@extend(apply_common_voting_result_handlers) function() = [common_proposal_type.ec_cluster_change_tag.name: apply_cluster_change_tag(*)];

function apply_cluster_create(proposal: common_proposal) {

    val pending_cluster = pending_cluster @? { proposal };

    if (pending_cluster == null) {
        log("Received accepted cluster creation proposal with no pending_cluster. Proposal: %s".format(proposal));
    } else {

        val create_cluster_message = create_cluster_message(
            name = pending_cluster.name,
            governor_voter_set_name = pending_cluster.governor_voter_set_name,
            voter_set_name = pending_cluster.voter_set_name,
            cluster_units = pending_cluster.cluster_units,
            extra_storage = pending_cluster.extra_storage,
            proposer_pubkey = pending_cluster.proposer_pubkey);

        send_message(create_cluster_topic, create_cluster_message.to_gtv());

        pending_cluster.status = pending_cluster_status.PENDING_CREATION;

        log("Message sent to create cluster %s".format(pending_cluster.name));
    }
}

@extend(delete_common_proposal_handlers) function(): map<text, (common_proposal) -> unit> = [common_proposal_type.ec_cluster_create.name: cleanup_pending_cluster_create(*)];
@extend(delete_common_proposal_handlers) function(): map<text, (common_proposal) -> unit> = [common_proposal_type.ec_cluster_change_tag.name: cleanup_pending_cluster_change_tag(*)];

function cleanup_pending_cluster_create(proposal: common_proposal) {

    val pending_cluster = pending_cluster @? { proposal };

    // Only cleanup if this was a revoke or a failed cluster creation
    if (pending_cluster != null and
    (pending_cluster.status == pending_cluster_status.PENDING_APPROVAL or
    pending_cluster.status == pending_cluster_status.FAILURE)
    ) {

        log("Revoked and removed pending cluster %s".format(pending_cluster.name));

        delete pending_cluster @ { proposal };
    }
}

@extend(apply_common_voting_result_handlers) function() = [common_proposal_type.ec_constants_update.name: apply_economy_constants(*)];


function apply_economy_constants(proposal: common_proposal) {

    val pending_economy_constants = pending_economy_constants @ { proposal };

    log("Updating economy constants after approval of proposal %d".format(proposal.rowid));

    if (pending_economy_constants.min_lease_time_weeks >= 0) {
        economy_constants.min_lease_time_weeks = pending_economy_constants.min_lease_time_weeks;
    }
    if (pending_economy_constants.max_lease_time_weeks >= 0) {
        economy_constants.max_lease_time_weeks = pending_economy_constants.max_lease_time_weeks;
    }
    if (pending_economy_constants.staking_reward_fee_share >= 0) {
        economy_constants.staking_reward_fee_share = pending_economy_constants.staking_reward_fee_share;
    }
    if (pending_economy_constants.chromia_foundation_fee_share >= 0) {
        economy_constants.chromia_foundation_fee_share = pending_economy_constants.chromia_foundation_fee_share;
    }
    if (pending_economy_constants.resource_pool_margin_fee_share >= 0) {
        economy_constants.resource_pool_margin_fee_share = pending_economy_constants.resource_pool_margin_fee_share;
    }
    if (pending_economy_constants.dapp_provider_risk_share >= 0) {
        economy_constants.dapp_provider_risk_share = pending_economy_constants.dapp_provider_risk_share;
    }
}

@extend(delete_common_proposal_handlers) function(): map<text, (common_proposal) -> unit> = [common_proposal_type.ec_constants_update.name: cleanup_pending_economy_constants(*)];

function cleanup_pending_economy_constants(proposal: common_proposal) {

    log("Cleaning up pending_economy_constants");

    delete pending_economy_constants @ { proposal };
}

entity pending_minting {
    proposal: common_proposal;
    amount: integer;
    account_id: byte_array;
}

@extend(apply_common_voting_result_handlers) function() = [common_proposal_type.ec_mint.name: apply_ec_pending_minting(*)];

function apply_ec_pending_minting(proposal: common_proposal) {

    val pending_minting = pending_minting @ { proposal };
    val account = require(ft4.accounts.account @? { pending_minting.account_id }, "Account not found");

    log("Apply minting proposal %d".format(pending_minting.rowid));

    ft4.assets.Unsafe.mint(account, get_asset(), pending_minting.amount);
}

@extend(delete_common_proposal_handlers) function(): map<text, (common_proposal) -> unit> = [common_proposal_type.ec_mint.name: cleanup_ec_pending_minting(*)];

function cleanup_ec_pending_minting(proposal: common_proposal) {

    log("Cleaning up pending minting proposal");

    delete pending_minting @ { proposal };
}

@extend(apply_common_voting_result_handlers) function() = [common_proposal_type.ec_tag_create.name: apply_tag_create(*)];
@extend(apply_common_voting_result_handlers) function() = [common_proposal_type.ec_tag_update.name: apply_tag_update(*)];
@extend(apply_common_voting_result_handlers) function() = [common_proposal_type.ec_tag_remove.name: apply_tag_remove(*)];

function apply_tag_remove(proposal: common_proposal) {

    val pending_tag = pending_tag_operation @ { proposal };
    val tag = tag @ { pending_tag.name };

    log("Remove tag %s after approval".format(tag.name));

    val clusters = cluster @* { tag };
    require(clusters.empty(), "Tag with name %s is in use.".format(tag.name));

    delete tag;
}

function apply_tag_update(proposal: common_proposal) {

    val pending_tag = pending_tag_operation @ { proposal };
    val tag = tag @ { pending_tag.name };

    log("Update tag %s after approval".format(tag.name));

    if (pending_tag.scu_price != -1) tag.scu_price = pending_tag.scu_price;
    if (pending_tag.extra_storage_price != -1) tag.extra_storage_price = pending_tag.extra_storage_price;
}

function apply_tag_create(proposal: common_proposal) {

    val pending_tag = pending_tag_operation @ { proposal };

    log("Create tag %s after approval".format(pending_tag.name));

    create tag(name = pending_tag.name, scu_price = pending_tag.scu_price, extra_storage_price = pending_tag.extra_storage_price);
}

function apply_cluster_change_tag(proposal: common_proposal) {

    val pending_cluster_change_tag = pending_cluster_change_tag @ { proposal };

    log("Changing tag of cluster %s to %s after approval".format(pending_cluster_change_tag.cluster.name, pending_cluster_change_tag.tag.name));

    pending_cluster_change_tag.cluster.tag = pending_cluster_change_tag.tag;
}

@extend(delete_common_proposal_handlers) function(): map<text, (common_proposal) -> unit> = [common_proposal_type.ec_tag_create.name: cleanup_pending_tag_operation(*)];
@extend(delete_common_proposal_handlers) function(): map<text, (common_proposal) -> unit> = [common_proposal_type.ec_tag_update.name: cleanup_pending_tag_operation(*)];
@extend(delete_common_proposal_handlers) function(): map<text, (common_proposal) -> unit> = [common_proposal_type.ec_tag_remove.name: cleanup_pending_tag_operation(*)];

function cleanup_pending_tag_operation(proposal: common_proposal) {

    log("Cleaning up pending_tag_operation");

    delete pending_tag_operation @ { proposal };
}

function cleanup_pending_cluster_change_tag(proposal: common_proposal) {

    log("Cleaning up pending_cluster_change_tag");

    delete pending_cluster_change_tag @ { proposal };
}

import common_proposal;

namespace voter_sets {
    val system_p = "SYSTEM_P";
    val chromia_foundation = "CHROMIA_FOUNDATION";
}

function system_p_voter_set() = common_voter_set @ { voter_sets.system_p };
function require_mint_chr_voter_set() = require_common_voter_set(voter_sets.chromia_foundation);

entity pending_ec_voter_set_update {
    key proposal: common_proposal, voter_set: common_voter_set;
}

namespace ec_voter_set_update {
    entity threshold {
        key pending_ec_voter_set_update;
        threshold: integer;
    }

    entity new_member {
        index pending_ec_voter_set_update;
        pubkey;
    }

    entity remove_member {
        index pending_ec_voter_set_update;
        pubkey;
    }
}

@extend(apply_common_voting_result_handlers) function() = [common_proposal_type.ec_voter_set_update.name: apply_ec_voter_set_update(*)];

function apply_ec_voter_set_update(proposal: common_proposal) {
    val vsp = pending_ec_voter_set_update @? { proposal };
    if (vsp == null) return;
    val threshold = ec_voter_set_update.threshold @? { vsp }.threshold;
    if (threshold != null) vsp.voter_set.threshold = threshold;
    val new_member = ec_voter_set_update.new_member @* { vsp }.pubkey;
    for (m in new_member) {
        create common_voter_set_member(vsp.voter_set, m);
    }
    val remove_member = ec_voter_set_update.remove_member @* { vsp }.pubkey;
    for (m in remove_member) {
        delete common_voter_set_member @ { vsp.voter_set, m };
    }
}

@extend(delete_common_proposal_handlers) function(): map<text, (common_proposal) -> unit> = [common_proposal_type.ec_voter_set_update.name: delete_pending_ec_voter_set_update(*)];

function delete_pending_ec_voter_set_update(proposal: common_proposal) {
    val p = pending_ec_voter_set_update @? { proposal };
    if (p == null) return;
    delete ec_voter_set_update.threshold @? { p };
    delete ec_voter_set_update.new_member @* { p };
    delete ec_voter_set_update.remove_member @* { p };
    delete p;
}

operation propose_update_ec_voter_set(my_pubkey: pubkey, voter_set_name: text, new_threshold: integer?, new_member: list<pubkey>, remove_member: list<pubkey>) {
    _propose_update_ec_voter_set(my_pubkey, voter_set_name, new_threshold, new_member, remove_member);
}

function _propose_update_ec_voter_set(my_pubkey: pubkey, voter_set_name: text, new_threshold: integer?, new_member: list<pubkey>, remove_member: list<pubkey>) {
    require_is_signer(my_pubkey);
    val voter_set = require_common_voter_set(voter_set_name);
    require(voter_set.name != voter_sets.system_p, "Cannot update system voter set. Update this by proposing system provider role");
    require_common_voter_set_governor(voter_set, my_pubkey);
    require(empty(common_proposal @* { voter_set, common_proposal_state.PENDING }), "Cannot have more than one pending proposal involving this voter set.");

    val prop = create common_proposal(
                                    timestamp = op_context.last_block_time,
        common_proposal_type.ec_voter_set_update,
        my_pubkey,
        voter_set, description = 1
    );
    val update_prop = create pending_ec_voter_set_update(prop, voter_set);
    if (new_threshold != null) {
        require(new_threshold >= -1 and new_threshold <= (common_voter_set_member @* { voter_set }).size(),
        "Invalid threshold level, must be in range [-1, voter_set.size()]");
        create ec_voter_set_update.threshold(update_prop, new_threshold);
    }
    for (m in new_member) {
        create ec_voter_set_update.new_member(update_prop, m);
    }
    for (m in remove_member) {
        create ec_voter_set_update.remove_member(update_prop, m);
    }
    internal_common_vote(my_pubkey, prop, true);
}

query get_ec_voter_set_update_proposal(id: rowid) {
    val p = common_proposal @? { id };
    if (p == null) return null;
    val pvsu = pending_ec_voter_set_update @? { p };
    if (pvsu == null) return null;
    return (
        voter_set = pvsu.voter_set.name,
        threshold = ec_voter_set_update.threshold @? { pvsu }.threshold,
        add_member = ec_voter_set_update.new_member @* { pvsu } .pubkey,
        remove_member = ec_voter_set_update.remove_member @* { pvsu } .pubkey
    );
}

