function get_integer_or_default(value: integer?, default: integer?): integer? {
    if (value != null and value >= 0) {
        return value;
    }
    return default;
}

function get_decimal_or_default(value: decimal?, default: decimal?): decimal? {
    if (value != null and value >= 0) {
        return value;
    }
    return default;
}

function get_last_blocktime(){
    return block @ {} (@max .timestamp) ?: 0;
}

val DAY_MS = 86400000; // 1000 * 60 * 60 * 24 - 1 day

function pay_evm_transaction_submitter_rewards(evm_transaction_submitter_cost: evm_transaction_submitter_cost) {
    pay_out_node_rewards(calculate_evm_transaction_submitter_reward(evm_transaction_submitter_cost));
}

function calculate_evm_transaction_submitter_reward(evm_transaction_submitter_cost: evm_transaction_submitter_cost): map<node, big_integer> {
    val node_reward = map<node, big_integer>();
    val currency_to_price = map<text, decimal>(
        price_oracle_rates @* { .symbol == chain_context.args.asset_symbol or .symbol == evm_transaction_submitter_cost.currency_symbol} (.symbol, .price)
    );
    require(currency_to_price.contains(chain_context.args.asset_symbol), "Reward currency %s does not exists in price oracle.".format(chain_context.args.asset_symbol));
    val node = node @? { .pubkey == evm_transaction_submitter_cost.processed_by};
    if (node == null) {
        log("Warning: Node %s does not exists in EC. Transaction %s will not be rewarded.".format(evm_transaction_submitter_cost.processed_by, evm_transaction_submitter_cost.id));
    } else {
        if (not currency_to_price.contains(evm_transaction_submitter_cost.currency_symbol)) {
            log("Warning: Currency %s does not exists in price oracle. Transaction %s will not be rewarded.".format(evm_transaction_submitter_cost.currency_symbol, evm_transaction_submitter_cost.id));
        } else {
            val native_currency_to_chr_ratio = currency_to_price[evm_transaction_submitter_cost.currency_symbol] / currency_to_price[chain_context.args.asset_symbol];
            node_reward[node] = (evm_transaction_submitter_cost.cost * native_currency_to_chr_ratio * (1 + chain_context.args.evm_transaction_submitters_bonus)).to_big_integer();
        }
    }
    return node_reward;
}


function pay_rewards(cluster: cluster, node_availability_report: node_availability_report) {

    val is_system_cluster = cluster.name == system_cluster_name;
    val node_reward = if (is_system_cluster)
            calculate_system_cluster_rewards(cluster, node_availability_report)
        else
            calculate_dapp_cluster_rewards(cluster, node_availability_report);

    pay_out_node_rewards(node_reward);

    if (is_system_cluster){
        pay_out_chromia_foundation_reward();
    }
}

function calculate_system_cluster_rewards(system_cluster: cluster, node_availability_report: node_availability_report): map<node, big_integer> {
    val system_cluster_nodes = cluster_node @* { .cluster == system_cluster} .node;

    val number_of_nodes_in_system_cluster = system_cluster_nodes.size();
    val sum_total_max_revenue_per_dapp_cluster = sum_total_max_revenue_per_dapp_cluster();

    val system_provider_cost_share_per_node = (sum_total_max_revenue_per_dapp_cluster * economy_constants.system_provider_fee_share) / number_of_nodes_in_system_cluster;
    val max_system_provider_reward_per_node = max(economy_constants.total_cost_system_providers * (1 - economy_constants.system_provider_risk_share) + system_provider_cost_share_per_node * economy_constants.system_provider_risk_share, system_provider_cost_share_per_node) * economy_constants.chr_per_usd * units_per_asset;

    val system_node_reward = map<node, big_integer>();
    for (system_cluster_node in system_cluster_nodes) {
        val availability_factor = adjusted_availability_factor(node_availability_report.node_availability[system_cluster_node.pubkey]);
        val system_provider_reward_per_node = max_system_provider_reward_per_node * availability_factor;
        log("Reward calculated for node %s in system cluster based on total_cost_system_providers: %s, system_provider_risk_share: %s, system_provider_cost_share_per_node: %s, system_provider_risk_share: %s, availability_factor: %s, chr_per_usd: %s, units_per_asset: %s, system_provider_fee_share: %s, system_provider_reward_per_node: %s"
            .format(system_cluster_node.pubkey, economy_constants.total_cost_system_providers, economy_constants.system_provider_risk_share, system_provider_cost_share_per_node, economy_constants.system_provider_risk_share, availability_factor, economy_constants.chr_per_usd, units_per_asset, economy_constants.system_provider_fee_share, system_provider_reward_per_node));
        system_node_reward[system_cluster_node] = system_provider_reward_per_node.to_big_integer();
    }
    return system_node_reward;
}

function calculate_dapp_cluster_rewards(cluster: cluster, node_availability_report: node_availability_report): map<node, big_integer> {
    val cluster_nodes = cluster_node @* { cluster } .node;

    val occupancy_rate = occupancy_rate(cluster);
    val dapp_cluster_value = dapp_cluster_value(cluster);
    val number_of_nodes_per_dapp_cluster = cluster_nodes.size();

    val max_dapp_provider_reward_per_node = ((dapp_cluster_value * (1 - economy_constants.dapp_provider_risk_share) + dapp_cluster_value * occupancy_rate * economy_constants.dapp_provider_risk_share) / number_of_nodes_per_dapp_cluster) * economy_constants.chr_per_usd * units_per_asset;
    val node_reward = map<node, big_integer>();
    for (cluster_node in cluster_nodes) {
        val availability_factor = adjusted_availability_factor(node_availability_report.node_availability[cluster_node.pubkey]);
        val dapp_provider_reward_per_node = max_dapp_provider_reward_per_node * availability_factor;
        log("Reward calculated for node %s in cluster %s based on dapp_cluster_value: %s, dapp_provider_risk_share: %s, dapp_cluster_value: %s, occupancy_rate: %s, number_of_nodes_per_dapp_cluster: %s, availability_factor: %s, chr_per_usd: %s, units_per_asset: %s, system_provider_fee_share: %s, staking_reward_fee_share: %s, chromia_foundation_fee_share: %s, resource_pool_margin_fee_share: %s, dapp_provider_reward_per_node: %s"
            .format(cluster_node.pubkey, cluster.name, dapp_cluster_value, economy_constants.dapp_provider_risk_share, dapp_cluster_value, occupancy_rate, number_of_nodes_per_dapp_cluster, availability_factor, economy_constants.chr_per_usd, units_per_asset, economy_constants.system_provider_fee_share, economy_constants.staking_reward_fee_share, economy_constants.chromia_foundation_fee_share, economy_constants.resource_pool_margin_fee_share, dapp_provider_reward_per_node));
        node_reward[cluster_node] = dapp_provider_reward_per_node.to_big_integer();
    }
    return node_reward;
}

function pay_out_chromia_foundation_reward() {
    val sum_total_max_revenue_per_dapp_cluster = sum_total_max_revenue_per_dapp_cluster();
    val chromia_foundation_reward = (sum_total_max_revenue_per_dapp_cluster * economy_constants.chromia_foundation_fee_share * economy_constants.chr_per_usd * units_per_asset).to_big_integer();
    log("Reward calculated for chromia foundation based on sum_total_max_revenue_per_dapp_cluster: %s, chromia_foundation_fee_share: %s, chr_per_usd: %s, units_per_asset: %s is chromia_foundation_reward: %s"
        .format(sum_total_max_revenue_per_dapp_cluster, economy_constants.chromia_foundation_fee_share, economy_constants.chr_per_usd, units_per_asset, chromia_foundation_reward));

    val pool = get_pool_account();
    var pool_balance = get_account_balance(pool);
    val chromia_foundation_account = get_chromia_foundation_account();

    val pay_reward_result = pay_reward(pool, pool_balance, chromia_foundation_account, chromia_foundation.reward_debt, chromia_foundation_reward, "Chromia Foundation");

    chromia_foundation.reward_debt = pay_reward_result.reward_debt;
}

function pay_out_node_rewards(node_reward: map<node, big_integer>) {

    val pool = get_pool_account();
    var pool_balance = get_account_balance(pool);

    for ((node, reward) in node_reward) {
        val provider = node.provider;
        val pa = provider_account @ { provider };

        if (is_staking_approved(provider, pa, reward)) {
            val pay_reward_result = pay_reward(pool, pool_balance, pa.account, pa.reward_debt, reward, "provider %s".format(pa.provider.pubkey));

            save_node_payed_reward(node.pubkey, pay_reward_result.payed_reward, op_context.last_block_time);
            pa.reward_debt = pay_reward_result.reward_debt;
            pool_balance = pay_reward_result.pool_balance;
        }
    }
}

function is_staking_approved(provider, provider_account, reward: big_integer): boolean {

    if (economy_constants.staking_requirements_enabled) {
        if (provider_meets_staking_requirements(provider, provider_account)) {

            provider_account.last_approved_stake_requirements = op_context.last_block_time;
        } else {
            val (days_since_approved_staking, pay_out_reward) = get_staking_requirement_payout_stop(provider_account);

            if (pay_out_reward) {
                log("Provider %s do not meet staking requirements - payouts will be stopped in %d days".format(
                    provider.pubkey, economy_constants.staking_requirement_stop_payout_days - days_since_approved_staking));
            } else {
                log("Provider %s lost reward of %s due to low levels of staking for too long (%s days)".format(
                    provider.pubkey, reward, days_since_approved_staking));
                return false;
            }
        }
    }

    return true;
}

function pay_reward(pool: ft4.accounts.account, pool_balance: big_integer, account: ft4.accounts.account, reward_debt:big_integer,  reward: big_integer, identity: text): pay_reward_result {
    var total_pool_balance = pool_balance;
    var total_reward_debt = reward + reward_debt;

    var amount_to_transfer = 0L;
    if (total_reward_debt > 0) {
        if (pool_balance < total_reward_debt) {
            if (pool_details.last_refill_millis + chain_context.args.test_chr_pool_refill_limit_millis > op_context.last_block_time) {
                log("Pool account have already claimed %s %s within the last %s millis.".format(
                    chain_context.args.pool_amount_to_mint,
                    chain_context.args.asset_symbol,
                    chain_context.args.test_chr_pool_refill_limit_millis));
            } else {
                log("Mint %s %s to pool account.".format(chain_context.args.pool_amount_to_mint, chain_context.args.asset_symbol));
                ft4.assets.Unsafe.mint(pool, get_asset(), chain_context.args.pool_amount_to_mint);
                pool_details.last_refill_millis = op_context.last_block_time;
                total_pool_balance += chain_context.args.pool_amount_to_mint;
            }
        }
        if (total_pool_balance >= total_reward_debt) {
            amount_to_transfer = total_reward_debt;
        } else if (total_pool_balance <= 0) { // No funds to pay reward
            log("Reward pool is empty!");
            amount_to_transfer = 0;
        } else { // Missing funds to pay full reward
            log("Reward pool does not have enough funds to transfer full reward.");
            amount_to_transfer = total_pool_balance;
        }
        if (amount_to_transfer > 0) {
            log("Transfer reward %s to %s".format(amount_to_transfer, identity));
            if (transfer_reward(pool, account, amount_to_transfer)) {
                total_reward_debt -= amount_to_transfer;
                total_pool_balance -= amount_to_transfer;
            } else {
                log("Unable to transfer reward to %s".format(identity));
            }
        }
    }

    val pay_reward_result = pay_reward_result(payed_reward = amount_to_transfer, payed_to = account, pool_balance = total_pool_balance, reward_debt = total_reward_debt);
    after_pay_reward(pay_reward_result);
    return pay_reward_result;
}

@extendable function after_pay_reward(pay_reward_result: pay_reward_result) {}

function sum_total_max_revenue_per_dapp_cluster(): decimal {
    var sum_total_max_revenue_per_dapp_cluster = 0.0;
    val clusters = cluster @* { .name != system_cluster_name };
    for (cluster in clusters) {
        sum_total_max_revenue_per_dapp_cluster += total_max_revenue_per_dapp_cluster(cluster);
    }
    return sum_total_max_revenue_per_dapp_cluster;
}

function total_max_revenue_per_dapp_cluster(cluster: cluster): decimal = (total_available_scus(cluster.cluster_units) - standard_cluster_unit.system_container_units) * cluster.tag.scu_price + cluster.tag.extra_storage_price * (cluster.extra_storage / 1024);

function dapp_provider_fee_share(): decimal = 1 - economy_constants.chromia_foundation_fee_share - economy_constants.resource_pool_margin_fee_share - economy_constants.system_provider_fee_share;

function dapp_cluster_value(cluster: cluster): decimal = total_max_revenue_per_dapp_cluster(cluster) * dapp_provider_fee_share() / (1 + economy_constants.staking_reward_fee_share);

function occupied_scus(cluster: cluster): integer = lease @ { cluster, not .expired } ( @sum .container_units );

function total_available_scus(cluster_units: integer): integer = cluster_units * standard_cluster_unit.container_units;

function occupancy_rate(cluster): decimal = decimal(occupied_scus(cluster)) / (total_available_scus(cluster.cluster_units) - standard_cluster_unit.system_container_units);

function adjusted_availability_factor(availability_factor: decimal): decimal = max(0, availability_factor - 0.9) * 10;

function transfer_reward(pool: ft4.accounts.account, account: ft4.accounts.account, amount: big_integer): boolean {
    return try_call(try_transfer_reward(pool, account, amount, *));
}

function try_transfer_reward(pool: ft4.accounts.account, account: ft4.accounts.account, amount: big_integer) {
    ft4.assets.Unsafe.transfer(get_pool_account(), account, get_asset(), amount);
}

@extend(ft4.auth.auth_handler)
function () = ft4.auth.add_auth_handler(
    scope = "transfer_to_pool",
    flags = ["T"],
    message = transfer_to_pool_auth_message(*)
);

function transfer_to_pool_auth_message(gtv): text {
    val args = struct<transfer_to_pool>.from_gtv(gtv);

    return "Please sign the message\nto transfer %s %s from account {account_id} \nto pool account.".format(
        ft4.assets.format_amount_with_decimals(args.amount, chain_context.args.asset_decimals),
        chain_context.args.asset_symbol);
}

function transfer_to_pool_impl(amount: big_integer) {
    require_initialized();

    val account = ft4.auth.authenticate();
    ft4.accounts.Account(account.id);

    ft4.assets.Unsafe.transfer(account, get_pool_account(), get_asset(), amount);
}

function save_node_payed_reward(node: byte_array, value: big_integer, time: timestamp){
    create node_payed_reward(node, value, time);
}

function get_days_since(time: timestamp): integer {
    return (op_context.last_block_time - time) / DAY_MS;
}

function get_staking_requirement_payout_stop(provider_account): (integer, boolean) {
    val days_since_approved_staking = get_days_since(provider_account.last_approved_stake_requirements);
    return (days_since_approved_staking, days_since_approved_staking < economy_constants.staking_requirement_stop_payout_days);
}

function provider_meets_staking_requirements(provider, provider_account): boolean {

    val required_own = if (provider.system)
        economy_constants.staking_requirement_system_provider_own_stake_usd
    else
        economy_constants.staking_requirement_dapp_provider_own_stake_usd;

    val required_total = if (provider.system)
            economy_constants.staking_requirement_system_provider_total_stake_usd
        else
            economy_constants.staking_requirement_dapp_provider_total_stake_usd;

    val own_usd = get_chr_in_usd(staking_get_balance(provider_account.account.id));
    val total_usd = get_chr_in_usd(staking_get_total_delegation_to(provider.pubkey));

    if (own_usd < required_own) {
        log("Provider %s has not enough own staking (%s < %s)".format(provider.pubkey, own_usd, required_own));
        return false;
    }

    if (total_usd < required_total) {
        log("Provider %s has not enough total staking (%s < %s)".format(provider.pubkey, total_usd, required_total));
        return false;
    }

    return true;
}

function get_chr_in_usd(chr: integer): decimal =
    chr * economy_constants.chr_per_usd;

function receive_blockchain_rid(body: gtv) {
    val blockchain_rid = blockchain_rid.from_gtv(body);

    create sender_blockchain(rid = blockchain_rid.rid, name = blockchain_rid.name);
}

// Rate management

function _staking_set_rate_at_impl(reward_rate: decimal, provider_rate: decimal, time: timestamp) {
    require_initialized();
    require_admin();
    require(time >= _staking_cannot_change_before(), "Cannot change rate before " + _staking_cannot_change_before());
   _staking_set_rate_at(reward_rate, time);
}

function _staking_set_rate_at(reward_rate: decimal, time: timestamp) {
    create reward_rate(time, reward_rate);
}

function _staking_set_rate_impl(reward_rate: decimal) {
    require_admin();
   _staking_set_rate_at(reward_rate, _staking_cannot_change_before());
}

function _staking_get_current_rate(): decimal {
    val current_rate = reward_rate @ {
        .reward_rate_time <= _staking_last_known_time()
    } (
        .reward_rate,
        @omit @sort_desc .reward_rate_time
    ) limit 1;
    return current_rate;
}


// Provider management

function _staking_offboard_provider(provider_account) {
    // Unwind delegations immediately
    // Find all the latest delegations involving removed provider
    // eg. latest AND new_provider is going
    val removed_delegations = staker_state @* { .new_provider == provider_account and .latest } (@group .staker);
    // then for each :-
    for (removed_delegation in removed_delegations) {
        // Apply undelegation to all networks
        for (n in network.values()) {
            val delta = staker_state_delta(
                network = n,
                cutover_time = staking_get_last_known_time(),
                new_provider = get_null_provider_account(),
                old_provider = _staking_get_current_delegate(removed_delegation),
                balance = null
);
            _staking_apply_staker_state_delta(removed_delegation, delta);
        }
    }
}


// Deposits and balances

function _staking_deposit_native_impl(amount: integer, delegateTo: pubkey? = null) {
    require_initialized();
    require(amount > 0, "Can't deposit nothing (or less)!");

    val staker = ft4.auth.authenticate();

    // Pull in the CHR
    require(amount < get_account_balance(staker), "Insufficent funds to deposit.");
    ft4.assets.Unsafe.transfer(staker, get_deposit_account(), get_asset(), amount);

    val existing = staker_state @? { .staker == staker and .latest and .network == network.CHR };
    val delta = staker_state_delta(
        network = network.CHR,
        balance = if (null != existing) existing.balance + amount else amount,
        cutover_time = null, new_provider = null, old_provider = null
    );
    _staking_apply_staker_state_delta(staker, delta);

    if (exists(delegateTo)) {
        val delegateToAccount = provider_account @ {.provider.pubkey == delegateTo};
        require(_staking_is_active_provider(delegateToAccount), "Must be active provider.");
        // Below check is duplicated, but less overhead than 2 wrapping functions.
        _staking_delegate(staker, delegateToAccount);
    }
}

function _staking_get_balance(staker: ft4.accounts.account) = _staking_get_balance_by_network(staker, network.CHR) + _staking_get_balance_by_network(staker, network.ETH) + _staking_get_balance_by_network(staker, network.BSC) ;
function _staking_get_balance_by_network(staker: ft4.accounts.account, network) = staker_state @? { .staker == staker and .latest and .network == network } ( .balance ) ?: 0;


// Legacy EVM events imports

function _staking_update_from_evm(staker: ft4.accounts.account, new_balance: integer, network) {
    require_initialized();
    val delta = staker_state_delta(
        network,
        balance = new_balance,
        cutover_time = null, new_provider = null, old_provider = null
    );
    _staking_apply_staker_state_delta(staker, delta);
}



// Withdrawals

function _staking_request_withdrawal_impl() {
    require_initialized();
    val staker = ft4.auth.authenticate();
    require(null == _staking_get_withdrawal_time(staker, network.CHR), "Only one withdrawal request at a time.");
    require(_staking_get_balance_by_network(staker, network.CHR) > 0, "Need something to withdraw.");
    _staking_request_withdrawal(staker, network.CHR);
}

// This operation needs to be called when an address was created by means others than ras_staking
// registration strategy.
// note: network_id is important only for smart contract stakers, for EOA stakers it is ignored
// should become irrelevant once we have hooks in eif hbridge
operation staking_import_evm_balance(address: byte_array, network_id: integer) {
    require_initialized();
    val staker = ft4.auth.authenticate();

    val account = eif.hbridge.find_ft4_account_for_address(address, network_id);
    require(exists(account), "No account link established for this address.");
    require(account == staker, "Address does not belong to the authenticated account.");

    flush_provisional_stake_balance(staker, address);
}

function _staking_request_withdrawal(staker: ft4.accounts.account, network) {
    _staking_delegate(staker, get_null_provider_account());

    // Make a new request
    require(_staking_last_known_time() > 0, "Require an actual time");
    create staker_withdrawal_request(network, staker_withdrawal_request_time=_staking_last_known_time(), staker=staker, false);
}

function _staking_cancel_withdrawal_impl() {
    require_initialized();
    val staker = ft4.auth.authenticate();
    update staker_withdrawal_request @? {not .used and .staker == staker} (used = true);
}

function _staking_withdraw_all() {
    require_initialized();

    val open_withdrawals = staker_withdrawal_request @* {
            not .used
        and .network == network.CHR
        and (.staker_withdrawal_request_time + chain_context.args.staking_withdrawal_delay_ms) < _staking_last_known_time()
    } ( $.to_struct() );

    for (withdrawal in open_withdrawals) {
        // Send the balance back to them through ft4
        ft4.assets.Unsafe.transfer(get_deposit_account(), withdrawal.staker, get_asset(), _staking_get_balance(withdrawal.staker));

        // Apply change
        val delta = staker_state_delta(
            network = network.CHR,
            cutover_time = _staking_last_known_time(),
            balance = 0,
            new_provider = null, old_provider = null
        );
        _staking_apply_staker_state_delta(withdrawal.staker, delta);
    }
}

function _staking_get_withdrawal_time(staker: ft4.accounts.account, network = network.CHR): timestamp? {
    val valid_request = staker_withdrawal_request @? {.staker == staker and not .used and .network == network};
    return
        if (null != valid_request)
            valid_request.staker_withdrawal_request_time + chain_context.args.staking_withdrawal_delay_ms
        else
            null
        ;
}

function _staking_is_active_provider(provider_account) = exists(provider @? {.pubkey == provider_account.provider.pubkey and .active});

function _staking_get_total_delegation_to(provider_account, _network: network): integer {
    return
        // Look at the full staker state 
        (s: staker_state) @ {
            .network == _network
            // consider only the latest state
            and s.latest
            // restricted to those currently on this provider according to the cut off date
            and (
                ( s.new_provider == provider_account and s.cutover_time <= _staking_last_known_time() )
                or
                ( s.old_provider == provider_account and s.cutover_time > _staking_last_known_time() )
            )
        } (
            // sum the balances
            @sum s.balance
        )
    ;
}

function _staking_delegate_impl(pubkey) {
    require_initialized();
    val provider_account = _staking_pubkey_to_provider(pubkey);
    require(_staking_is_active_provider(provider_account), "Must be active provider.");
    val staker = ft4.auth.authenticate();
    _staking_delegate(staker, provider_account);
}

function _staking_undelegate_impl() {
    require_initialized();
    val delegator = ft4.auth.authenticate();
    for(n in network.values()) {
        _staking_delegate_by_network(delegator, get_null_provider_account(), n);
}
}

// Rewards

function _staking_rewards_claimable_for(staker: ft4.accounts.account, network): integer {
    val since = (staker_payout @? {} (@max .staker_payout_time)) ?: 0;
    return _staking_rewards_claimable_since(staker, network, since);
}

function _staking_rewards_claimable_since(staker: ft4.accounts.account, network, since: integer): integer {

    // We are going to limit ourselves here by simply calculating the reward as of the last payout date at the
    // prevailing reward rate. This will give a "wrong" answer as a portion of the reward will be paid at the
    // new rate when it should have been on the old. This will not be significant.
    // The author would like to have done something more fun here tbh. Hopefully this will get easier as Rell
    // approaches its final form of a modern Tutorial D :)
    // TODO extend this query to handle the above accurately

    // So what we will do is consider all of the states, but we will cap the previous and current stake times
    // at the last payout date, which will cause periods enterly before the payout date to collapse to zero
    // duration, and the state during which the payout happened to be truncated to the payout date.
    // Each row also potentially needs to be cut in two, as the delegate could change to NO_ONE during it, we do
    // this by first considering the time before the cutoff date, and then the time afterwards (if any). 
    // We also need to recognise the last row, and for this row only, include the *present* balance extended to
    // the present date. In effect a last virtual row. (If we could UPSERT, we could cheaply create this row rather
    // than interpolating it.)

    val total_token_time = staker_state @ {
        .staker == staker and .network == network
    } (
        @sum(
            // Real and concluded states truncated by the last payment date
            (
                (
                    max(.staker_state_time, since) - max(.previous_staker_state_time, since)
                ) * (.previous_balance)
            )
            // TODO We need to consider the cutoff time
            +
            // Interpolated last row from latest row
            (
                when (.latest) {
                    true -> (_staking_last_known_time() - max(.staker_state_time, since)) * .balance;
                    else -> 0;
                }
            )
        )
    );

    val rate = _staking_get_current_rate() / millis_per_year;

    val token_reward = total_token_time * rate;
    return integer(token_reward); // Can only transfer whole minor units
}

function _staking_delegate(staker: ft4.accounts.account, provider_account) {
    require(_staking_get_balance(staker) > 0, "Must have a stake to delegate somewhere.");
    for(n in network.values()) {
        _staking_delegate_by_network(staker, provider_account, n);
    }
}

function _staking_get_current_delegate(staker: ft4.accounts.account, network = network.CHR) {
    val current_state = staker_state @? { .staker == staker and .latest and .network == network };
    return
        if  (empty(current_state)) get_null_provider_account()
    else if ( staking_get_last_known_time() >= current_state.cutover_time ) current_state.new_provider
    else    current_state.old_provider;
}

function _staking_delegate_by_network(delegator: ft4.accounts.account, provider: provider_account, _network: network) : boolean {

    // Is there an active withdrawal request for an EVM chain
    if ( [network.ETH, network.BSC].contains(_network)
            and exists (staker_withdrawal_request @? {not .used and .staker == delegator and .network == _network})
    ) {
        log("Quietly skip as we cannot cancel the withdrawal request from here.");
        return false;
    }

    // Clear any withdrawal request
    update staker_withdrawal_request @? {not .used and .staker == delegator and .network == _network} (used = true);

    // Get the values before messing with the flag
    val current_provider = _staking_get_current_delegate(delegator);

    // Apply change
    val delta = staker_state_delta(
        network = _network,
        cutover_time = _staking_cannot_change_before(),
        new_provider = provider,
        old_provider = current_provider,
        balance = null
    );
    _staking_apply_staker_state_delta(delegator, delta);

    return true;
}

function _staking_claim_rewards_impl() {
    require_initialized();
    require_admin();
    _staking_claim_rewards();
}

function _staking_claim_rewards() {
    var payout_list: list<(ft4.accounts.account, integer)> = [];
    var total_amount = 0;

    // Get a list of payouts
    for(staker in staker_state @* {} (@group .staker) ) {
        // Find the amounts
        val payout_amount = _staking_rewards_claimable_for(staker, network.CHR) + _staking_rewards_claimable_for(staker, network.BSC) + _staking_rewards_claimable_for(staker, network.ETH);
        payout_list.add((staker, payout_amount));
        total_amount += payout_amount;
    }

    // Do not start what we cannot finish
    if (get_account_balance(get_pool_account()) < total_amount) {
        log("Cannot pay rewards. Insufficient funds.");
        return;
    }

    // Do the payouts
    for(payment in payout_list) {
        val (staker, payout_amount) = payment;
        if(payout_amount > 0) {
            _pay_to(staker, payout_amount);
            log("Paid out %s to account id %s".format(payout_amount, staker.id));
        }
    }

    // Record payout
    create staker_payout(staker_payout_time = _staking_last_known_time());
}


// Shared rewards (triggered by a hook in the rewards logic)

function _staking_shared_rewards(pay_reward_result) {
    // We ignore reward debt here as it will flow through the reward term after the pool is refreshed
    val total_shared_reward = chain_context.args.rewards_share * pay_reward_result.payed_reward;

    // Find provider pubkey
    val provider_account = provider_account @? {pay_reward_result.payed_to};

    // In some edge cases during testing a public key may be absent
    if(empty(provider_account)) {
        log("Not provider public key for id: %s".format(pay_reward_result.payed_to.id));
        return;
    }

    // Find all the delegations
    val delegating_to =
        (s: staker_state) @* {
            // consider only the latest state
            s.latest
            // restricted to those currently on this provider according to the cut off date
            and (
                ( s.new_provider == provider_account and s.cutover_time <= _staking_last_known_time() )
                or
                ( s.old_provider == provider_account and s.cutover_time > _staking_last_known_time() )
            )
        } (
            @group staker = s.staker,
            @sum balance = s.balance
        )
    ;

    // Get total and divide through
    val total_delegation = delegating_to @ {} (@sum .balance);

    // Zero delegation check (should not occur in normal useage.)
    if (total_delegation == 0) return;

    // Run through and payout by share of delegation
    for (reward_share in delegating_to) {
        val share_amount = integer(total_shared_reward * (reward_share.balance / total_delegation));
        _pay_to(reward_share.staker, share_amount);
        log("Paid reward share of %s to %s. Based on a delegation of %s CHR.".format(share_amount, reward_share.staker.id, reward_share.balance));
    }
}

namespace ft4 {
    import lib.ft4.accounts;
    import lib.ft4.assets;
    import lib.ft4.auth;
}
import lib.auth;

val STAKING_NETWORK_ID_BSC = 56;
val STAKING_NETWORK_ID_ETH = 1;
val STAKING_NETWORK_ID_BSC_TEST = 97;

struct event_data {
    tnx_hash: byte_array;
    log_index: integer;
    signature: byte_array;
    contract_address: byte_array;
    name: text;
    indexed_values: list<gtv>;
    non_indexed_values: list<gtv>;
}

function _staking_network_id_to_enum(network_id: integer) = when (network_id) {
    STAKING_NETWORK_ID_ETH -> network.ETH;
    STAKING_NETWORK_ID_BSC -> network.BSC;
    STAKING_NETWORK_ID_BSC_TEST -> network.BSC;
    else -> network.CHR;
};

entity provisional_stake_balance {
    key address: byte_array, network;
    mutable staked_balance: integer;
}

function flush_provisional_stake_balance(account: ft4.accounts.account, address: byte_array) {
    val provisional = provisional_stake_balance @* { address };
    for (p in provisional) {
        _staking_update_from_evm(account, p.staked_balance, p.network);
        delete p;
    }
}

function __staking_evm_block(network_id: integer, evm_block_height: integer, evm_block_hash: byte_array, events: list<event_data>) {
    for (event in events) {
        val evm_address = byte_array.from_gtv(event.indexed_values[0]);

        val current_network = _staking_network_id_to_enum(network_id);
        if (current_network == network.CHR) {
            log("Unknown staking network id: ", network_id);
            return;
        }

        val ft4_account = eif.hbridge.find_ft4_account_for_address(evm_address, network_id);

        if (event.name == "WithdrawRequest") {
            if (exists(ft4_account)) {
                _staking_request_withdrawal(ft4_account, current_network);
            } else {
                delete provisional_stake_balance @? { evm_address, current_network };
            }
        } else if (event.name == "StakeUpdate") {
            val staked_balance = integer.from_gtv(event.non_indexed_values[0]);

            if (exists(ft4_account)) {
                _staking_update_from_evm(ft4_account, staked_balance, current_network);
            } else {
                val provisional = provisional_stake_balance @? { evm_address, current_network };
                if (exists(provisional)) {
                    provisional.staked_balance = staked_balance;
                } else {
                    create provisional_stake_balance (
                        .address = evm_address,
                        .network = current_network,
                        .staked_balance = staked_balance
                    );
                }
            }
        } else {
            log("Unknown EIF event: ", event.name);
        }
    }
}

function _staking_cannot_change_before(): timestamp = _staking_last_known_time() + chain_context.args.staking_rate_change_delay_ms;

// As per https://learn.chromia.com/courses/latest-known-time
function _staking_last_known_time()
    = if (op_context.exists) op_context.last_block_time else block @ {} (@max .timestamp) ?: 0;

function _pay_to(staker: ft4.accounts.account, amount: integer) {
    // We pay from the same pool account as provider rewards
    ft4.assets.Unsafe.transfer(get_pool_account(), staker, get_asset(), amount);
}

// As approach suggested by https://chromadev.zulipchat.com/#narrow/stream/316358-Protocols/topic/Little.20questions/near/421469052
val NULL_ACCOUNT_ID = "NULL".hash();
function get_null_provider_account() {
    // Relies on code that runs at initialisation
    val ft4_null = ft4.accounts.account @ { NULL_ACCOUNT_ID };
    val provider_null = provider @ {.pubkey == NULL_ACCOUNT_ID};
    return provider_account @ { .account == ft4_null };
}

function _staking_pubkey_to_provider(pubkey) {
    val provider_account = provider_account @? {.provider.pubkey == pubkey};
    require(provider_account, "No provider for this public key.");
    require(_staking_is_active_provider(provider_account), "Must be active provider.");
    return provider_account;
}

@extend(remove_provider_handler) function(provider_account) = _staking_offboard_provider(provider_account);
@extend(after_pay_reward) function(pay_reward_result) = _staking_shared_rewards(pay_reward_result);

function __staking_init() {
   _staking_set_rate_at(chain_context.args.staking_initial_reward_rate, _staking_last_known_time());

   // Create a sentinel value for null provider
    val ft4_null = create ft4.accounts.account(NULL_ACCOUNT_ID, type = "");
    val provider_null = create provider(pubkey = NULL_ACCOUNT_ID, tier = provider_tier.COMMUNITY_NODE_PROVIDER, active = false);
    create provider_account(account = ft4_null, provider = provider_null);
}

function __staking_begin_block(height: integer) {
    val last_payout_time = (staker_payout @? {} (@max .staker_payout_time)) ?: 0;
    val interval_since_last_payout = _staking_last_known_time() - last_payout_time;
    if(interval_since_last_payout > chain_context.args.staking_payout_interval_ms) {
        _staking_claim_rewards();
    }
    _staking_withdraw_all();
}

// It might be better for this to live in a table
enum network {
    BSC, ETH, CHR
}

entity staker_withdrawal_request {
    network: network;
    staker_withdrawal_request_time: timestamp;
    staker: ft4.accounts.account;
    mutable used: boolean;
    index staker;
    key staker_withdrawal_request_time, staker;
}

entity staker_payout {
    staker_payout_time: timestamp;
    key staker_payout_time;
}

entity staker_state {
    network: network;
    staker_state_time: timestamp;
    previous_staker_state_time: timestamp; // We have no look-back windowing functions
    staker: ft4.accounts.account;
    cutover_time: timestamp;
    new_provider: provider_account;
    old_provider: provider_account;
    balance: integer;
    previous_balance: integer;
    mutable latest: boolean; // We have no windowing functions, and want to group by other fields
    index staker;
}

struct staker_state_delta {
    network: network?; // Null means all networks
    cutover_time: timestamp?;
    new_provider: provider_account?;
    old_provider: provider_account?;
    balance: integer?;
}

entity reward_rate {
    reward_rate_time: timestamp;
    reward_rate: decimal;
    key reward_rate_time;
}

function _staking_apply_staker_state_delta(staker: ft4.accounts.account, delta: staker_state_delta) {
    // Apply to specified network or to all
    val networks = if (delta.network??) [delta.network!!] else network.values();

    for(n in networks) {
        // Snapshot existing state and/or initialise
        var existing = staker_state @? {.latest and .staker == staker and .network == n };
        if (empty(existing)) {
            create staker_state(
                network = n,
                staker_state_time = _staking_last_known_time(),
                previous_staker_state_time = 0,
                staker = staker,        
                balance = 0,    
                previous_balance = 0,
                cutover_time = _staking_last_known_time(),
                new_provider = get_null_provider_account(),
                old_provider = get_null_provider_account(),
                latest = true
            );
            existing = staker_state @ {.latest and .staker == staker and .network == n };
        }

        // Clear flag from any existing state
        update staker_state @? { .staker == staker and .latest and .network == n and .latest } ( latest = false );

        // Create new from existing state + delta
        create staker_state(
            network = n,
            staker_state_time = _staking_last_known_time(),
            previous_staker_state_time = existing.staker_state_time,
            staker = staker,
            cutover_time = delta.cutover_time ?: existing.cutover_time,
            new_provider = delta.new_provider ?: existing.new_provider,
            old_provider = delta.old_provider ?: existing.old_provider,
            balance = delta.balance ?: existing.balance,
            previous_balance = existing.balance,
            latest = true
        );

        // TODO Handle with extendable functions
        // Have we reduced the balance to zero, e.g. a complete withdrawal
        if (
            0 != existing.balance
            and
            0 == delta.balance ?: 0
            and
            delta.balance??
        ) {
            // Clear the withdrawal request
            update staker_withdrawal_request @ {.staker == staker and .network == n} (used = true);
        }
    }
}

// Global Settings

operation staking_set_rate_at(reward_rate: decimal, provider_rate: decimal, time: timestamp) {
