// Rates

query staking_get_current_rate(): decimal = _staking_get_current_rate();


// Delegations

query staking_get_current_delegate_on_network(account_id: byte_array, network): pubkey? {
    val account = ft4.accounts.Account(account_id);
    val current_delegation = _staking_get_current_delegate(account, network);
    return when(current_delegation) {get_null_provider_account() -> null; else -> current_delegation.provider.pubkey;};
}

query staking_get_current_delegate(account_id: byte_array): pubkey? {
    val account = ft4.accounts.Account(account_id);
    val current_delegation = _staking_get_current_delegate(account, network.CHR);
    return when(current_delegation) {get_null_provider_account() -> null; else -> current_delegation.provider.pubkey;};
}

query staking_get_next_delegation_change(account_id: byte_array) : (pubkey: pubkey, time: integer)? {
    val staker = ft4.accounts.Account(account_id);
    val existing = staker_state @ {.latest and .staker == staker and .network == network.CHR} ( (pubkey = .new_provider.provider.pubkey, time = .cutover_time) );
    return if (_staking_last_known_time() <= existing.time) existing else null;
}

query staking_get_total_delegation_to(pubkey) {
    val provider_account = provider_account @ {.provider.pubkey == pubkey};
    return _staking_get_total_delegation_to(provider_account, network.CHR) + _staking_get_total_delegation_to(provider_account, network.BSC) + _staking_get_total_delegation_to(provider_account, network.ETH);
}


// Withdrawals

query staking_get_withdrawal_time(account_id: byte_array): timestamp? {
    val staker = ft4.accounts.Account(account_id);
    return _staking_get_withdrawal_time(staker);
}


// Rewards

query staking_rewards_claimable_for(account_id: byte_array): integer {
    val staker = ft4.accounts.Account(account_id);
    return _staking_rewards_claimable_for(staker, network.CHR) + _staking_rewards_claimable_for(staker, network.BSC) + _staking_rewards_claimable_for(staker, network.ETH);
}

query staking_rewards_for(account_id: byte_array) {
    val staker = ft4.accounts.Account(account_id);
    return _staking_rewards_claimable_since(staker, network.CHR, 0) + _staking_rewards_claimable_since(staker, network.BSC, 0) + _staking_rewards_claimable_since(staker, network.ETH, 0);
}

query staking_get_rewards_paid(account_id: byte_array) {
    val account = ft4.accounts.Account(account_id);
    val total_since_zero = _staking_rewards_claimable_since(account, network.CHR, 0) +  _staking_rewards_claimable_since(account, network.ETH, 0) + _staking_rewards_claimable_since(account, network.BSC, 0);
    val unclaimed = _staking_rewards_claimable_for(account, network.CHR) + _staking_rewards_claimable_for(account, network.BSC) + _staking_rewards_claimable_for(account, network.ETH);
    return total_since_zero - unclaimed;
}


// Balances

query staking_get_balance(account_id: byte_array) {
    val account = ft4.accounts.Account(account_id);
    return _staking_get_balance(account);
}

query staking_get_native_balance(account_id: byte_array) {
    val account = ft4.accounts.Account(account_id);
    return _staking_get_balance_by_network(account, network.CHR);
}


// Statistics

query staking_total_stake() = staker_state @ { .latest } (@sum .balance);
query staking_total_accounts() = staker_state @ { .latest and .network == network.CHR } (@sum 1);


// Date utilites

query staking_get_cannot_change_before(): timestamp = _staking_cannot_change_before();
query staking_get_last_known_time() = _staking_last_known_time();

val min_stake_to_create_account = 10 * units_per_asset; // 10 CHR

operation ras_staking(
    evm_address: byte_array,
    main: ft4.accounts.auth_descriptor,
    disposable: ft4.accounts.auth_descriptor? = null
) {}

function ras_s_account_details(gtv) {
    val params = struct<ras_staking>.from_gtv(gtv);
    val signers = ft4.accounts.get_signers(params.main);
    return ft4.strategies.account_details(
        account_id = ft4.accounts.get_account_id_from_signers(signers),
        main = params.main,
        disposable = params.disposable
    );
}

function apply_stake_action(ft4.accounts.account, strategy_params_gtv: gtv) {
    val evm_address = struct<ras_staking>.from_gtv(strategy_params_gtv).evm_address;

    // this duplicates check in register_account, we do this because evm_address
    // might differ from auth descriptor's address
    // we could instead check if signers match
    val tx_operations = op_context.get_all_operations();
    val strategy_op = tx_operations[op_context.op_index-1];
    val message = ft4.strategies.get_register_account_message(strategy_op, op_context.get_current_operation());
    ft4.auth.verify_signers_with_message([evm_address], message);

    require( provisional_stake_balance @? { .address == evm_address, .staked_balance >= min_stake_to_create_account } ,
        "no stake or insufficient stake");

    flush_provisional_stake_balance(account, evm_address);
    eif.hbridge._link_evm_eoa_account(evm_address, account);
}

@extend(ft4.strategies.strategy)
function () = ft4.strategies.add_strategy(
    op = rell.meta(ras_staking),
    account_details = ras_s_account_details(*),
    action = apply_stake_action(*)
                );

function require_system_provider_signer_entity(): provider {
    for (signer in op_context.get_signers()) {
        val provider = provider @? { .pubkey == signer };
        if (provider != null and provider.system and provider.active) {
            return provider;
        }
    }
    require(false, "Expected system provider signature");
    return provider @ { x"" }; // Return to make compiler not complain about path without return statement (the require will always fail)
}

function require_system_provider_entity(pubkey): provider {
    for (signer in op_context.get_signers()) {
        if (signer == pubkey) {
            val provider = provider @? { .pubkey == signer };
            if (provider != null and provider.system and provider.active) {
                return provider;
            }
        }
    }
    require(false, "Expected system provider pubkey");
    return provider @ { x"" }; // Return to make compiler not complain about path without return statement (the require will always fail)
}

function has_pending_upgrade(container_name: text): boolean {
    val upgrade_ticket = upgrade_container_ticket @? { container_name };
    return upgrade_ticket != null and upgrade_ticket.ticket.state == ticket_state.PENDING;
}

function receive_ticket_container_result_message(body: gtv) {
    val message = ticket_container_result_message.from_gtv(body);
    val ticket = ticket @? { .rowid == rowid(message.ticket_id) };
    if (ticket == null) {
        log("ticket_id %s not found".format(message.ticket_id));
        return;
    }
    ticket.state = if (message.error_message == null) ticket_state.SUCCESS else ticket_state.FAILURE;
    ticket.error_message = message.error_message ?: "";

    when (ticket.type) {
        ticket_type.CREATE_CONTAINER -> {
            val specific_ticket = create_container_ticket @ { ticket };
            val cluster = cluster @ { .name == specific_ticket.cluster_name };
            when (ticket.state) {
                ticket_state.SUCCESS -> {
                    val container_name = message.container_name!!;
                    val cluster_name = message.cluster_name!!;
                    log("Successfully created container %s in cluster %s for ticket %s".format(container_name, cluster_name, message.ticket_id));
                    specific_ticket.container_name = container_name;
                    create lease(
                        container_name = container_name,
                        account = ticket.account,
                        container_units = specific_ticket.container_units,
                        extra_storage_gib = specific_ticket.extra_storage_gib,
                        cluster = cluster,
                        start_time = op_context.last_block_time,
                        duration_millis = specific_ticket.duration_millis,
                        auto_renew = specific_ticket.auto_renew
                    );
                }
                ticket_state.FAILURE -> {
                    log("Failed to create container for ticket %s".format(message.ticket_id));

                    ft4.assets.Unsafe.transfer(get_pool_account(), ticket.account, get_asset(), specific_ticket.cost);
                }
            }
        }
        ticket_type.UPGRADE_CONTAINER -> {
            val specific_ticket = upgrade_container_ticket @ { ticket };
            val cluster = cluster @ { .name == specific_ticket.cluster_name };
            when (ticket.state) {
                ticket_state.SUCCESS -> {
                    // Note: When we implement "move" the container name might change so we should check what name D1 returns
                    val upgraded_container_name = message.container_name!!;
                    val upgraded_cluster_name = message.cluster_name!!;
                    log("Successfully upgraded container %s for ticket %s".format(upgraded_container_name, message.ticket_id));
                    val current_lease = lease @ { .container_name == specific_ticket.container_name };
                    val currently_auto_renewed = current_lease.auto_renew;
                    val current_duration = current_lease.duration_millis;
                    val bridge_leases = delete_bridge_leases(current_lease);
                    delete current_lease;
                    val new_lease = create lease(
                        container_name = upgraded_container_name,
                        account = ticket.account,
                        container_units = specific_ticket.container_units,
                        extra_storage_gib = specific_ticket.extra_storage_gib,
                        cluster = cluster,
                        start_time = op_context.last_block_time,
                        duration_millis = current_duration,
                        auto_renew = currently_auto_renewed
                    );
                    transfer_bridge_leases_to_lease(new_lease, bridge_leases);
                }
                ticket_state.FAILURE -> {
                    log("Failed to upgrade container for ticket %s".format(message.ticket_id));

                    ft4.assets.Unsafe.transfer(get_pool_account(), ticket.account, get_asset(), specific_ticket.cost);
                }
            }
        }
    }
}

