val millis_per_day = 24 * 60 * 60 * 1000;
val millis_per_week = 7 * millis_per_day;
val millis_per_month = 30 * millis_per_day;
val millis_per_year = 365 * millis_per_day;

operation init() {
    require(state.initialized == false, "Economy chain is already initialized");
    state.initialized = true;

    val asset = register_assets();
    register_and_link_erc20_asset(asset);

    create_pool_account();

    create_deposit_account();

    create_chromia_foundation_account();

    __staking_init();

    log("Economy chain was initialized");
}

operation __begin_block(height: integer) {
    if (state.initialized) {
        if (not try_call(expire_leases(op_context.last_block_time, *))) log("Failed lease expiry.");
        if (not try_call(__staking_begin_block(height, *))) log("Failed staking payout.");
    }
}

operation __evm_block(network_id: integer, evm_block_height: integer, evm_block_hash: byte_array, events: list<event_data>) {
    _fn_evm_block(network_id, evm_block_height, evm_block_hash, events);
}

function _fn_evm_block(network_id: integer, evm_block_height: integer, evm_block_hash: byte_array, events: list<event_data>) {
    __staking_evm_block(network_id, evm_block_height, evm_block_hash, events);
}

function require_initialized() {
    require(state.initialized == true, "Economy chain is not initialized");
}

function require_pubkey(pubkey) {
    require(pubkey.size() == 33 or pubkey.size() == 65 or pubkey.size() == 1336, "Value is not pubkey: " + pubkey);
}

function require_tag(name) = require(tag @? { name }, "Tag with name %s does not exist".format(name));

function require_cluster(name: text) = require(cluster @? { name }, "No cluster exists with name %s".format(name));

function require_lease(container_name: text) = require(lease @? { container_name }, "No current lease for container %s".format(container_name));

function require_lease_duration(duration_weeks: integer) {
    require(duration_weeks >= economy_constants.min_lease_time_weeks, "duration_weeks must be at least %s weeks".format(economy_constants.min_lease_time_weeks));
    require(duration_weeks <= economy_constants.max_lease_time_weeks, "duration_weeks can be max %s weeks".format(economy_constants.max_lease_time_weeks));
}

function require_dapp_cluster(cluster_name: text) = require(cluster_name != system_cluster_name, "System cluster not allowed for operation");

function require_provider(pubkey) = require(provider @? { pubkey }, "No provider found with pubkey %s".format(pubkey));

function validate_entity_name(name: text) = require(
    name.matches("^[a-zA-Z0-9_]{0,64}$"),
    "Entity name can only contain letters, numerals, and underscores. Maximum allowed length is 64 characters."
);

@extend(ft4.auth.auth_handler)
function () = ft4.auth.add_auth_handler(
    scope = "claim_test_chr",
    flags = ["T"],
    message = claim_test_chr_auth_message(*)
);

function claim_test_chr_auth_message(gtv) =
    "Please sign the message\nto receive %s %s on account {account_id}".format(
        ft4.assets.format_amount_with_decimals(chain_context.args.amount_to_mint, chain_context.args.asset_decimals),
        chain_context.args.asset_symbol);

operation claim_test_chr() {
    require_initialized();

    val account = ft4.auth.authenticate();
    val user = require(user @? { account }, "No user for account %s".format(account.id));

    require(user.last_refill_millis + chain_context.args.test_chr_refill_limit_millis < op_context.last_block_time,
        "You have already claimed %s within the last 7 days, come back later".format(chain_context.args.asset_name));

    ft4.assets.Unsafe.mint(account, get_asset(), chain_context.args.amount_to_mint);
    user.last_refill_millis = op_context.last_block_time;
}

