@mount('eif.utils')
module;

function to_32_byte_array(array: byte_array): byte_array = (x"00").repeat(12) + array;

struct single_sig_args {
    flags: set<text>;
    signer: byte_array;
}

struct multi_sig_args {
    flags: set<text>;
    signatures_required: integer;
    signers: list<byte_array>;
}

/*
 * Returns VALID if valid.
 */
function check_single_sig_auth(args: byte_array, signers: list<byte_array>, required_flags: list<text>): utils.validation_result {
    if(signers.size() > 1) {
        return utils.invalid("Single sig Auth Descriptor must have only one signer.");
    }
    if (signers.size() < 1) {
        return utils.invalid("Single sig Auth Descriptor's signer list is empty.");
    }

    val ss_args = single_sig_args.from_bytes(args);
    if ( check_required_flags(ss_args.flags, required_flags)) {
        if (op_context.is_signer(signers[0])) {
            return utils.VALID;
        } else {
            return utils.invalid("The auth descriptor signer did not sign the transaction.");
        }
    } else {
        return utils.invalid("Some required flags " + required_flags.to_text() + " are missing on the (single sig) Auth Descriptor.");
    }
}

/*
 * Returns VALID if valid.
 */
function check_multi_sig_auth(args: byte_array, signers: list<byte_array>, required_flags: list<text>): utils.validation_result {
    val multi_sign_args = multi_sig_args.from_bytes(args);
    if (not (check_required_flags(multi_sign_args.flags, required_flags))) {
       return utils.invalid("Some required flags " + required_flags.to_text() + " are missing on the (multi sig) Auth Descriptor.");
    }
    var num_sign = multi_sign_args.signatures_required;
    for(s in signers) {
        if(op_context.is_signer(s)) {
            num_sign -= 1;
            if(num_sign < 1) {
                return utils.VALID;
            }
        }
    }
    return utils.invalid("Transaction must be signed by at least " + multi_sign_args.signatures_required + " signers in the Auth Descriptor.");
}

/*
 * Returns false if any of the required flags are missing from the "flags" set.
 */
function check_required_flags(flags: set<text>, required_flags: list<text>): boolean {
    return flags.contains_all(required_flags);
}

/*
 * Returns the set of flags found in the "args" parameter.
 */
function get_flags_from_args(a_t: auth_type, args: byte_array): set<text> {
    return when (a_t) {
        S -> single_sig_args.from_bytes(args).flags;
        M -> multi_sig_args.from_bytes(args).flags;
    };
}

/*
 * Returns VALID if authentication arguments are valid.
 */
function check_auth_args(a_t: auth_type, args: byte_array, signers: list<byte_array>, required_flags: list<text>): utils.validation_result {
    return when (a_t) {
        S -> check_single_sig_auth(args, signers, required_flags);
        M -> check_multi_sig_auth(args, signers, required_flags);
    };
}

function get_signers_from_encoded_auth_descriptor(a_t: auth_type, args: byte_array): list<byte_array>{
    var signers: list<byte_array>? = null;
    if (a_t == auth_type.S){
        signers = [single_sig_args.from_bytes(args).signer];
    }
    if (a_t == auth_type.M) {
        signers = multi_sig_args.from_bytes(args).signers;
    }
    //TODO: add extendable callback for custom types
    return require(signers, "Unknown auth_descriptor type"); // or return empty list?
}

function get_signers(auth_descriptor)
    = when (auth_descriptor.auth_type) {
        S -> [single_sig_args.from_gtv(auth_descriptor.args.to_gtv()).signer];
        M -> multi_sig_args.from_gtv(auth_descriptor.args.to_gtv()).signers;
    };

enum rule_variable {
	block_height,
	block_time,
	op_count
}

enum rule_operator {
	lt,
	le,
	eq,
	ge,
	gt
}

struct rule_expression {
	operator: rule_operator;
	variable: rule_variable;
	value: integer;
}

struct rule_parameters {
	variable: rule_variable;
	value: integer;
}

/*
 * Operator functions
 */

function greater_than(rule_parameters): rule_expression {
    return rule_expression(
        rule_parameters.variable,
        rule_operator.gt,
        rule_parameters.value
    );
}

function greater_or_equal(rule_parameters): rule_expression {
    return rule_expression(
        rule_parameters.variable,
        rule_operator.ge,
        rule_parameters.value
    );
}

function equals(rule_parameters): rule_expression {
    return rule_expression(
        rule_parameters.variable,
        rule_operator.eq,
        rule_parameters.value
    );
}

function less_than(rule_parameters): rule_expression {
    return rule_expression(
        rule_parameters.variable,
        rule_operator.lt,
        rule_parameters.value
    );
}

function less_or_equal(rule_parameters): rule_expression {
    return rule_expression(
        rule_parameters.variable,
        rule_operator.le,
        rule_parameters.value
    );
}

/*
 * Rule variable functions
 */

function block_height(integer): rule_parameters {
    return rule_parameters(
        rule_variable.block_height,
        integer
    );
}

function block_time(integer): rule_parameters {
    return rule_parameters(
        rule_variable.block_time,
        integer
    );
}

function op_count(integer): rule_parameters {
    return rule_parameters(
        rule_variable.op_count,
        integer
    );
}

function serialize_rules(rules: list<rule_expression>): gtv {
	if (rules.size() == 0) {
		return GTV_NULL;
	}
	if (rules.size() == 1) {
		return rule_expression_to_gtv(rules[0]);
	}

	val rules_gtv = ["and".to_gtv()];
	for (rule in rules) {
		rules_gtv.add(rule_expression_to_gtv(rule));
	}
	return rules_gtv.to_gtv();
}

function rule_expression_to_gtv(rule_expression): gtv = [
        rule_expression.operator.name.to_gtv(),
        rule_expression.variable.name.to_gtv(),
        rule_expression.value.to_gtv()
    ].to_gtv();

function rule_expression_from_gtv(gtv) {
	val components = list<gtv>.from_gtv(gtv);
	val operator_name = text.from_gtv(components[0]);
	val variable_name = text.from_gtv(components[1]);
	val value = integer.from_gtv(components[2]);

	val operator = require(
			rule_operator.values() @? { .name == operator_name },
			"Unknown rule operator %s".format(operator_name)
	);

	val variable = require(
			rule_variable.values() @? { .name == variable_name },
			"Unknown rule variable %s".format(variable_name)
	);

	return rule_expression(
			operator,
			variable,
			value
	);
}

function map_rule_expressions_from_gtv(gtv_rules: list<gtv>) {
	val rules = list<rule_expression>();
	for (rule in gtv_rules) {
		rules.add(rule_expression_from_gtv(rule));
	}
	return rules;
}

function have_violating_rules(auth_descriptor: account_auth_descriptor) =
	are_rules_violating(gtv.from_bytes(auth_descriptor.rules), load_variables(auth_descriptor.ctr));

function load_variables(op_count: integer): map<text, gtv> {
	val variables = map<text, gtv>();
	variables[rule_variable.op_count.name] = (op_count + 1).to_gtv();
	variables[rule_variable.block_height.name] = op_context.block_height.to_gtv();
	variables[rule_variable.block_time.name] = op_context.last_block_time.to_gtv();
	return variables;
}

function are_rules_violating(rules: gtv, variables: map<text, gtv>): boolean {
	if (rules == GTV_NULL) {
		return false;
	}

	val rules_gtv = list<gtv>.from_gtv(rules);

	if (rules_gtv[0] != "and".to_gtv()) {
		require(
			rules_gtv.size() == 3,
			"Expected a single rule expression, but got something else"
		); // This error will be caught on the next line as well, but like this we can give a better error message

		return is_rule_violated(rule_expression_from_gtv(rules_gtv.to_gtv()), variables);
	}

	return are_and_rules_violated(map_rule_expressions_from_gtv(rules_gtv.sub(1)), variables);
}

function is_rule_violated(rule: rule_expression, variables: map<text, gtv>): boolean {
	return not evaluate_int_variable_rule(rule, variables);
}

function are_and_rules_violated(rules: list<rule_expression>, variables: map<text, gtv>): boolean {
	for (rule in rules) {
		if (is_rule_violated(rule, variables)) {
			return true;
		}
	}
	return false;
}

function is_active(account_auth_descriptor) = are_rules_active(gtv.from_bytes(account_auth_descriptor.rules));

function are_rules_active(rules: gtv): boolean {
	if (rules == GTV_NULL) {
		return true;
	}

	val gtv_rules = list<gtv>.from_gtv(rules);
	if (gtv_rules[0] == "and".to_gtv()) {
		for (rule in gtv_rules.sub(1)) {
			if (not is_rule_active(rule_expression_from_gtv(rule))) {
				return false;
			}
		}
		return true;
	}

	return is_rule_active(rule_expression_from_gtv(gtv_rules.to_gtv()));
}

function is_rule_active(rule: rule_expression): boolean {
	when (rule.variable) {
		rule_variable.block_height -> {
			return is_block_height_rule_active(rule);
		}
		rule_variable.block_time -> {
			return is_block_time_rule_active(rule);
		}		
		rule_variable.op_count -> {
			return is_op_count_rule_active(rule);
		}
	}
}

/*
 *  Variables
 */

function evaluate_int_variable_rule(
	rule: rule_expression,
	variables: map<text, gtv>
): boolean {
	val current_value = variable_value(
		rule.variable,
		variables
	);
	val defined_value = rule.value;

	when (rule.operator) {
		rule_operator.lt -> {
			return current_value < defined_value;
		}
		rule_operator.le -> {
			return current_value <= defined_value;
		}
		rule_operator.eq -> {
			return current_value == defined_value;
		}
		rule_operator.ge -> {
			return current_value >= defined_value;
		}
		rule_operator.gt -> {
			return current_value > defined_value;
		}
	}
}

function variable_value(
	variable: rule_variable,
	variables: map<text, gtv>
): integer {
	when (variable) {
		rule_variable.block_height -> {
			return integer.from_gtv(variables[rule_variable.block_height.name]);
		}
		rule_variable.block_time -> {
			return integer.from_gtv(variables[rule_variable.block_time.name]);
		}
		rule_variable.op_count -> {
			return integer.from_gtv(variables[rule_variable.op_count.name]);
		}
	}
}

/*
 * Analyze the rules before assigning them to an authenticator descriptor
 */
function validate_auth_descriptor_rules(rules: gtv) {
 	if (rules == GTV_NULL) {
		return;
	}

	val rules_gtv = list<gtv>.from_gtv(rules);
	if (rules_gtv[0] != "and".to_gtv()) {
		validate_rule(rule_expression_from_gtv(rules_gtv.to_gtv()));
	} else {
		require(rules_gtv.size() <= chain_context.args.auth_descriptor.max_rules, "Too many rules");

		for (gtv_rule in rules_gtv.sub(1)) {
			validate_rule(rule_expression_from_gtv(gtv_rule));
		}
	}

	require((not are_rules_active(rules)) or (not are_rules_violating(rules, load_variables(op_count = 0))),
		"Active and invalid rules detected");
}

function validate_rule(rule: rule_expression) {
	when (rule.variable) {
		rule_variable.block_height -> {
			require(rule.value >= 0, "rule variable block_height must be a non-negative value");
		}
		rule_variable.block_time -> {
			require(rule.value >= 0, "rule variable block_time must be a non-negative value");
		}
		rule_variable.op_count -> {
			when (rule.operator) {
				rule_operator.lt -> require(rule.value > 1, "rule variable op_count must be a positive value greater than 1");
				rule_operator.le -> require(rule.value > 0, "rule variable op_count must be a positive value");
				else -> require(false, "rule variable op_count must be lt or le");
			}
		}
	}
}

function update_auth_descriptor_rule_variables(desc: account_auth_descriptor) {
	desc.ctr += 1;
	return desc;
}

/*
 * auth descriptor cleanup
 */

function delete_expired_auth_descriptors(account) {
	val auth_descriptors = account_auth_descriptor @* { account };

	val deleted_descriptors = set<account_auth_descriptor>();

	for (auth_descriptor in auth_descriptors) {
		if (is_active(auth_descriptor) and have_violating_rules(auth_descriptor)) {
			delete_auth_descriptor(auth_descriptor);
			deleted_descriptors.add(auth_descriptor);
		}
	}

	return deleted_descriptors;
}

/****************************************************************************************
 *                                     block_time                                       *
 ****************************************************************************************/

function is_block_time_rule_active(r: rule_expression): boolean {
	when (r.operator) {
		rule_operator.gt -> {
			return op_context.last_block_time > r.value;
		}
		rule_operator.ge,
		rule_operator.eq -> {
			return op_context.last_block_time >= r.value;
		}
		else -> {
			return true;
		}
	}
}


/****************************************************************************************
 *                                  block_height                                        *
 ****************************************************************************************/

function is_block_height_rule_active(r: rule_expression): boolean {
	when (r.operator) {
		rule_operator.gt -> {
			return op_context.block_height > r.value;
		}
		rule_operator.ge,
		rule_operator.eq -> {
			return op_context.block_height >= r.value;
		}
		else -> {
			return true;
		}
	}
}


/****************************************************************************************
 *                                     op_count                                         *
 ****************************************************************************************/

 function op_count_variable_initial_value(): gtv {
 	return (1).to_gtv();
 }

 function is_op_count_rule_active(rule: rule_expression): boolean {
 	return true;
 }

function AuthDescriptor(id: byte_array) = require(
    account_auth_descriptor @? { id },
    "Provided auth descriptor id does not exist %s".format(id)
);

function Account(id: byte_array) = require(
    account @? { id },
    "Account not found: %s".format(id)
);

struct auth_flags_config {
    mandatory: gtv = ["A", "T"].to_gtv();
    default: gtv? = null;
}

function get_raw_auth_flags_config() {
    return chain_context.args.auth_flags;
}

function get_auth_flags_config() {
    val flags = chain_context.args.auth_flags;
    val mandatory = parse_auth_flags(flags.mandatory);
    val default = if (flags.default??) parse_auth_flags(flags.default!!) else mandatory;

    return (
        mandatory = mandatory,
        default = default
    );
}

function parse_auth_flags(gtv) {
    var flags = list<text>();

    if (utils.is_list(gtv)) {
        flags = require(
            try_call(list<text>.from_gtv(gtv, *)),
            "Cannot parse auth flags. Expected flags list, but found <%s>".format(gtv)
        );
    } else if (utils.is_text(gtv)) {
        flags = (text.from_gtv(gtv).split(",")) @* {} ($.trim());
    } else {
        require(false, "Expected flags list or comma separated flags list, but found <%s>".format(gtv));
    }

    require_valid_auth_flags(flags);

    return flags;
}

function require_valid_auth_flags(flags: list<text>) {
    val invalid_flags = flags @* { not $.matches("[a-z_A-Z]+") };
    require(
        empty(invalid_flags),
        "Found invalid flags <%s>".format(invalid_flags)
    );
}

@mount('ft4')
module;

import ^^.utils;
import ^^.version;

val GTV_NULL = null.to_gtv();
val GTV_NULL_BYTES = null.to_gtv().to_bytes();

struct rate_limit_config {
    active: boolean = true;
	max_points: integer = 10;
    recovery_time: integer = 5000;
    points_at_account_creation: integer = 1;
}

struct auth_descriptor_config {
    max_rules: integer = 8;
    max_number_per_account: integer = 10;
}

struct module_args {
	rate_limit: rate_limit_config = rate_limit_config();
    auth_descriptor: auth_descriptor_config = auth_descriptor_config();
    auth_flags: auth_flags_config = auth_flags_config();
}

val AUTH_DESCRIPTORS_PER_ACCOUNT_UPPER_BOUND = min(
    200,
    chain_context.args.auth_descriptor.max_number_per_account
);

function get_auth_descriptor_config() = chain_context.args.auth_descriptor;

/**
 * Constant that represents account type for regular user accounts 
 * created with `create_account_with_auth`.
 */
val ACCOUNT_TYPE_USER = "FT4_USER";

enum auth_type {
    S, M,
}

struct auth_descriptor {
    auth_type;
    args: list<gtv>;
    rules: gtv;
}

entity account {
    key id: byte_array;
    index type: text;
}

entity main_auth_descriptor {
    key account;
    key auth_descriptor: account_auth_descriptor;
}

entity account_auth_descriptor {
    id: byte_array;
    key account, id;
    index id;
    auth_type;
    args: byte_array;
    rules: byte_array;
    mutable ctr: integer;
    created: timestamp;
}

entity auth_descriptor_signer {
    key account_auth_descriptor, id: byte_array;
}

// rate limiter
entity rl_state {
    key account;
    mutable points: integer;
    mutable last_update: timestamp;
    mutable recovery_time: timestamp;
}


function add_auth_descriptor(account, auth_descriptor): account_auth_descriptor {
    require(
        (account_auth_descriptor @ { account } (@sum 1))  <
            AUTH_DESCRIPTORS_PER_ACCOUNT_UPPER_BOUND,
        "Max <%d> auth descriptor count reached. Delete some before adding new ones."
            .format(AUTH_DESCRIPTORS_PER_ACCOUNT_UPPER_BOUND)
    );

    val id = auth_descriptor.hash();

    validate_auth_descriptor_args(auth_descriptor);
    validate_auth_descriptor_rules(auth_descriptor.rules);

    val account_auth_descriptor = create account_auth_descriptor (
        account, 
        id,
        auth_descriptor.auth_type,
        args = auth_descriptor.args.to_gtv().to_bytes(),
        rules = auth_descriptor.rules.to_gtv().to_bytes(),
        created = utils.latest_time(),
        ctr = 0
    );

    add_signers(account, auth_descriptor, account_auth_descriptor);
    return account_auth_descriptor;
}

/**
 * Deletes old main auth descriptor and sets provided auth descriptor as main auth descriptor
 */
function update_main_auth_descriptor(account, auth_descriptor) {
    delete_main_auth_descriptor(account);
    val account_auth_descriptor = add_auth_descriptor(account, auth_descriptor);
    set_main_auth_descriptor(account, account_auth_descriptor);
}

function delete_main_auth_descriptor(account) {
    val main_auth_descriptor = require(
        main_auth_descriptor @? { account },
        "Error deleting main auth descriptor of account <%s>. Auth descriptor not found".format(account.id)
    );

    val auth_descriptor = main_auth_descriptor.auth_descriptor;
    delete main_auth_descriptor;
    delete_auth_descriptor(auth_descriptor);
}

function set_main_auth_descriptor(account, account_auth_descriptor) {
    require(
        empty(main_auth_descriptor @? { account }),
        "Error setting main auth descriptor. Main auth descriptor already exists"
    );

    create main_auth_descriptor(account, account_auth_descriptor);
}

function delete_auth_descriptor(auth_descriptor: account_auth_descriptor) {
    require(
        main_auth_descriptor @? { auth_descriptor } == null,
        "Cannot delete main auth descriptor"
    );
    delete auth_descriptor_signer @* { auth_descriptor };
    delete auth_descriptor;
}

function delete_all_auth_descriptors_except_main(account) {
    val main = main_auth_descriptor @ { account } ( .auth_descriptor );
    delete (ads: auth_descriptor_signer, ad: account_auth_descriptor) @* {
        ad.account == account,
        ad != main,
        ads.account_auth_descriptor == ad
    };

    delete account_auth_descriptor @* {
       .account == account,
       $ != main
    };
}

function create_account_with_auth(auth_descriptor, account_id: byte_array? = null): account {
    require(auth_descriptor.rules == GTV_NULL, "Cannot create an account with a restricted auth descriptor");

    var flags = get_flags(auth_descriptor);
    val mandatory = get_auth_flags_config().mandatory;
    require(
        flags.contains_all(mandatory),
        "Some of mandatory flags <%s> missing, found only <%s>".format(mandatory, flags)
    );

    val id = account_id ?: get_account_id_from_signers(get_signers(auth_descriptor));
    val account = create account(id, type = ACCOUNT_TYPE_USER);

    val main = add_auth_descriptor(account, auth_descriptor);
    create main_auth_descriptor(account, main);

    create_rate_limiter_state_for_account(account);

    return account;
}

/**
 * Creates an account without auth descriptor. Used to create different "system" account types,
 * that cannot be directly accessed, e.g. POOL, FEE, BLOCKCHAIN, ... accounts.
 * 
 * @param account_id    account id
 * @param type          account type specified as a free form text. Usually uppercase.
 */
function create_account_without_auth(account_id: byte_array, type: text): account {
    return create account(
        id = account_id,
        type = type
    );
}

/**
 * Finds or creates an account of specific type.
 *
 * @param account_id    account id
 * @param type          account type 
 */
function ensure_account_without_auth(account_id: byte_array, type: text): account {
    val account = account @? { .id == account_id };
    if (account??) {
        require(
            account.type == type,
            "Found account <%s> of invalid type. Expected <%s>, found <%s>".format(account.id, type, account.type)
        );

        return account;
    } else {
        return create_account_without_auth(account_id, type);
    }
}

function get_flags(auth_descriptor) {
    return when (auth_descriptor.auth_type) {
        S -> single_sig_args.from_gtv(auth_descriptor.args.to_gtv()).flags;
        M -> multi_sig_args.from_gtv(auth_descriptor.args.to_gtv()).flags;
    };
}

/**
* Checks if an `account_auth_descriptor` has all the specified flags
*/
function has_flags(account_auth_descriptor, required_flags: list<text>): boolean {
    val flags = get_flags_from_args(account_auth_descriptor.auth_type, account_auth_descriptor.args);
    return flags.contains_all(required_flags);
}

function add_signers(account, auth_descriptor, account_auth_descriptor, safe: boolean = true) {
    create auth_descriptor_signer(
        get_signers(auth_descriptor) @* {}
            (struct<auth_descriptor_signer>(account_auth_descriptor, id = $))
    );
}

function get_account_id_from_signers(signers: list<byte_array>) {
    require(signers.size() > 0, "Cannot derive account id. Signers list is empty");
    return if (signers.size() == 1) signers[0].hash() else signers @* {} (@sort $).hash();
}

function auth_descriptor_by_id(account, id: byte_array) = require(
    account_auth_descriptor @? { account, id },
    "Auth descriptor '%s' not found for account '%s'".format(id, account.id)
);

function account_by_id(id: byte_array) = require(
    account @? { id },
    "Account not found: '%s'".format(id)
);

function single_sig_auth_descriptor(signer: byte_array, flags: set<text>) = auth_descriptor(
    auth_type = auth_type.S,
    args = list<gtv>.from_gtv(single_sig_args(
        flags = flags,
        signer = signer
    ).to_gtv()),
    GTV_NULL
);

function multi_sig_auth_descriptor(signers: list<byte_array>, signatures_required: integer, flags: set<text>) = auth_descriptor(
    auth_type = auth_type.M,
    args = list<gtv>.from_gtv(multi_sig_args(
        signers = signers,
        signatures_required = signatures_required,
        flags = flags
    ).to_gtv()),
    GTV_NULL
);

function get_auth_descriptors(id: byte_array) {
    return account_auth_descriptor @* {
        .account.id == id
    } (
        get_auth_descriptor_data($.to_struct())
    );
}

function get_auth_descriptors_by_signer(account_id: byte_array, signer: byte_array) {
    return auth_descriptor_signer @* {
        .account_auth_descriptor.account.id == account_id,
        .id == signer
    } (
        get_auth_descriptor_data(.account_auth_descriptor.to_struct())
    );
}

function get_auth_descriptor_data(ad: struct<account_auth_descriptor>) {
    return (
        id = ad.id,
        account_id = ad.account.id,
        auth_type = ad.auth_type,
        args = gtv.from_bytes(ad.args),
        rules = gtv.from_bytes(ad.rules),
        created = ad.created
    );
}

function get_paginated_accounts_by_signer(id: byte_array, page_size: integer?, page_cursor: text?) {
    val before_rowid = utils.before_rowid(page_cursor);
    return auth_descriptor_signer @* {
        id,
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data=.account_auth_descriptor.account.to_struct().to_gtv_pretty(),
            rowid=.rowid
        )
    ) limit utils.fetch_data_size(page_size); 
}

function get_paginated_accounts_by_ad_id(id: byte_array, page_size: integer?, page_cursor: text?) {
    val before_rowid = utils.before_rowid(page_cursor);
    return account_auth_descriptor @* {
        .id == id,
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data=.account.id.to_gtv_pretty(),
            rowid=.rowid
        )
    ) limit utils.fetch_data_size(page_size);
}

function get_paginated_accounts_by_type(type: text, page_size: integer?, page_cursor: text?) {
    val before_rowid = utils.before_rowid(page_cursor);
    return account @* {
        .type == type,
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data = .id.to_gtv(),
            rowid = .rowid
        )
    ) limit utils.fetch_data_size(page_size);    
}

function validate_auth_descriptor_args(auth_descriptor) {
    when (auth_descriptor.auth_type) {
        S -> single_sig_args.from_gtv(auth_descriptor.args.to_gtv());
        M -> multi_sig_args.from_gtv(auth_descriptor.args.to_gtv());
    }
}

function get_max_allowed_auth_descriptor_rules() = chain_context.args.auth_descriptor.max_rules;

/**
 * Extend this function to have different rate limiting for different accounts.
 *
 * @param account  the account
 *
 * @return rate limit configuration for the account, or `null` to use default config from blockchain configuration.
 */
@extendable
function account_rate_limit_config(account): rate_limit_config? = null;

function rate_limit(account) {
    val rl_config = get_rate_limit_config_for_account(account);

    if (rl_config.active == false) return;

    val max_counter = rl_config.max_points;
    val recovery_time = rl_config.recovery_time;
    val stat = require(
        rl_state@?{account} (.points, .last_update), 
        "Rate limiter state not found for the account with ID: %s".format(account.id)
    );
    val delta = utils.latest_time() - stat.last_update;
    var got_points = 0;
    var update_time = stat.last_update;

    if (delta > recovery_time) {
        got_points = delta / recovery_time;
        update_time = stat.last_update + got_points * recovery_time;
        if (got_points + stat.points > max_counter) {
            got_points = max_counter - stat.points;
            // if user is at maximum reset his timer
            update_time = utils.latest_time();
        }
    }

    require(stat.points + got_points > 0, "Insufficient rate limiter points");

    update rl_state @ { account } (
        .points += got_points - 1,
        .last_update = update_time
    );
}

function current_rate_limit_points(rate_limit_config, rl_state, current_timestamp: timestamp) {
    val delta = current_timestamp - rl_state.last_update;
    return if (delta > rate_limit_config.recovery_time)
        min(rate_limit_config.max_points, rl_state.points + delta / rate_limit_config.recovery_time)
    else
        rl_state.points;
}

function add_rate_limit_points(account, amount: integer) {
    var state = require(
        rl_state@?{account}, 
        "Rate limiter state not found for the account with ID: %s".format(account.id)
    );
	state.points += amount;
}

function get_rate_limit_config(): rate_limit_config = chain_context.args.rate_limit;

function get_rate_limit_config_for_account(account): rate_limit_config =
    if (chain_context.args.rate_limit.active == false)
        chain_context.args.rate_limit
    else
        account_rate_limit_config(account) ?: chain_context.args.rate_limit;

function create_rate_limiter_state_for_account(account) {
    val rl_config = get_rate_limit_config_for_account(account);

    val max_points = rl_config.max_points;
    val recovery_time = rl_config.recovery_time;
    val points_at_start = rl_config.points_at_account_creation;

    create rl_state(account, .points = points_at_start, .last_update = utils.latest_time(), recovery_time);
}

function get_register_account_message(
    strategy_operation: gtx_operation,
    register_account_operation: gtx_operation
) {
    val strategy = get_strategy(strategy_operation.name);

    val account_details = strategy.account_details(strategy_operation.args.to_gtv());

    var message = "Blockchain: %s\n\nPlease sign the message to register account\n\nAccount ID:\n%s\n\n"
        .format(
            chain_context.blockchain_rid,
            account_details.account_id
        );

    message = message + auth_message_operation_details(register_account_operation);
    message = message + auth_message_auth_descriptors_details(account_details.main, account_details.disposable);

    return message;
}

function auth_message_operation_details(op: gtx_operation): text {
    var message = "Operation:\n%s\n\n".format(op.name);
    if (op.args.size() > 0) {
        message = message + "Parameters:\n";
        for (parameter in op.args) {
            message = message + "- %s\n".format(parameter);
        }
        message = message + "\n\n";
    }
    return message;
}

function auth_message_auth_descriptors_details(
    main: accounts.auth_descriptor, 
    disposable: accounts.auth_descriptor? = null
): text {
    var message = "Main:\n" + auth_message_auth_descriptor(main);

    if (disposable??) {
        message = message + "\n\nDisposable:\n" + auth_message_auth_descriptor(disposable);
    }

    return message;
}

function auth_message_auth_descriptor(accounts.auth_descriptor)
    = when (auth_descriptor.auth_type) {
        S -> auth_message_single_sig(accounts.single_sig_args.from_gtv(auth_descriptor.args.to_gtv()));
        M -> auth_message_multi_sig(accounts.multi_sig_args.from_gtv(auth_descriptor.args.to_gtv()));
    };

function auth_message_single_sig(args: accounts.single_sig_args)
    = "Signer:\n%s\n\nFlags:\n%s\n".format(args.signer, args.flags);

function auth_message_multi_sig(args: accounts.multi_sig_args) {
    var message = "Signers:\n";
    for (signer in args.signers) {
        message = message + signer + "\n";
    }
    message = message + "\nRequired signatures: %d\n\n".format(args.signatures_required);
    return message + "Flags:\n%s".format(args.flags);
}

@mount("ft4")
module;

import ^^^.core.accounts;
import ^^^.core.auth;

function get_strategy(strategy_name: name): _strategy {
    val strategies = strategy();
    require(strategy_name in strategies, "Strategy <%s> is not loaded or does not exist.".format(strategy_name));
    return strategies[strategy_name];
}

function is_strategy_op(op: gtx_operation): boolean {
    val strategy_operations = strategy().values() @* {} ($.op.mount_name);
    return op.name in strategy_operations;
}

function register_account(): accounts.account {
    val tx_operations = op_context.get_all_operations();
    val strategy_op = tx_operations[op_context.op_index-1];
    val strategy_name = strategy_op.name;
    val strategy_params = strategy_op.args.to_gtv();

    val strategy = get_strategy(strategy_name);
    val account_details = strategy.account_details(strategy_params);

    var signers = accounts.get_signers(account_details.main);
    if (account_details.disposable??) {
        signers.add_all(accounts.get_signers(account_details.disposable!!));
    }

    val message = get_register_account_message(strategy_op, op_context.get_current_operation());
    auth.verify_signers_with_message(signers, message);

    val account_id = account_details.account_id;

    before_register_account(account_id);

    val account = accounts.create_account_with_auth(account_details.main, account_id);
    if (account_details.disposable??) {
        accounts.add_auth_descriptor(account, account_details.disposable!!);
    }

    strategy.action(account, strategy_params);

    after_register_account(account);

    return account;
}

@extendable function before_register_account(account_id: byte_array);

@extendable function after_register_account(accounts.account);

@extendable 
function strategy(): map<name, _strategy>;

struct _strategy {
    op: rell.meta;
    account_details: (gtv) -> account_details;
    action: (accounts.account, gtv) -> unit;
}

struct account_details {
    account_id: byte_array;
    main: accounts.auth_descriptor;
    disposable: accounts.auth_descriptor? = null;
}

function add_strategy(op: rell.meta, account_details: (gtv) -> account_details, action: ((accounts.account, gtv) -> unit)? = null)
    = [op.mount_name: _strategy(op, account_details, action ?: _no_action(*))];

function _no_action(accounts.account, strategy_params: gtv) {}

function is_value_allowed(value: byte_array, allowlist) {
    return 
        allowlist.allow_all
        or
        value in allowlist.allowed_values;
}

function is_blockchain_allowed(rule, blockchain_rid: byte_array) {
    val bc = rule.blockchains;
    return is_value_allowed(blockchain_rid, bc);
}

function is_sender_allowed(rule, sender_id: byte_array) {
    val sender = rule.senders;
    return is_value_allowed(sender_id, sender);
}

function is_recipient_allowed(rule, recipient_id: byte_array, sender_id: byte_array) {
    if (rule.require_same_address) {
        return recipient_id == sender_id;
    }
    return is_value_allowed(recipient_id, rule.recipients);
}

function is_asset_amount_allowed(rule, asset: assets.asset, amount: big_integer) {
    if (rule.allow_all_assets) return true;
    var min_amount = 0L;
    for (asset_limit in rule.asset_limits) {
        if ((asset_limit.id != null and asset_limit.id!! == asset.id) or
            (asset_limit.name != null and asset_limit.name!! == asset.name and
                asset_limit.issuing_blockchain_rid != null and asset_limit.issuing_blockchain_rid!! == asset.issuing_blockchain_rid)) {
            min_amount = asset_limit.min_amount;
        }
    }
    if (min_amount > 0L) {
        return amount >= min_amount;
    } else {
        return false;
    }
}

function has_tx_expired(rule, tx_start_timestamp: timestamp) {
    val timeout_millis = rule.timeout_days * utils.MILLISECONDS_PER_DAY;
    return tx_start_timestamp + timeout_millis < utils.latest_time();
}

function is_strategy_active(rule, strategy: text) {
    val strats = rule.strategies;
    return strategy in strats;
}

function find_allowed_rules(
    from_chain: byte_array,
    from_id: byte_array,
    to_id: byte_array,
    asset: assets.asset,
    amount: big_integer
): map<text,rule> {
    val cfg = get_config();
    val allowed_rules = cfg @* {
        is_blockchain_allowed($, from_chain),
        is_sender_allowed($, from_id),
        is_recipient_allowed($, to_id, from_id),
        is_asset_amount_allowed($, asset, amount)
    };

    val rule_map = map<text,rule>();
    for (rule in allowed_rules) {
        for (strat in rule.strategies) {
            rule_map[strat] = rule;
        }
    }
    return rule_map;
}

function find_allowed_assets(sender_blockchain_rid: byte_array, sender_id: byte_array, recipient_id: byte_array):
        map<byte_array, big_integer>? {
    val cfg = get_config();
    val allowed_rules = cfg @* {
        is_blockchain_allowed($, sender_blockchain_rid),
        is_sender_allowed($, sender_id),
        is_recipient_allowed($, recipient_id, sender_id)
    };

    val allowed_assets = map<byte_array, big_integer>();
    for (rule in allowed_rules) {
        val resolved_assets = resolve_allowed_assets(rule);
        if (resolved_assets == null) return null;
        allowed_assets.put_all(resolved_assets);
    }
    return allowed_assets;
}

function resolve_allowed_assets(rule): map<byte_array, big_integer>? {
    val allowed_assets = map<byte_array, big_integer>();
    if (rule.allow_all_assets) return null;
    for (asset_limit in rule.asset_limits) {
        val asset_id = asset_limit.id ?:
            assets.asset @? { .name == asset_limit.name!!, .issuing_blockchain_rid == asset_limit.issuing_blockchain_rid!! } (.id);
        if (asset_id != null) allowed_assets[asset_id] = asset_limit.min_amount;
    }
    return allowed_assets;
}

val _CONFIG_ERROR_TEXT = "Error in moduleArgs (lib.ft4.core.accounts.strategy.transfer): ";

struct allowlist {
    allow_all: boolean = false;
    allowed_values: list<byte_array> = [];
}

struct asset_limit {
    id: byte_array? = null;
    issuing_blockchain_rid: byte_array? = null;
    name: text? = null;
    min_amount: big_integer;
}

struct rule {
    timeout_days: integer = 0;
    strategies: list<text> = [];

    blockchains: allowlist = allowlist();
    senders: allowlist = allowlist();
    recipients: allowlist = allowlist();

    require_same_address: boolean = false;

    allow_all_assets: boolean = false;
    asset_limits: list<asset_limit> = list<asset_limit>();
}

function get_config(config_gtv: gtv = chain_context.args.rules): list<rule> {
    val config = list<rule>();

    val inputs = list<module_args_list_element>.from_gtv_pretty(config_gtv);

    for (input in inputs) {
        val strats = if (utils.is_list(input.strategy))
            list<text>.from_gtv(input.strategy)
        else [text.from_gtv(input.strategy)];

        val sender_res = parse_account_ids_from_gtv(
            input.sender
        );

        val recipient_res = parse_account_ids_from_gtv(
            input.recipient
        );

        require(
            sender_res.require_same == recipient_res.require_same,
            _CONFIG_ERROR_TEXT + "'X' should appear in both or none of recipient and sender."
        );

        var allow_all_assets: boolean;
        var asset_limits: list<asset_limit>;
        val res = parse_asset_limits_from_gtv(input.asset);
        if (res == null) {
            allow_all_assets = true;
            asset_limits = list<asset_limit>();
        } else {
            allow_all_assets = false;
            asset_limits = res;
        }

        require(input.timeout_days >= 0, "timeout_days cannot be negative");
        config.add(
            rule(
                timeout_days = input.timeout_days,
                strategies = strats,
                blockchains =
                    parse_blockchains_from_gtv(input.sender_blockchain),
                senders = sender_res.allowlist,
                recipients = recipient_res.allowlist,
                require_same_address = sender_res.require_same,
                allow_all_assets,
                asset_limits
            )
        );
    }
    return config;
}

function parse_account_ids_from_gtv(gtv): (
    allowlist: allowlist,
    require_same: boolean
) {
    if (utils.is_list(gtv)) {
        val allowed_values = list<byte_array>();
        val gtv_list = list<gtv>.from_gtv(gtv);

        for (element in gtv_list) {
            val parsed_element = parse_account_id_single_value_from_gtv(element);
            if (parsed_element.allow_all) {
                require(
                    gtv_list.size() == 1,
                    _CONFIG_ERROR_TEXT + "using multiple values alongside '*' and 'X' is not allowed."
                );
                return (allowlist=allowlist(true), require_same=parsed_element.is_x);
            } else allowed_values.add(parsed_element.allowed_value!!);
        }
        return (
            allowlist = allowlist(allowed_values),
            require_same = false
        );
    } else {
        val parsed_gtv = parse_account_id_single_value_from_gtv(gtv);
        return (
            allowlist = allowlist(
                parsed_gtv.allow_all,
                if (parsed_gtv.allowed_value??) [parsed_gtv.allowed_value!!] else list<byte_array>()
            ),
            require_same = parsed_gtv.is_x
        );
    }
}

function parse_account_id_single_value_from_gtv(gtv): (
    allow_all: boolean,
    allowed_value: byte_array?,
    is_x: boolean
) {
    var allow_all = false;
    var allowed_value: byte_array? = null;
    var is_x = false;

    if (utils.is_text(gtv)) { // "*" or "abcdef"
        val input = text.from_gtv(gtv);
        if (input == "*") {
            allow_all = true;
        } else if (input == "X") {
            is_x = true;
            allow_all = true;
        } else {
            allowed_value = try_call(byte_array.from_hex(input, *));
            require(
                allowed_value,
                _CONFIG_ERROR_TEXT +
                "sender and recipient only allow blockchain RIDs, 'X' and '*'. Received <%s>."
                    .format(input)
            );
        }
    } else {
        require(
            utils.is_byte_array(gtv),
            _CONFIG_ERROR_TEXT +
            "sender and recipient fields only support strings, byte arrays and lists of these types. Received <%s>."
                .format(gtv)
        );
        allowed_value = byte_array.from_gtv(gtv);
    }

    return (
        allow_all = allow_all,
        allowed_value = allowed_value,
        is_x = is_x
    );
}

function parse_blockchains_from_gtv(gtv): allowlist {
    if (utils.is_list(gtv)) {
        val allowed_values = list<byte_array>();
        val gtv_list = list<gtv>.from_gtv(gtv);

        for (element in gtv_list) {
            val parsed_element = parse_blockchain_single_value_from_gtv(element);
            if (parsed_element.allow_all) {
                require(
                    gtv_list.size() == 1,
                    _CONFIG_ERROR_TEXT + "using multiple values alongside '*' is not allowed."
                );
                return allowlist(true);
            } else allowed_values.add(parsed_element.allowed_value!!);
        }
        return allowlist(allowed_values);
    } else {
        val parsed_gtv = parse_blockchain_single_value_from_gtv(gtv);
        return allowlist(
            parsed_gtv.allow_all,
            if (parsed_gtv.allowed_value??) [parsed_gtv.allowed_value!!] else list<byte_array>()
        );
    }
}

function parse_blockchain_single_value_from_gtv(gtv): (
    allow_all: boolean,
    allowed_value: byte_array?
) {
    var allow_all = false;
    var allowed_value: byte_array? = null;

    if (utils.is_text(gtv)) { // "*" or "$" or "abcdef"
        val input = text.from_gtv(gtv);
        if (input == "*") {
            allow_all = true;
        } else if (input == "$") {
            allowed_value = chain_context.blockchain_rid;
        } else {
            allowed_value = try_call(byte_array.from_hex(input, *));
            require(
                allowed_value,
                _CONFIG_ERROR_TEXT +
                "sender_blockchain only allows blockchain RIDs, '$' and '*'. Received <%s>."
                    .format(input)
            );
        }
    } else {
        require(
            utils.is_byte_array(gtv),
            _CONFIG_ERROR_TEXT + "sender_blockchain only supports strings, byte arrays and lists of these types. Received <%s>."
                .format(gtv)
        );
        allowed_value = byte_array.from_gtv(gtv);
    }

    return (
        allow_all = allow_all,
        allowed_value = allowed_value
    );
}

function parse_asset_limits_from_gtv(gtv): list<asset_limit>? {
    if (utils.is_dict(gtv)) {
        val input = map<name, gtv>.from_gtv_pretty(gtv);
        return [parse_asset_limit(input)];
    } else if (utils.is_list(gtv)) {
        val inputs = list<map<name, gtv>>.from_gtv_pretty(gtv);
        return inputs @* {} (parse_asset_limit($));
    } else {
        require(
            gtv == "*".to_gtv(),
            _CONFIG_ERROR_TEXT + "asset only accepts '*' and a list of ids and minimum amounts."
        );
        return null;
    }
}

function parse_asset_limit(input: map<name, gtv>): asset_limit {
    require("id" in input or "name" in input, _CONFIG_ERROR_TEXT + "asset limit needs to have either 'id' or 'name'");
    require(not ("id" in input and "name" in input), _CONFIG_ERROR_TEXT + "asset limit cannot have both 'id' and 'name'");
    return asset_limit(
        id = if ("id" in input) byte_array.from_gtv(input["id"]) else null,
        issuing_blockchain_rid = if ("name" in input)
            (if ("issuing_blockchain_rid" in input) byte_array.from_gtv(input["issuing_blockchain_rid"]) else chain_context.blockchain_rid)
            else null,
        name = if ("name" in input) text.from_gtv(input["name"]) else null,
        min_amount = parse_amount(input["min_amount"])
    );
}

function parse_amount(input: gtv): big_integer = if (utils.is_text(input))
    big_integer.from_text(text.from_gtv(input).replace("L", ""))
else
    big_integer.from_gtv(input);

val _CONFIG_ERROR_TEXT_TEMPLATE = "Error in moduleArgs (%s): %s";

struct fee_asset {
    id: byte_array? = null;
    issuing_blockchain_rid: byte_array? = null;
    name: text? = null;
    amount: big_integer;
}

function resolve_fee_assets(config: list<fee_asset>): map<byte_array, big_integer> {
    val fee_assets = map<byte_array, big_integer>();
    for (fee_asset in config) {
        val asset_id = fee_asset.id ?:
            assets.asset @? { .name == fee_asset.name!!, .issuing_blockchain_rid == fee_asset.issuing_blockchain_rid!! } (.id);
        if (asset_id != null) fee_assets[asset_id] = fee_asset.amount;
    }
    return fee_assets;
}

function parse_fee_assets(gtv, module_name: text): list<fee_asset> {
    if (utils.is_dict(gtv)) {
        val input = map<name, gtv>.from_gtv_pretty(gtv);
        return [parse_fee_asset(input, module_name)];
    } else if (utils.is_list(gtv)) {
        val inputs = list<map<name, gtv>>.from_gtv_pretty(gtv);
        return inputs @* {} (parse_fee_asset($, module_name));
    }
    else {
        require(
            false,
            _CONFIG_ERROR_TEXT_TEMPLATE.format(module_name, "asset only accepts a list of ids and amounts.")
        );
        return []; // will never happen
    }
}

function parse_fee_asset(input: map<name, gtv>, module_name: text): fee_asset {
    require("id" in input or "name" in input, _CONFIG_ERROR_TEXT_TEMPLATE.format(module_name, "fee asset needs to have either 'id' or 'name'"));
    require(not ("id" in input and "name" in input), _CONFIG_ERROR_TEXT_TEMPLATE.format(module_name, "fee asset cannot have both 'id' and 'name'"));
    return fee_asset(
        id = if ("id" in input) byte_array.from_gtv(input["id"]) else null,
        issuing_blockchain_rid = if ("name" in input)
            (if ("issuing_blockchain_rid" in input) byte_array.from_gtv(input["issuing_blockchain_rid"]) else chain_context.blockchain_rid)
            else null,
        name = if ("name" in input) text.from_gtv(input["name"]) else null,
        amount = parse_amount(input["amount"])
    );
}

@mount("ft4")
module;

import ^^^^.core.assets;
import ^^^^.core.accounts;
import ^^^^.core.crosschain;
import ^^^^.core.accounts.strategies;
import ^^^^.utils;

/**
 * Constant that represents account type used to temporarily store assets of transfers 
 * that have recipient_id that does not exist.
 */
val ACCOUNT_TYPE_POOL = "FT4_POOL";

/**
 * Constant that represent account type used to store fees charged during account registration.
 * Currently used both for `fee` and `subscription` strategies.
 */
val ACCOUNT_TYPE_FEE = "FT4_FEE";

struct module_args_list_element {
    sender_blockchain: gtv;
    sender: gtv;
    recipient: gtv;
    asset: gtv;
    timeout_days: integer;
    strategy: gtv;
}

struct module_args {
    rules: gtv; //list<module_args_list_element>
}

enum account_creation_state {
    pending,
    done,
    recalled
}

entity account_creation_transfer {
    index transaction, op_index: integer;
    sender_blockchain_rid: byte_array;
    sender_id: byte_array;
    index recipient_id: byte_array;
    assets.asset;
    amount: big_integer;
    rules: byte_array;
    timestamp;
    mutable state: account_creation_state = account_creation_state.pending;
    mutable final_tx_rid: byte_array = x"";
    mutable final_op_index: integer = -1;
}

@extend(assets.is_create_on_internal_transfer_enabled)
function() = true;

@extend(assets.create_on_internal_transfer)
function(sender: accounts.account, recipient_id: byte_array, assets.asset, amount: big_integer) {
    assets.Unsafe.transfer(sender, ensure_pool_account(chain_context.blockchain_rid), asset, amount);

    val sender_blockchain_rid = chain_context.blockchain_rid; // internal transfer
    pool_assets(sender_blockchain_rid, sender.id, recipient_id, asset, amount);
}

@extend(assets.recall_on_internal_transfer)
function(sender: accounts.account, transfer_tx_rid: byte_array, transfer_op_index: integer) {
    val sender_blockchain_rid = chain_context.blockchain_rid; // internal transfer
    val (asset, amount) = recall_transfer(sender_blockchain_rid, sender.id, transfer_tx_rid, transfer_op_index);

    assets.Unsafe.transfer(ensure_pool_account(chain_context.blockchain_rid), sender, asset, amount);
}

@extend(crosschain.is_create_on_crosschain_transfer_enabled)
function() = true;

@extend(crosschain.create_on_crosschain_transfer)
function(sender_blockchain_rid: byte_array, sender_id: byte_array, recipient_id: byte_array, assets.asset, amount: big_integer) {
    crosschain.Unsafe.update_balances_if_needed(
        crosschain.ensure_blockchain_account(sender_blockchain_rid),
        ensure_pool_account(chain_context.blockchain_rid),
        asset,
        amount
    );

    pool_assets(sender_blockchain_rid, sender_id, recipient_id, asset, amount);
}

@extend(crosschain.recall_on_crosschain_transfer)
function(sender_blockchain_rid: byte_array, sender_id: byte_array, transfer_tx_rid: byte_array, transfer_op_index: integer) {
    val (asset, amount) = recall_transfer(sender_blockchain_rid, sender_id, transfer_tx_rid, transfer_op_index);

    crosschain.Unsafe.update_balances_if_needed(
        ensure_pool_account(chain_context.blockchain_rid),
        crosschain.ensure_blockchain_account(sender_blockchain_rid),
        asset,
        amount
    );
}

function pool_assets(
        sender_blockchain_rid: byte_array,
        sender_id: byte_array,
        recipient_id: byte_array,
        assets.asset,
        amount: big_integer) {
    val rules = find_allowed_rules(
        from_chain = sender_blockchain_rid,
        from_id = sender_id,
        to_id = recipient_id,
        asset = asset,
        amount = amount
    );
    require(
        not rules.empty(),
        ("Recipient account <%s> does not exist, and no rule was found that allows account"+
        " creation with <%s> <%s> from account <%s> of chain <%s>")
            .format(
                recipient_id,
                assets.format_amount_with_decimals(amount, asset.decimals),
                asset.symbol,
                sender_id,
                sender_blockchain_rid
            )
    );

    require(empty(account_creation_transfer @* { recipient_id, asset, .state == account_creation_state.pending }),
        "This asset is already transferred");

    pool_assets_with_rules(sender_blockchain_rid, sender_id, recipient_id, asset, amount, rules);
}

function pool_assets_with_rules(
        sender_blockchain_rid: byte_array,
        sender_id: byte_array,
        recipient_id: byte_array,
        assets.asset,
        amount: big_integer,
        rules: map<text,rule>): account_creation_transfer {
    return create account_creation_transfer(
        op_context.transaction, op_index = op_context.op_index,
        sender_blockchain_rid, sender_id, recipient_id, asset, amount,
        rules = rules.to_gtv().to_bytes(),
        timestamp = utils.latest_time());
}

@extend(strategies.after_register_account)
function(accounts.account) {
    collect_pooled_assets(account, account.id);
}

function collect_pooled_assets(accounts.account, recipient_id: byte_array) {
    for (account_creation_transfer in
            account_creation_transfer @* { recipient_id, .state == account_creation_state.pending }) {
        val pool_account = ensure_pool_account(chain_context.blockchain_rid);

        assets.Unsafe.transfer(
            pool_account,
            account,
            account_creation_transfer.asset,
            account_creation_transfer.amount);

        account_creation_transfer.state = account_creation_state.done;
        account_creation_transfer.final_tx_rid = op_context.transaction.tx_rid;
        account_creation_transfer.final_op_index = op_context.op_index;
    }
}

function do_transfer(accounts.account, strategy: text) {
    val account_creation_transfers = account_creation_transfer @* { .recipient_id == account.id, .state == account_creation_state.pending };
    require(account_creation_transfers.size() > 0, "No pending transfer to account id <%s>".format(account.id));

    val pool_account = ensure_pool_account(chain_context.blockchain_rid);

    var enough_transferred = false;
    for (account_creation_transfer in account_creation_transfers) {
        assets.Unsafe.transfer(
            pool_account,
            account,
            account_creation_transfer.asset,
            account_creation_transfer.amount);

        account_creation_transfer.state = account_creation_state.done;
        account_creation_transfer.final_tx_rid = op_context.transaction.tx_rid;
        account_creation_transfer.final_op_index = op_context.op_index;

        val rules = map<text,rule>.from_gtv(gtv.from_bytes(account_creation_transfer.rules));
        val rule = rules.get_or_null(strategy);
        if (rule != null) {
            val resolved_assets = resolve_allowed_assets(rule);
            if (resolved_assets == null or (account_creation_transfer.asset.id in resolved_assets
                    and account_creation_transfer.amount >= resolved_assets[account_creation_transfer.asset.id])) {
                enough_transferred = true;
            }
        }
    }
    require(enough_transferred, "Insufficient amount of asset transferred");
}

function recall_transfer(
    sender_blockchain_rid: byte_array,
    sender_id: byte_array,
    transfer_tx_rid: byte_array,
    transfer_op_index: integer
) {
    val account_creation_transfers = account_creation_transfer @* {
        .transaction.tx_rid == transfer_tx_rid,
        .op_index == transfer_op_index,
        sender_blockchain_rid,
        sender_id,
        .state == account_creation_state.pending
    };

    require(account_creation_transfers.size() > 0, "No pending transfer found");
    require(account_creation_transfers.size() < 2,
        "%d pending transfers found, should not happen".format(account_creation_transfers.size()));
    val account_creation_transfer = account_creation_transfers[0];

    val rules = map<text,rule>.from_gtv(gtv.from_bytes(account_creation_transfer.rules));
    val timeout = (rules.values() @ {} (@min .timeout_days))!! * utils.MILLISECONDS_PER_DAY;
    val latest_time = utils.latest_time();
    val occurred_time = account_creation_transfer.timestamp;
    val delta = (latest_time - occurred_time);
    require(delta > timeout, "This transfer has not timed out yet");

    account_creation_transfer.state = account_creation_state.recalled;
    account_creation_transfer.final_tx_rid = op_context.transaction.tx_rid;
    account_creation_transfer.final_op_index = op_context.op_index;

    return (account_creation_transfer.asset, account_creation_transfer.amount);
}

function ensure_pool_account(blockchain_rid: byte_array): accounts.account {
    val pool_account_id = (ACCOUNT_TYPE_POOL + chain_context.blockchain_rid).hash();
    return accounts.ensure_account_without_auth(pool_account_id, ACCOUNT_TYPE_POOL);       
}

function ensure_fee_account(custom_account_id: byte_array?, blockchain_rid: byte_array): accounts.account {
    if (custom_account_id != null) {
        return accounts.Account(custom_account_id);
    } else {
        val fee_account_id = (ACCOUNT_TYPE_FEE + chain_context.blockchain_rid).hash();
        return accounts.ensure_account_without_auth(fee_account_id, ACCOUNT_TYPE_FEE);
    }
}

/**
 *
 * @return `null` if all assets are allowed
 */
query get_allowed_assets(sender_blockchain_rid: byte_array, sender_id: byte_array, recipient_id: byte_array):
        list<(asset_id: byte_array, min_amount: big_integer)>? {
    val rule = find_allowed_assets(sender_blockchain_rid, sender_id, recipient_id);
    if (rule == null) return null;
    val allowed_assets = list<(asset_id: byte_array, min_amount: big_integer)>();
    for ((asset_id, min_amount) in rule) {
        allowed_assets.add((asset_id = asset_id, min_amount = min_amount));
    }
    return allowed_assets;
}

query get_pending_transfer_strategies(recipient_id: byte_array): set<text> {
    val strategies2 = account_creation_transfer @* { recipient_id, .state == account_creation_state.pending }
        (map<text,rule>.from_gtv(gtv.from_bytes(.rules)).keys());
    val strategies = set<text>();
    for (s in strategies2) {
        strategies.add_all(s);
    }
    return strategies;
}

query has_pending_create_account_transfer_for_strategy(
    strategy_name: text,  
    sender_blockchain_rid: byte_array,
    sender_id: byte_array,
    recipient_id: byte_array,
    asset_id: byte_array,
    amount: big_integer
) {
    val transfers = account_creation_transfer @* {
        .recipient_id == recipient_id,
        .sender_blockchain_rid == sender_blockchain_rid,
        .sender_id == sender_id,
        .asset.id == asset_id,
        .amount == amount,
        .state == account_creation_state.pending
    };

    for (transfer in transfers) {
        val rules = map<text, rule>.from_gtv(gtv.from_bytes(transfer.rules));

        if (not (strategy_name in rules)) continue;
        val rule = rules[strategy_name];

        if (
            is_blockchain_allowed(rule, sender_blockchain_rid) and
            is_sender_allowed(rule, sender_id) and
            is_recipient_allowed(rule, sender_id, recipient_id) and
            is_asset_amount_allowed(rule, transfer.asset, amount)
        ) {
            return true;
        }
    }

    return false;
}

val ASSET_TYPE_FT4 = "ft4";

entity asset {
    key id: byte_array;
    name;
    key symbol: text;
    decimals: integer;
    issuing_blockchain_rid: byte_array;
    icon_url: text;
    type: text = ASSET_TYPE_FT4;
    mutable total_supply: big_integer;
}

function Asset(id: byte_array) = require(
    asset @? { id },
    "Asset <%s> not found".format(id)
);

entity balance {
    key accounts.account, asset;
    mutable amount: big_integer;
}

val max_asset_amount = big_integer.from_hex("ff".repeat(32));

function increase_balance(accounts.account, asset, amount: big_integer): big_integer {
    val balance = balance @? { account, asset };
    if (balance != null) {
        val new_amount = balance.amount + amount;
        balance.amount = new_amount;
        return new_amount;
    } else {
        create balance(account, asset, amount);
        return amount;
    }
}

function deduct_balance(accounts.account, asset, amount: big_integer): big_integer {
    val balance = balance @? { account, asset };
    require(balance, "User does not have asset <%s> in account <%s>".format(asset.id, account.id));
    require(balance.amount >= amount, "Balance is too low");

   if (balance.amount - amount == 0L) {
       delete balance;
       return 0L;
   } else {
       val new_amount = balance.amount - amount;
       balance.amount = new_amount;
       return new_amount;
   }
}

function get_asset_balance(accounts.account, asset): big_integer {
    val balance = balance @? {asset, account};
    return if (balance != null) balance.amount else 0L;
}

function map_asset(asset: asset) {
    return (
        id = asset.id,
        name = asset.name,
        symbol = asset.symbol,
        decimals = asset.decimals,
        blockchain_rid = asset.issuing_blockchain_rid,
        icon_url = asset.icon_url,
        type = asset.type,
        supply = asset.total_supply
    );
}

function get_paginated_asset_balances(account_id: byte_array, page_size: integer?, page_cursor: text?): list<utils.pagination_result> {
    val before_rowid = utils.before_rowid(page_cursor);
    return balance @* {
        .account.id == account_id,
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data = (
                asset = map_asset(.asset),
                amount = .amount
            ).to_gtv_pretty(),
            rowid = .rowid
        )
    ) limit utils.fetch_data_size(page_size);
}

function get_assets_by_type(type: text, page_size: integer?, page_cursor: text?) {
    val before_rowid = utils.before_rowid(page_cursor);
    return asset @* {
        type,
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data = (map_asset($)).to_gtv_pretty(),
            rowid = .rowid
        )
    ) limit utils.fetch_data_size(page_size);
}

function get_all_assets(page_size: integer?, page_cursor: text?) {
    val before_rowid = utils.before_rowid(page_cursor);
    return asset @* {
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data = (map_asset($)).to_gtv_pretty(),
            rowid = .rowid
        )
    ) limit utils.fetch_data_size(page_size);
}

function get_asset_balances(account_id: byte_array) {
    return balance @* { .account.id == account_id } (
        asset = map_asset(.asset),
        amount = .amount
    );
}

function format_amount_with_decimals(amount: big_integer, decimals: integer): text {
    require(decimals >= 0, "Decimals must be non-negative. Received: %s".format(decimals));
    var amt = amount.to_text();
    if (decimals == 0) {
        return amt;
    } else if (amt.size() > decimals) {
        amt = amt.sub(0, amt.size() - decimals) + "." + amt.sub(amt.size() - decimals);
    } else {
        amt = "0." + "0".repeat(decimals - amt.size()) + amt;
    }
    return amt;
}

function get_paginated_asset_balances_by_name(name, page_size: integer?, page_cursor: text?) {
    val before_rowid = utils.before_rowid(page_cursor);
    return asset @* {
        .name == name,
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data = (map_asset($)).to_gtv_pretty(),
            rowid = .rowid
        )
    ) limit utils.fetch_data_size(page_size);
}

function require_zero_exclusive_asset_amount_limits(value: big_integer, name) {
    require(
        value <= max_asset_amount, 
        "%s: value must be lower than 2^256, actual: %d".format(name, value)
    );
    require(
        value > 0L, 
         "%s: value must be non-zero positive, actual: %d".format(name, value)
    );
}

namespace Unsafe {
    function mint(accounts.account, asset, amount: big_integer) {
        require_zero_exclusive_asset_amount_limits(amount, "Parameter amount");
        require(
            asset.issuing_blockchain_rid == chain_context.blockchain_rid,
            "Assets can only be minted on issuing chain"
        );
        before_mint(account, asset, amount);
        increase_balance(account, asset, amount);

        asset.total_supply += amount;

        require(asset.total_supply <= max_asset_amount, "End total supply must be lower than 2^256");

        create transfer_history_entry(
            account,
            asset,
            .delta = amount,
            .op_index = op_context.op_index,
            .is_input = false
        );

        after_mint(account, asset, amount);
    }

    function burn(accounts.account, asset, amount: big_integer) {
        require_zero_exclusive_asset_amount_limits(amount, "Parameter amount");
        require(
            asset.issuing_blockchain_rid == chain_context.blockchain_rid,
            "Assets can only be burned on issuing chain"
        );
        require(get_asset_balance(account, asset) >= amount, "Insufficient balance");

        before_burn(account, asset, amount);

        deduct_balance(account, asset, amount);

        asset.total_supply -= amount;

        create transfer_history_entry (
            account,
            asset,
            .delta = amount,
            .op_index = op_context.op_index,
            .is_input = true
        );
        after_burn(account, asset, amount);
    }

    function register_asset(
        name,
        symbol: text,
        decimals: integer,
        blockchain_rid: byte_array,
        icon_url: text,
        type: text = ASSET_TYPE_FT4): asset {

        require(decimals >= 0 and decimals < 79, "Decimals must be between 0 and 78 (included)");

        val trimmed_icon_url = icon_url.trim();
        require(
            (trimmed_icon_url == "") or (trimmed_icon_url.size() <= 2048 and trimmed_icon_url.matches('^\\S+:\\/\\/[^\\s$.?#].[^\\s]*$')),
            "Invalid URL for icon"
        );

        require(blockchain_rid.size() > 0, "blockchain_rid cannot be empty");

        val id = (name, blockchain_rid).hash();
        return create asset (
            id,
            name,
            symbol,
            decimals,
            issuing_blockchain_rid=blockchain_rid,
            icon_url=trimmed_icon_url,
            type=type,
            total_supply=0L
        );
    }
}

@extendable function before_transfer(from: accounts.account, to: accounts.account, asset, amount: big_integer);

@extendable function after_transfer(from: accounts.account, to: accounts.account, asset, amount: big_integer);

@extendable function before_mint(accounts.account, asset, amount: big_integer);

@extendable function after_mint(accounts.account, asset, amount: big_integer);

@extendable function before_burn(accounts.account, asset, amount: big_integer);

@extendable function after_burn(accounts.account, asset, amount: big_integer);

@log entity transfer_history_entry {
    op_index: integer = op_context.op_index; // helps to locate exact position of transfer entry in transaction
    index transaction, op_index;

    index accounts.account;
    index asset;
    delta: big_integer;
    is_input: boolean;
}

@log entity crosschain_transfer_history_entry {
    op_index: integer = op_context.op_index; // helps to locate exact position of transfer entry in transaction
    index transaction, op_index;

    blockchain_rid: byte_array;
    index account_id: byte_array;
    index asset;
    delta: big_integer;
    is_input: boolean;
}

enum transfer_type {
    sent,
    received,
}

struct filter {
    transfer_type?;
}

function extract_data_from_transfer_history_list(
        entries: list<transfer_history_entry>
    ): list<(data:gtv,rowid:rowid)> {
    return entries @* {} (
        data = extract_data_from_transfer_history_entry($).to_gtv_pretty(),
        rowid = .rowid
    );
}

function extract_operation_name(entry: transfer_history_entry): text {
    val gtx = gtx_transaction.from_gtv(gtv.from_bytes(entry.transaction.tx_data));
    return gtx.body.operations[entry.op_index].name;
}

function extract_data_from_transfer_history_entry(entry: transfer_history_entry) {
    return (
        id = entry.rowid,
        delta = entry.delta,
        decimals = entry.asset.decimals,
        asset = map_asset(entry.asset),
        is_input = entry.is_input,
        timestamp = entry.transaction.block.timestamp,
        block_height = entry.transaction.block.block_height,
        tx_rid = entry.transaction.tx_rid,
        tx_data = entry.transaction.tx_data,
        operation_name = extract_operation_name(entry),
        op_index = entry.op_index,
        is_crosschain = exists(
            crosschain_transfer_history_entry @* { .transaction == entry.transaction, .op_index == entry.op_index, .asset == entry.asset }
        )
    );
}

function get_paginated_transfers(accounts.account?, asset?, filter, height: integer?, page_size: integer?, page_cursor: text?) {
    var before_rowid: rowid? = null;
    if (page_cursor??) {
        val cursor = utils.decode_cursor(page_cursor);
        before_rowid = cursor.before_rowid;
    }

    val entries = transfer_history_entry @* {
        if (account == null) true else .account == account,
        if (asset == null) true else .asset == asset,
        if (filter.transfer_type == null) true else .is_input == (filter.transfer_type!! == transfer_type.sent),
        if (height == null) true else (.transaction.block.block_height > height),
        if (before_rowid??) (.rowid < before_rowid) else true
    } (@sort_desc $) limit utils.fetch_data_size(page_size);

    return extract_data_from_transfer_history_list(entries) @* {} (
        utils.pagination_result(
            data = .data,
            rowid = .rowid
        )
    );
}

struct transfer_detail {
    blockchain_rid: byte_array;
    account_id: byte_array;
    asset_id: byte_array;
    delta: big_integer;
    is_input: boolean;
}

function get_transfer_details(tx_rid: byte_array, op_index: integer): set<transfer_detail> {
    val result = set(transfer_history_entry @*
        { .transaction.tx_rid == tx_rid, op_index,
            .account.type != crosschain.ACCOUNT_TYPE_BLOCKCHAIN }
        (extract_details_from_transfer_history_entry($)));

    result.add_all(crosschain_transfer_history_entry @*
        { .transaction.tx_rid == tx_rid, op_index }
        (extract_details_from_crosschain_transfer_history_entry($))
    );

    return result;
}

function get_transfer_details_by_asset(tx_rid: byte_array, op_index: integer, asset_id: byte_array): set<transfer_detail> {
    val result = set(transfer_history_entry @*
        { .transaction.tx_rid == tx_rid, op_index, .asset.id == asset_id,
            .account.type != crosschain.ACCOUNT_TYPE_BLOCKCHAIN }
        (extract_details_from_transfer_history_entry($)));

    result.add_all(crosschain_transfer_history_entry @*
        { .transaction.tx_rid == tx_rid, op_index, .asset.id == asset_id }
        (extract_details_from_crosschain_transfer_history_entry($))
    );

    return result;
}

function extract_details_from_transfer_history_entry(entry: transfer_history_entry) =
    transfer_detail(
        blockchain_rid = chain_context.blockchain_rid,
        account_id = entry.account.id,
        asset_id = entry.asset.id,
        delta = entry.delta,
        is_input = entry.is_input
    );

function extract_details_from_crosschain_transfer_history_entry(entry: crosschain_transfer_history_entry) =
    transfer_detail(
        blockchain_rid = entry.blockchain_rid,
        account_id = entry.account_id,
        asset_id = entry.asset.id,
        delta = entry.delta,
        is_input = entry.is_input
    );

@mount('ft4')
module;

import ^^.core.accounts;
import ^^.core.crosschain;
import ^^.utils;
import ^^.version;

@extendable
function is_create_on_internal_transfer_enabled(): boolean = false;

@extendable
function create_on_internal_transfer(
   sender: accounts.account,
   recipient_id: byte_array,
   asset,
   amount: big_integer
);

@extendable
function recall_on_internal_transfer(
   sender: accounts.account,
   transfer_tx_rid: byte_array,
   transfer_op_index: integer
);

namespace Unsafe {

   function transfer_to_recipient_id(sender: accounts.account, recipient_id: byte_array, asset, amount: big_integer) {
      val recipient = accounts.account @? { .id == recipient_id };
      if (recipient != null) {
          transfer(sender, recipient, asset, amount);
      } else {
          require(is_create_on_internal_transfer_enabled(),
              "Account <%s> does not exist and creating accounts on transfer is not enabled".format(recipient_id));
          create_on_internal_transfer(sender, recipient_id, asset, amount);
      }
   }

   function transfer(from: accounts.account, to: accounts.account, asset, amount: big_integer) {
      require_zero_exclusive_asset_amount_limits(amount, "Parameter amount");
      require(from != to, "Sender and receiver have to be different");

      before_transfer(from, to, asset, amount);

      deduct_balance(from, asset, amount);
      create transfer_history_entry(
         .account = from,
         .asset = asset,
         .delta = amount,
         .op_index = op_context.op_index,
         .is_input = true
      );

      increase_balance(to, asset, amount);
      create transfer_history_entry(
         .account = to,
         .asset = asset,
         .delta = amount,
         .op_index = op_context.op_index,
         .is_input = false
      );

      after_transfer(from, to, asset, amount);
   }

   function recall_unclaimed_transfer(accounts.account, transfer_tx_rid: byte_array, transfer_op_index: integer) {
      require(is_create_on_internal_transfer_enabled(), "Creating accounts on transfer is not enabled");
      recall_on_internal_transfer(account, transfer_tx_rid, transfer_op_index);
   }
}

/**
 * This function can be extended by users to add custom logic before authentication.
 */
@extendable
function before_authenticate(accounts.account, accounts.account_auth_descriptor);

/**
 * This function can be extended by users to add custom logic after authentication.
 */
@extendable
function after_authenticate(accounts.account, accounts.account_auth_descriptor?);

val EVM_AUTH_OP = "ft4.evm_auth";
val FT_AUTH_OP = "ft4.ft_auth";

val EVM_ADDRESS_SIZE = 20;
val FT_PUBKEY_SIZE = 33;

val BLOCKCHAIN_RID_PLACEHOLDER = "{blockchain_rid}";
val ACCOUNT_ID_PLACEHOLDER = "{account_id}";
val AUTH_DESCRIPTOR_ID_PLACEHOLDER = "{auth_descriptor_id}";
val NONCE_PLACEHOLDER = "{nonce}";

function authenticate() {
    val op = op_context.get_current_operation();
    require(op_context.op_index > 0, "Expected at least two operations, make sure that you included auth operation.");

    val previous_op = op_context.get_all_operations()[op_context.op_index - 1];
    require(
        is_auth_op(previous_op),
        "Error authorizing operation. Incorrect auth operation %s".format(previous_op.name)
    );

    val (account, auth_descriptor) = fetch_account_and_auth_descriptor(previous_op.args);
    require(
        get_first_allowed_auth_descriptor(op.name, op.args.to_gtv(), account.id, [auth_descriptor.id]),
        "The provided auth descriptor is not valid for this operation"
    );
    before_authenticate(account, auth_descriptor);

    accounts.rate_limit(account);

    require(not accounts.have_violating_rules(auth_descriptor), "The rules for this auth descriptor have been violated");

    val flags = get_auth_flags(op.name);

    when (previous_op.name) {
        EVM_AUTH_OP -> _validate_evm_signature(op, previous_op, flags, account, auth_descriptor);
        FT_AUTH_OP -> _validate_ft4_signature(flags, account, auth_descriptor);
        else -> require(false, "Invalid auth operation: %s".format(previous_op.name));
    };

    val auth_desc_after = accounts.update_auth_descriptor_rule_variables(auth_descriptor);
    val deleted_descriptors = accounts.delete_expired_auth_descriptors(account);

    after_authenticate(account, if (auth_desc_after in deleted_descriptors) null else auth_desc_after);

    return account;
}

function get_first_allowed_auth_descriptor_by_signers(op_name: name, args: gtv, account_id: byte_array, signers: list<byte_array>) {
    val ads = accounts.auth_descriptor_signer @* {
        .account_auth_descriptor.account.id == account_id,
        .id in signers
    } (.account_auth_descriptor);

    val flags = get_auth_flags(op_name);

    val valid_ad_ids = ads @* { accounts.has_flags($, flags) } (.id);

    return get_first_allowed_auth_descriptor(op_name, args, account_id, valid_ad_ids);
}

function get_first_allowed_auth_descriptor(op_name: name, args: gtv, account_id: byte_array, ad_ids: list<byte_array>) {
    if (ad_ids.size() == 0) return null;

    val resolver = get_auth_handler(op_name).resolver;
    if (resolver == null) return ad_ids[0];

    return resolver(args, account_id, ad_ids);
}

function _ft_auth(required_flags: list<text>, account: accounts.account, auth_descriptor: accounts.account_auth_descriptor) {
    accounts.rate_limit(account);

    require(not accounts.have_violating_rules(auth_descriptor), "The rules for this auth descriptor have been violated");

    _validate_ft4_signature(required_flags, account, auth_descriptor);

    accounts.update_auth_descriptor_rule_variables(auth_descriptor);
    accounts.delete_expired_auth_descriptors(account);
}

function fetch_account_and_auth_descriptor(auth_args: list<gtv>): (accounts.account, accounts.account_auth_descriptor) {
    val (account_id, auth_descriptor_id) = extract_account_and_auth_descriptor(auth_args);
    val account = accounts.Account(account_id);
    val auth_descriptor = require(
        try_fetch_auth_descriptor(account, auth_descriptor_id),
        "Auth descriptor '%s' not found for account '%s'".format(auth_descriptor_id, account_id)
    );
    return (account, auth_descriptor);
}

function extract_account_and_auth_descriptor(auth_args: list<gtv>): (byte_array, byte_array) {
    val account_id = byte_array.from_gtv(auth_args[0]);
    val auth_descriptor_id = byte_array.from_gtv(auth_args[1]);
    return (account_id, auth_descriptor_id);
}

function try_fetch_auth_descriptor(accounts.account, auth_descriptor_id: byte_array): accounts.account_auth_descriptor? =
    accounts.account_auth_descriptor @? { .id == auth_descriptor_id, .account == account };

function get_auth_flags(op_name: name) = get_auth_handler(op_name).flags;

function get_auth_message_template(op_name: name, op_args: gtv) {
    val formatter = get_auth_handler(op_name).message_formatter;

    val message = if (formatter??) formatter(op_args) else generate_operation_auth_message(chain_context.blockchain_rid, gtx_operation(
        name = op_name,
        args = list<gtv>.from_gtv(op_args)
    ));

    return utils.make_auth_message(message);
}

function _validate_evm_signature(
  op: gtx_operation,
  auth_op: gtx_operation,
  flags: list<text>,
  account: accounts.account,
  auth_descriptor: accounts.account_auth_descriptor
) {
    val message_template = get_auth_message_template(op.name, op.args.to_gtv());
    val validated_args = _validate_evm_arguments(auth_op.args, set(flags), account, auth_descriptor);
    val message = create_message_from_template(
        validated_args, 
        message_template, 
        op.args, 
        utils.derive_nonce(op, auth_descriptor.ctr)
    );

    if (auth_descriptor.auth_type == accounts.auth_type.S)
        _validate_evm_address(message, validated_args.signatures[0], auth_descriptor);
    else
        _validate_multiple_evm_addresses(message, validated_args.signatures, auth_descriptor);
}

function create_message_from_template(evm_auth_args, message_template: text, args: list<gtv>, nonce: text): text {
    require(message_template.contains(NONCE_PLACEHOLDER), "Message template has to include '%s'".format(NONCE_PLACEHOLDER));
    require(message_template.contains(BLOCKCHAIN_RID_PLACEHOLDER), "Message template has to include '%s'".format(BLOCKCHAIN_RID_PLACEHOLDER));
    var message = message_template;

    return message
        .replace(ACCOUNT_ID_PLACEHOLDER, evm_auth_args.account.id.to_hex().upper_case())
        .replace(AUTH_DESCRIPTOR_ID_PLACEHOLDER, evm_auth_args.account_auth_descriptor.id.to_hex().upper_case())
        .replace(NONCE_PLACEHOLDER, nonce)
        .replace(BLOCKCHAIN_RID_PLACEHOLDER, chain_context.blockchain_rid.to_hex().upper_case());
}

function _validate_evm_arguments(
  auth_args: list<gtv>,
  required_flags: set<text>,
  account: accounts.account, 
  auth_descriptor: accounts.account_auth_descriptor
): evm_auth_args {
    require(auth_args.size() == 3, "Incorrect number of arguments to auth operation");

    val signatures = list<signature?>.from_gtv(auth_args[2]);

    val has_all_flags = accounts.has_flags(auth_descriptor, list(required_flags));

    require(has_all_flags, "The auth descriptor does not have the required permissions");

    return evm_auth_args(account, auth_descriptor, signatures);
}

function _validate_ft4_signature(
  flags: list<text>,
  account: accounts.account,
  auth_descriptor: accounts.account_auth_descriptor
) {
   	val result: utils.validation_result = accounts.check_auth_args(
        auth_descriptor.auth_type,
        auth_descriptor.args,
        accounts.get_signers_from_encoded_auth_descriptor(auth_descriptor.auth_type, auth_descriptor.args),
        flags
   	);

    require(result.valid, result.error!!); // Prints a precise error message.
}

function _recover_evm_address(message: text, signature) {
    require(message != "", "Empty messages are not allowed");

    val msg_hash = _evm_message_hash(message);
    val evm_pubkey = crypto.eth_ecrecover(
        signature.r,
        signature.s,
        signature.v - 27,
        msg_hash
    );

    return crypto.eth_pubkey_to_address(evm_pubkey);
}

function _evm_message_hash(message: text): byte_array =
    keccak256(("\u0019Ethereum Signed Message:\n" + message.size().to_text() + message).to_bytes());

function _validate_evm_address(message: text, signature?, accounts.account_auth_descriptor) {
    require(signature, "Signature cannot be null when using single sig");
    val recovered_address = _recover_evm_address(message, signature);
    val signer = accounts.auth_descriptor_signer @? {
        .account_auth_descriptor == account_auth_descriptor,
        .id == recovered_address
    };
    require(signer, "Invalid signature on message: \n%s".format(message));

    return recovered_address;
}

function _validate_multiple_evm_addresses(message: text, signatures: list<signature?>, accounts.account_auth_descriptor) {
    val recovered_keys = list<byte_array>();
    val ad_args = accounts.multi_sig_args.from_bytes(account_auth_descriptor.args);
    for (i in range(signatures.size())) {
        if (signatures[i] == null) continue;

        val recovered_address = _validate_evm_address(
            message,
            signatures[i],
            account_auth_descriptor
        );
        require(
            recovered_address == ad_args.signers[i],
            "Expected signer at index <%d> to be <%s> but was: <%s>"
                .format(i, ad_args.signers[i], recovered_address)
        );
        recovered_keys.add(recovered_address);
    }
    require(
        recovered_keys.size() >= ad_args.signatures_required, 
        "Minimum number of valid signatures not reached. Expected <%d>, found <%d>."
            .format(ad_args.signatures_required, recovered_keys.size())
    );
    return recovered_keys;
}

/**
  * Verifies whether provided list of signers have signed the operation/transaction.
  * FT (GTX) signers are checked against GTX `signers` and `signatures` fields, while 
  * EVM signers are checked against signers and signatures provided in `ft4.evm_signatures` operation.
  */
function verify_signers(ft_and_evm_signers: list<byte_array>) {
    val op = op_context.get_current_operation();
    val message_template = get_auth_message_template(op.name, op.args.to_gtv());

    var message = message_template
        .replace(BLOCKCHAIN_RID_PLACEHOLDER, chain_context.blockchain_rid.to_hex().upper_case())
        .replace(NONCE_PLACEHOLDER, utils.derive_nonce(op, 0));

    if (message_template.contains(ACCOUNT_ID_PLACEHOLDER) or message_template.contains(AUTH_DESCRIPTOR_ID_PLACEHOLDER)) {
        val auth_details = require(
            get_auth_details_from_auth_operation(),
            "Cannot extract auth details. Auth operation not found"
        );

        message = message
            .replace(ACCOUNT_ID_PLACEHOLDER, auth_details.account_id.to_hex().upper_case())
            .replace(AUTH_DESCRIPTOR_ID_PLACEHOLDER, auth_details.auth_descriptor_id.to_hex().upper_case());
    }

    verify_signers_with_message(ft_and_evm_signers, message);
}

function verify_signers_with_message(ft_and_evm_signers: list<byte_array>, message: text) {
    val (signers, signatures) = get_evm_signatures();
    for (i in range(signatures.size())) {
        val signer = signers[i];
        require(
            signer == _recover_evm_address(message, signatures[i]),
            "Invalid signature for address <%s>".format(signer)
        );
    }

    val evm_signers = set(signers);

    for (signer in ft_and_evm_signers) {
        if (signer.size() == EVM_ADDRESS_SIZE) require(signer in evm_signers, "Missing signature for address <%s>".format(signer));
        else if (signer.size() == FT_PUBKEY_SIZE) require(op_context.is_signer(signer), "Missing signature for public key <%s>".format(signer));
        else require(false, "Unsupported signer <%s>".format(signer));
    }
}

function get_evm_signatures(): (signers: list<byte_array>, signatures: list<signature>) {
    if (op_context.op_index == 0) return (signers = list<byte_array>(), signatures = list<signature>());

    val tx_operations = op_context.get_all_operations();
    val prev_op = tx_operations[op_context.op_index-1];
    var evm_signatures_op: gtx_operation? = null;

    if (is_evm_signatures_op(prev_op)) {
        evm_signatures_op = prev_op;
    } else if (
        op_context.op_index > 1 and
        (is_auth_op(prev_op) or strategies.is_strategy_op(prev_op)) and 
        is_evm_signatures_op(tx_operations[op_context.op_index-2])
    ) {
        evm_signatures_op = tx_operations[op_context.op_index-2];
    }

    if (empty(evm_signatures_op)) return (signers = list<byte_array>(), signatures = list<signature>());

    val args = struct<evm_signatures>.from_gtv(evm_signatures_op.args.to_gtv());

    require(
        args.signers.size() == args.signatures.size(),
        "Number of evm signers <%d> is not equal to number of evm signatures <%d>".format(args.signers.size(), args.signatures.size())
    );

    var signatures = list<signature>();
    for (i in range(args.signatures.size())) {
        val signature = require(
            args.signatures[i],
            "Missing signature for address <%s>.".format(args.signers[i])
        );
        signatures.add(signature);
    }

    return (
        signers = args.signers,
        signatures = signatures
    );
}

function extract_account_id(auth_op: gtx_operation): byte_array {
    require(is_auth_op(auth_op), "Operation %s is not an auth operation".format(auth_op.name));
    require(auth_op.args.size() >= 1, "Invalid auth op, insufficient number of args: %s".format(auth_op.args.size()));
    return byte_array.from_gtv(auth_op.args[0]);
}

function is_auth_op(op: gtx_operation) = op.name in [EVM_AUTH_OP, FT_AUTH_OP];

function is_evm_signatures_op(op: gtx_operation) = op.name == "ft4.evm_signatures";

function get_auth_details_from_auth_operation() {
    if (op_context.op_index == 0) return null;
    val op = op_context.get_all_operations()[op_context.op_index-1];
    if (not is_auth_op(op)) return null;

    return (
        account_id = byte_array.from_gtv(op.args[0]),
        auth_descriptor_id = byte_array.from_gtv(op.args[1])
    );
}

val DEFAULT_LOGIN_CONFIG_NAME = "default";

struct _login_config {
    flags: list<text>;
    rules: gtv? = null;
}

@extendable
function login_config(): map<name, _login_config>;

function add_login_config(
    name = DEFAULT_LOGIN_CONFIG_NAME,
    flags: list<text>,
    rules: gtv? = null
) {
    return [name: _login_config(flags, rules)];
}

function map_rule(rule: rule_expression): gtv {
    return [
        rule.operator.name.to_gtv(),
        rule.variable.name.to_gtv(),
        rule.value.to_gtv()
    ].to_gtv();
}

function login_simple_rule(rule: rule_expression) = map_rule(rule);

function login_rules(rules_list: list<rule_expression>): gtv {
    require(rules_list.size() > 0, "Empty login rules list");

    if (rules_list.size() == 1) return map_rule(rules_list[0]);

    val rules = ["and".to_gtv()];
    for (rule in rules_list) {
        rules.add(map_rule(rule));
    }
    return rules.to_gtv();
}

function ttl(millis: integer): gtv {
    return map_rule(
        rule_expression(
            rule_operator.lt,
            rule_variable.relative_block_time,
            millis
        )
    );
}

enum rule_variable {
    block_height,
    block_time,
    op_count,
    relative_block_height,
    relative_block_time
}

enum rule_operator {
    lt,
    le,
    eq,
    ge,
    gt
}

struct rule_expression {
	operator: rule_operator;
	variable: rule_variable;
	value: integer;
}

struct rule_parameters {
	variable: rule_variable;
	value: integer;
}

/*
 * Operator functions
 */

function greater_than(rule_parameters) = rule_expression(
    rule_parameters.variable,
    rule_operator.gt,
    rule_parameters.value
);

function greater_or_equal(rule_parameters) = rule_expression(
    rule_parameters.variable,
    rule_operator.ge,
    rule_parameters.value
);

function equals(rule_parameters): rule_expression {
    return rule_expression(
        rule_parameters.variable,
        rule_operator.eq,
        rule_parameters.value
    );
}

function less_than(rule_parameters) = rule_expression(
    rule_parameters.variable,
    rule_operator.lt,
    rule_parameters.value
);

function less_or_equal(rule_parameters) = rule_expression(
    rule_parameters.variable,
    rule_operator.le,
    rule_parameters.value
);

/*
 * Rule variable functions
 */

function block_height(integer) = rule_parameters(
    rule_variable.block_height,
    integer
);

function block_time(integer) = rule_parameters(
    rule_variable.block_time,
    integer
);

function op_count(integer) = rule_parameters(
    rule_variable.op_count,
    integer
);

function relative_block_height(integer) = rule_parameters(
    rule_variable.relative_block_height,
    integer
);

function relative_block_time(integer) = rule_parameters(
    rule_variable.relative_block_time,
    integer
);

@mount('ft4')
module;

import ^^.core.accounts;
import ^^.core.accounts.strategies;
import ^^.utils;
import ^^.version;

import ^^.external.auth.{
    evm_signatures
};

struct module_args {
    evm_signatures_authorized_operations: gtv? = null;
}

struct auth_data {
    flags: list<text>;
    message: text;
}

struct _auth_handler {
    flags: list<text>;
    message_formatter: ((gtv) -> text)? = null;
    resolver: ((gtv, byte_array, list<byte_array>) -> byte_array?)? = null;
}

/*
 * The constant that defines app level authentication scope.
 * If scope is omitted when defining an auth handler, then
 * it has 'app' scope, i.e. it is used to authenticate 
 * operations that do not have own auth handlers or if 
 * there is no mount point auth handler for the operation.
 */
val APP_SCOPE = "app";

/*
 * Extendable function used to define auth handlers. 
 * When called it returns a list of all auth handlers defined
 * in the dapp.
 */
@extendable 
function auth_handler(): map<name, _auth_handler>;

/*
 * Finds auth handler for provided operation name.
 */
function get_auth_handler(op_name: name) {
    require_valid_scope_name(op_name);
    val auth_handlers = auth_handler();
    if (op_name in auth_handlers) return auth_handlers[op_name];
    val override_name = "__override__" + op_name;
    if (override_name in auth_handlers) return auth_handlers[override_name];

    val handler = get_mount_scope_auth_handler(auth_handlers, op_name);
    if (handler??) return handler;

    require(
        auth_handlers.get_or_null(APP_SCOPE),
        "Cannot find auth handler for operation <%s>".format(op_name)
    );
    return auth_handlers[APP_SCOPE];
}

function add_auth_handler(
    scope: text = APP_SCOPE, 
    flags: list<text>,
    message: ((gtv) -> text)? = null,
    resolver: ((gtv, byte_array, list<byte_array>) -> byte_array?)? = null
) = [valid_scope_name(scope): _auth_handler(flags, message, resolver)];

function add_overridable_auth_handler(
    scope: text = APP_SCOPE,
    flags: list<text>,
    message: ((gtv) -> text)? = null,
    resolver: ((gtv, byte_array, list<byte_array>) -> byte_array?)? = null
) = ["__override__" + valid_scope_name(scope): _auth_handler(flags, message, resolver)];

function valid_scope_name(scope: text) {
    val scope_name = scope.trim();
    require_valid_scope_name(scope_name);
    return scope_name;
}

function args() = op_context.get_current_operation().args.to_gtv();

struct signature {
    r: byte_array;
    s: byte_array;
    v: integer;
}

struct evm_auth_args {
    accounts.account;
    accounts.account_auth_descriptor;
    signatures: list<signature?>;
}

function get_mount_scope_auth_handler(auth_handlers: map<name, _auth_handler>, op_name: name) {
    val op_name_components = op_name.split(".");
    if (op_name_components.size() < 2) return null;

    for (count in range(op_name_components.size()-1, 0, -1)) {
        val mount_point = join_text_list(op_name_components, count);
        if (mount_point in auth_handlers) return auth_handlers[mount_point];
    }

    return null;
}

/*
 * Creates message from operation name and arguments.
 * It is used when `evm_auth` is used to authenticate a user, 
 * but auth message is not specified in the auth handler of the operation.
 */
function generate_operation_auth_message(blockchain_rid: byte_array, op: gtx_operation) {
    var message = "Please sign the message to call\noperation:\n- %s".format(op.name);

    if (op.args.size() > 0) {
        message = message + "\n\n";
        var arguments = "with arguments:\n";
        for (arg in op.args) {
            arguments = arguments + "- %s\n".format(arg).replace("\"", "");
        }
        message = message + arguments.sub(0, arguments.size() - 1);
    }

    return message;
}

function join_text_list(components: list<text>, count: integer) {
    require(count < components.size() and count > 0, "Error building mount path");
    var result = components[0];
    for (i in range(1, count)) {
        result = result + "." + components[i];
    }
    return result;
}

function require_valid_scope_name(name) =     
    require(
        name.matches("^\\w+(\\.\\w+)*$"), 
        "Invalid scope name <%s>".format(name)
    );

/*
 * Checks whether `evm_signatures` operation can be used with provided operation.
 * We don't keep track of nonce for keys used with evm_signatures, therefore if not used with care,
 * authorizing an operation with `evm_signatures` could lead to replay attack. In order to use it with
 * an operation, the operation has to be whitelisted. By default, library only allows 
 * `evm_signatures` to be used with `ft4.add_auth_descriptor` and `ft4.register_account`.
 * `evm_signatures` is safe to use in combination with `ft_auth` or `evm_auth` operation.
 * However if used as only way to authorize an operation, then the operation has to ensure that it
 * cannot be called more than once with same parameters, e.g. operation creates an entity that has id
 * that is derived from operation parameters.
 */

function is_evm_signatures_authorized_operation(name): boolean {
    val whitelisted_operations = set([
        "ft4.register_account",
        "ft4.add_auth_descriptor",
        "ft4.update_main_auth_descriptor"
    ]);

    if (chain_context.args.evm_signatures_authorized_operations??) {
        whitelisted_operations.add_all(require(
            try_call(set<text>.from_gtv(chain_context.args.evm_signatures_authorized_operations!!, *)),
            "Cannot parse 'evm_signatures_authorized_operations' config parameter"
        ));
    }

    return name in whitelisted_operations;
}

function require_evm_signatures_can_be_used() {
    val all_operations = op_context.get_all_operations();

    require(
        all_operations.size() > op_context.op_index+1,
        "Cannot find an operation to authorize with 'ft4.evm_signatures'"
    );
    var next_op = all_operations[op_context.op_index+1];

    var op_to_authorize: gtx_operation?;
    if (not (is_auth_op(next_op) or strategies.is_strategy_op(next_op))) {
        op_to_authorize = next_op;
    } else {
        require(
            all_operations.size() > op_context.op_index+2,
            "Cannot find an operation to authorize with 'ft4.evm_signatures'"
        );
        op_to_authorize = all_operations[op_context.op_index+2];
    }

    require(
        is_evm_signatures_authorized_operation(op_to_authorize.name),
        "Cannot authorize operation <%s> with evm_signatures".format(op_to_authorize.name)
    );
}

import ^.assets;
import ^.accounts;

val ACCOUNT_TYPE_BLOCKCHAIN = "FT4_BLOCKCHAIN";

entity asset_origin {
   key assets.asset;
   origin_blockchain_rid: byte_array;
}

function is_blockchain(account_id: byte_array): boolean {
   return accounts.account @? { .id == account_id, .type == ACCOUNT_TYPE_BLOCKCHAIN }??;
}

function ensure_blockchain_account(blockchain_rid: byte_array) =
   accounts.ensure_account_without_auth(blockchain_rid, ACCOUNT_TYPE_BLOCKCHAIN);

namespace Unsafe {
    function register_crosschain_asset(
        name,
        symbol: text,
        decimals: integer,
        issuing_blockchain_rid: byte_array,
        icon_url: text,
        origin_blockchain_rid: byte_array
    ): asset_origin {
        require(origin_blockchain_rid.size() > 0, "origin_blockchain_rid cannot be empty");
        val asset = assets.Unsafe.register_asset(
                name,
                symbol,
                decimals,
                issuing_blockchain_rid,
                icon_url
            );
        return create asset_origin(asset, origin_blockchain_rid);
    }
}

@extendable function before_init_transfer(
    sender: accounts.account,
    recipient_id: byte_array,
    assets.asset,
    amount: big_integer,
    hops: list<byte_array>,
    deadline: timestamp
);

@extendable function after_init_transfer(
    sender: accounts.account,
    recipient_id: byte_array,
    assets.asset,
    amount: big_integer,
    hops: list<byte_array>,
    deadline: timestamp,
    pending_transfer
);

@extendable function before_apply_transfer(
    sender_blockchain_rid: byte_array,
    sender_account_id: byte_array,
    recipient_id: byte_array,
    assets.asset,
    amount: big_integer,
    hop_index: integer,
    is_final: boolean
);

@extendable function after_apply_transfer(
    sender_blockchain_rid: byte_array,
    sender_account_id: byte_array,
    recipient_id: byte_array,
    assets.asset,
    amount: big_integer,
    hop_index: integer,
    is_final: boolean,
    applied_transfers
);

@mount('ft4.crosschain')
module;

import ^^.utils;
import ^^.core.assets;

@extendable
function is_create_on_crosschain_transfer_enabled(): boolean = false;

@extendable
function create_on_crosschain_transfer(
   sender_blockchain_rid: byte_array,
   sender_id: byte_array,
   recipient_id: byte_array,
   assets.asset,
   amount: big_integer
);

@extendable
function recall_on_crosschain_transfer(
    sender_blockchain_rid: byte_array,
    sender_id: byte_array,
    transfer_tx_rid: byte_array,
    transfer_op_index: integer
);

function get_paginated_pending_transfers(account_id: byte_array, page_size: integer?, page_cursor: text?) {
    val after_rowid = utils.before_rowid(page_cursor);

    return pending_transfer @* {
        .sender.id == account_id,
        .rowid > (after_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data = (
                tx_data = .transaction.tx_data,
                op_index = .op_index,
                account_id = .sender.id
            ).to_gtv_pretty(),
            rowid = .rowid
        )
    ) limit utils.fetch_data_size(page_size);
}

function get_last_pending_transfer_for_account(
    sender_id: byte_array, 
    target_blockchain_rid: byte_array, 
    recipient_id: byte_array, 
    asset_id: byte_array, 
    amount: big_integer
) = (
    pt: pending_transfer, 
    cth: assets.crosschain_transfer_history_entry
) @? {
    cth.blockchain_rid == target_blockchain_rid,
    cth.account_id == recipient_id,
    cth.asset.id == asset_id,
    cth.delta == amount,
    cth.is_input == false,

    pt.sender.id == sender_id,
    pt.transaction == cth.transaction,
    pt.op_index == cth.op_index
} (
    @omit @sort_desc pt.rowid,
    tx_data = pt.transaction.tx_data,
    op_index = pt.op_index,
    account_id = pt.sender.id
) limit 1;

import ^.assets;
import ^.accounts;

entity applied_transfers {
    key init_tx_rid, init_op_index;
    init_tx_rid: byte_array;
    init_op_index: integer;
    transaction;
    op_index: integer;
}

entity canceled_transfers {
    key init_tx_rid, init_op_index;
    init_tx_rid: byte_array;
    init_op_index: integer;
}

entity unapplied_transfers {
    key init_tx_rid, init_op_index;
    init_tx_rid: byte_array;
    init_op_index: integer;
}

entity recalled_transfers {
    key init_tx_rid, init_op_index;
    init_tx_rid: byte_array;
    init_op_index: integer;
}

entity pending_transfer {
    key transaction, op_index; 
    op_index: integer;
    index sender: accounts.account;
}

entity reverted_transfer {
    key init_tx_rid, init_op_index;
    init_tx_rid: byte_array;
    init_op_index: integer;
}

namespace Unsafe {

    function update_balances_if_needed(
        sender: accounts.account,
        recipient: accounts.account,
        assets.asset,
        amount: big_integer
    ) {
        require(
            sender != recipient,
            "Cannot transfer to own account"
        );
        require(
            chain_context.blockchain_rid != sender.id,
            "Cannot transfer from this blockchain's account"
        );
        require(
            chain_context.blockchain_rid != recipient.id,
            "Cannot transfer to this blockchain's account"
        );
        assets.require_zero_exclusive_asset_amount_limits(
            amount,
            "Parameter amount"
        );

        val origin_blockchain_rid = asset_origin @? { asset } .origin_blockchain_rid;
        val is_sender_blockchain =  sender.type == ACCOUNT_TYPE_BLOCKCHAIN;
        val is_recipient_blockchain = recipient.type == ACCOUNT_TYPE_BLOCKCHAIN;

        if (
            not exists(origin_blockchain_rid)
            or not is_sender_blockchain
            or origin_blockchain_rid != sender.id
        ) {
            assets.deduct_balance(
                sender,
                asset, 
                amount
            );
        }

        create assets.transfer_history_entry(
            .account = sender,
            .asset = asset,
            .delta = amount,
            .op_index = op_context.op_index,
            .is_input = true
        );

        if (
            not exists(origin_blockchain_rid)
            or not is_recipient_blockchain
            or origin_blockchain_rid != recipient.id
        ) {
            assets.increase_balance(recipient, asset, amount);
        }

        create assets.transfer_history_entry(
            .account = recipient,
            .asset = asset,
            .delta = amount,
            .op_index = op_context.op_index,
            .is_input = false
        );
    }
}

@mount('ft4')
module;

import ^^.core.accounts;
import ^^.core.auth;
import ^^.utils;

function delete_auth_descriptor_message(gtv) {
    val params = struct<delete_auth_descriptor>.from_gtv(gtv);
    return "Please sign the message\nto delete auth descriptor:\n%s\n\nfrom account\n{account_id}".format(params.auth_descriptor_id);
}

function delete_auth_descriptor_resolver(args: gtv, account_id: byte_array, auth_descriptor_ids: list<byte_array>) {
    val params = struct<delete_auth_descriptor>.from_gtv(args);
    if (params.auth_descriptor_id in auth_descriptor_ids) return params.auth_descriptor_id;

    for (ad in accounts.account_auth_descriptor @* { .account.id == account_id, .id in auth_descriptor_ids }) {
        if (accounts.has_flags(ad, ["A"])) return ad.id;
    }

    return null;
}

@extend(auth.auth_handler)
function () = auth.add_overridable_auth_handler(
    scope = rell.meta(delete_auth_descriptor).mount_name,
    flags = [],
    message = delete_auth_descriptor_message(*),
    resolver = delete_auth_descriptor_resolver(*)
);

operation delete_auth_descriptor(auth_descriptor_id: byte_array) {
    val account = auth.authenticate();
    accounts.delete_auth_descriptor(
        accounts.auth_descriptor_by_id(account, auth_descriptor_id)
    );
}

function delete_auth_descriptors_for_signer_message(gtv) {
    val params = struct<delete_auth_descriptors_for_signer>.from_gtv(gtv);
    return "Please sign the message\nto delete all auth descriptor for signer:\n%s\n\nfrom account\n{account_id}".format(params.signer);
}

function delete_auth_descriptors_for_signer_resolver(args: gtv, account_id: byte_array, auth_descriptor_ids: list<byte_array>) {
    val params = struct<delete_auth_descriptors_for_signer>.from_gtv(args);

    val ads = (a_ad: accounts.account_auth_descriptor, ad_s: accounts.auth_descriptor_signer) @* {
        a_ad.account.id == account_id,
        ad_s.account_auth_descriptor == a_ad,
        ad_s.id == params.signer,
        a_ad.auth_type == accounts.auth_type.S,
        a_ad.id in auth_descriptor_ids
    } (a_ad.id);
    if (not ads.empty()) {
        return ads[0];
    }

    for (ad in accounts.account_auth_descriptor @* { .account.id == account_id, .id in auth_descriptor_ids }) {
        if (accounts.has_flags(ad, ["A"])) return ad.id;
    }

    return null;
}

@extend(auth.auth_handler)
function () = auth.add_overridable_auth_handler(
    scope = rell.meta(delete_auth_descriptors_for_signer).mount_name,
    flags = [],
    message = delete_auth_descriptors_for_signer_message(*),
    resolver = delete_auth_descriptors_for_signer_resolver(*)
);

operation delete_auth_descriptors_for_signer(signer: byte_array) {
    val account = auth.authenticate();

    val ads = (a_ad: accounts.account_auth_descriptor, ad_s: accounts.auth_descriptor_signer) @* {
        a_ad.account == account,
        ad_s.account_auth_descriptor == a_ad,
        ad_s.id == signer
    } (a_ad);
    for (ad in ads) {
        accounts.delete_auth_descriptor(ad);
    }
}

function delete_all_auth_descriptors_except_main_message(gtv) {
    return "Please sign the message\nto delete all auth descriptors except main:\n%s\n\n from account:\n{account_id}";
}

function delete_all_auth_descriptors_except_main_resolver(args: gtv, account_id: byte_array, auth_descriptor_ids: list<byte_array>) {
    val main_auth_descriptor = require(
        accounts.main_auth_descriptor @? { .account.id == account_id } .auth_descriptor,
        "Account <%s> does not have main auth descriptor set".format(account_id)
    );

    return if (main_auth_descriptor.id in auth_descriptor_ids) main_auth_descriptor.id else null;
}

@extend(auth.auth_handler)
function () = auth.add_overridable_auth_handler(
    scope = rell.meta(delete_all_auth_descriptors_except_main).mount_name,
    flags = ["A"],
    message = delete_all_auth_descriptors_except_main_message(*),
    resolver = delete_all_auth_descriptors_except_main_resolver(*)
);

operation delete_all_auth_descriptors_except_main() {
    val account = auth.authenticate();
    accounts.delete_all_auth_descriptors_except_main(account);
}

function add_auth_descriptor_message(gtv) {
    val params = struct<add_auth_descriptor>.from_gtv(gtv);
    val flags = params.new_desc.args[0];

    return "Please sign the message\nto add auth descriptor\nwith flags:\n%s\n\nto account:\n{account_id}".format(flags);
}

@extend(auth.auth_handler)
function () = auth.add_overridable_auth_handler(
    scope = rell.meta(add_auth_descriptor).mount_name,
    flags = ["A"],
    message = add_auth_descriptor_message(*)
);

operation add_auth_descriptor(new_desc: accounts.auth_descriptor) {
    val account = auth.authenticate();
    val signers = accounts.get_signers(new_desc);
    auth.verify_signers(signers);
    accounts.add_auth_descriptor(account, new_desc);
}

function update_main_auth_descriptor_message(gtv) {
    val params = struct<update_main_auth_descriptor>.from_gtv(gtv);
    val flags = params.new_desc.args[0];
    val signers = accounts.get_signers(params.new_desc);

    return "Please sign the message to\nset new main auth descriptor\n\nwith flags:\n%s\n\nand signers:\n%s\n\nof account:\n{account_id}".format(flags, signers);
}

function update_main_auth_descriptor_resolver(args: gtv, account_id: byte_array, auth_descriptor_ids: list<byte_array>) {
    val main_auth_descriptor = require(
        accounts.main_auth_descriptor @? { .account.id == account_id } .auth_descriptor,
        "Account <%s> does not have main auth descriptor set".format(account_id)
    );

    return if (main_auth_descriptor.id in auth_descriptor_ids) main_auth_descriptor.id else null;
}

@extend(auth.auth_handler)
function () = auth.add_overridable_auth_handler(
    scope = rell.meta(update_main_auth_descriptor).mount_name,
    flags = ["A"],
    message = update_main_auth_descriptor_message(*),
    resolver = update_main_auth_descriptor_resolver(*)
);

operation update_main_auth_descriptor(new_desc: accounts.auth_descriptor) {
    val account = auth.authenticate();
    auth.verify_signers(accounts.get_signers(new_desc));
    accounts.update_main_auth_descriptor(account, new_desc);
}

query get_config() {
    return (
        rate_limit = accounts.get_rate_limit_config(),
        auth_descriptor = accounts.get_auth_descriptor_config()
    );
}

query get_account_rate_limit_last_update(account_id: byte_array) {
    val account = accounts.Account(account_id);
    if (accounts.get_rate_limit_config_for_account(account).active == false) return (points = 0, last_update = 0);

    return accounts.rl_state @ { account }
    (
        .points, 
        .last_update
    );
}

query is_auth_descriptor_valid(account_id: byte_array, auth_descriptor_id: byte_array) {
    return not accounts.have_violating_rules(accounts.account_auth_descriptor @ {
        .account.id == account_id,
        .id == auth_descriptor_id
    });
}

query get_account_auth_descriptors(id: byte_array) {
    return accounts.get_auth_descriptors(id);
}

query get_account_auth_descriptors_by_signer(account_id: byte_array, signer: byte_array) {
    return accounts.get_auth_descriptors_by_signer(account_id, signer);
}

query get_account_auth_descriptor_by_id(account_id: byte_array, id: byte_array) {
    return accounts.account_auth_descriptor @ {
        .id == id,
        .account.id == account_id
    } ( accounts.get_auth_descriptor_data($.to_struct()) );
}

query get_account_main_auth_descriptor(account_id: byte_array) {
    return accounts.main_auth_descriptor @ {
        .account.id == account_id
    } ( accounts.get_auth_descriptor_data(.auth_descriptor.to_struct()) );
}

query get_account_by_id(id: byte_array) {
    return accounts.account @? { id } ( .id );
}

query get_account_by_auth_descriptor(accounts.auth_descriptor) {
    return accounts.account @? { .id == auth_descriptor.hash() } ( .id );
}

query get_accounts_by_signer(id: byte_array, page_size: integer?, page_cursor: text?) {
    return utils.make_page(
        accounts.get_paginated_accounts_by_signer(id, page_size, page_cursor),
        page_size
    );
}

query get_accounts_by_auth_descriptor_id(id: byte_array, page_size: integer?, page_cursor: text?) {
    return utils.make_page(
        accounts.get_paginated_accounts_by_ad_id(id, page_size, page_cursor),
        page_size
    );
}

query get_accounts_by_type(type: text, page_size: integer, page_cursor: text?) {
    return utils.make_page(
        accounts.get_paginated_accounts_by_type(type, page_size, page_cursor),
        page_size
    );
}

query get_auth_descriptor_counter(
    account_id: byte_array, 
    auth_descriptor_id: byte_array
) = accounts.account_auth_descriptor @? { 
        .account.id == account_id, 
        .id == auth_descriptor_id 
    } ( .ctr );

@mount('ft4')
module;

import ^^^.core.accounts.strategies;
import ^^^.core.accounts;
